window.QBANK={"1":[{"y":2015,"e":"지방직 9급","qn":1,"i":"L92015-01-1","t":"납세고지서, 납부통지서, 독촉장 또는 납부최고서를 송달한 때로서 해당 서류가 납부기한이 지난 후에 도달되거나 도달한 날부터 7일 이내에 납부기한이 도래하는 경우에는 그 도달한 날부터 14일이 지난 날을 납부기한으로 한다. 다만, 납기 전 징수의 경우는 별도의 규정에 따른다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2015,"e":"지방직 9급","qn":1,"i":"L92015-01-2","t":"송달하는 서류는 그 송달을 받아야 할 자에게 도달한 때부터 효력이 발생한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2015,"e":"지방직 9급","qn":1,"i":"L92015-01-3","t":"서류를 전자송달하는 경우에는 송달받을 자가 지정한 전자우편 주소에 입력된 것을 그 송달받을 자가 확인한 때에 도달된 것으로 본다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2015,"e":"지방직 9급","qn":1,"i":"L92015-01-4","t":"서류를 공시송달하는 경우에는 그 서류의 요지를 공고한 날부터 14일이 지나면 서류의 송달이 된 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2015,"e":"지방직 9급","qn":2,"i":"L92015-02-1","t":"납부기한 만료일 10일 전에 행한 납세자의 납부기한연장신청에 대하여 지방자치단체의 장이 신청일부터 10일 이내에 승인 여부를 통지하지 않으면 그 10일이 되는 날에 납부기한의 연장을 승인한 것으로 본다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 천재지변 등으로 인한 기한의 연장"},{"y":2015,"e":"지방직 9급","qn":2,"i":"L92015-02-2","t":"기한연장의 기간은 그 기한연장을 결정한 날의 다음 날부터 6개월 이내로 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 천재지변 등으로 인한 기한의 연장"},{"y":2015,"e":"지방직 9급","qn":2,"i":"L92015-02-3","t":"지방자치단체의 장은 기한을 연장한 후에도 3개월을 넘지 아니 하는 범위에서 한 차례에 한정하여 그 기한을 연장할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 천재지변 등으로 인한 기한의 연장"},{"y":2015,"e":"지방직 9급","qn":2,"i":"L92015-02-4","t":"기한이 연장된 후 한 차례 더 기한이 연장된 경우 그 연장된 기간 중의 분납기한 및 분납금액은 지방자치단체의 장이 정하되, 가능한 한 매회 같은 금액을 분납할 수 있도록 정하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 천재지변 등으로 인한 기한의 연장"},{"y":2015,"e":"지방직 9급","qn":9,"i":"L92015-09-1","t":"비상장 상태인 합명회사나 합자회사의 무한책임사원은 제2차 납세의무를 진다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 출자자의 제2차납세의무"},{"y":2015,"e":"지방직 9급","qn":9,"i":"L92015-09-2","t":"주식회사의 경우 주주 1인과 그의 특수관계인의 지분 합계가 50 % 미만인 경우 그들은 제2차납세의무를 지는 과점주주에 해당되지 않는다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 출자자의 제2차납세의무"},{"y":2015,"e":"지방직 9급","qn":9,"i":"L92015-09-3","t":"제2차납세의무를 지는 과점주주 여부의 판단은 해당 징수금의 과세기준일 또는 납세의무성립일 현재를 기준으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 출자자의 제2차납세의무"},{"y":2015,"e":"지방직 9급","qn":9,"i":"L92015-09-4","t":"제2차납세의무의 적용대상에서 상장법인은 제외되므로 코스닥 상장법인의 출자자는 제2차납세의무를 지지 않는다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 출자자의 제2차납세의무"},{"y":2015,"e":"지방직 9급","qn":11,"i":"L92015-11-1","t":"지방소비세는 과세대상 재화와 용역을 소비하는 자의 주소지 또는 소재지를 관할하는 도에서 부가가치세법에 따라 부가 가치세를 납부할 의무가 있는 자에게 부과한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 세목과 납세의무자"},{"y":2015,"e":"지방직 9급","qn":11,"i":"L92015-11-2","t":"외국으로부터 입국하는 사람의 휴대품 또는 탁송품·별송품으로 담배가 반입될 때에는 그 반입한 사람이 담배소비세를 납부할 의무가 있다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 세목과 납세의무자"},{"y":2015,"e":"지방직 9급","qn":11,"i":"L92015-11-3","t":"주민세 종업원분의 납세의무자는 급여를 받는 종업원으로 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 세목과 납세의무자"},{"y":2015,"e":"지방직 9급","qn":11,"i":"L92015-11-4","t":"레저세의 과세대상 사업을 하는 자는 해당 과세대상 사업장과 장외발매소가 있는 지방자치단체에 각각 레저세를 납부할 의무가 있다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 세목과 납세의무자"},{"y":2015,"e":"지방직 9급","qn":18,"i":"L92015-18-1","t":"납세자가 법정신고기한까지 법인세의 과세표준신고서를 제출 하지 아니하여 해당 지방소득세를 부과할 수 없는 경우(조세 조약에 따라 상호합의절차가 진행 중인 경우가 아님)에 지방 소득세의 부과제척기간은 이를 부과할 수 있는 날부터 5년이 되는 날까지로 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 제척기간, 소멸시효 및 결손처분"},{"y":2015,"e":"지방직 9급","qn":18,"i":"L92015-18-2","t":"지방세징수권은 가산세를 제외한 지방세의 금액이 5천만원 미만인 경우 그 권리를 행사할 수 있는 때부터 5년간 행사하지 아니하면 시효로 인하여 소멸한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 제척기간, 소멸시효 및 결손처분","t0":"지방세징수권은 그 권리를 행사할 수 있는 때부터 5년간 행사 하지 아니하면 시효로 인하여 소멸한다.","ox0":"O","rv":"개정 반영"},{"y":2015,"e":"지방직 9급","qn":18,"i":"L92015-18-3","t":"지방세징수권의 시효에 관하여는 지방세기본법 또는 지방세 관계법에 규정되어 있는 것을 제외하고는 민법을 따른다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 제척기간, 소멸시효 및 결손처분"},{"y":2015,"e":"지방직 9급","qn":18,"i":"L92015-18-4","t":"지방자치단체의 장은 지방세징수권의 소멸시효가 완성되어 결손처분한 경우를 제외하고, 결손처분을 한 후 압류할 수 있는 다른 재산을 발견하였을 때에는 지체 없이 그 처분을 취소하고 체납처분을 하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 제척기간, 소멸시효 및 결손처분"},{"y":2015,"e":"지방직 9급","qn":19,"i":"L92015-19-1","t":"여신전문금융업법에 따른 시설대여업자가 건설기계나 차량의 시설대여를 하는 경우로서 같은 법에 따라 대여시설이용자의 명의로 등록하는 경우라도 그 건설기계나 차량은 시설대여 업자가 취득한 것으로 본다.","ox":"O","m":"①","c":"A","tp":"지방세법"},{"y":2015,"e":"지방직 9급","qn":19,"i":"L92015-19-2","t":"차고용 토지, 보세창고용 토지, 시험·연구·검사용 토지, 물류 단지시설용 토지 등 공지상태나 해당 토지의 이용에 필요한 시설 등을 설치하여 업무에 사용되는 토지로서 대통령령으로 정하는 토지는 재산세 분리과세대상이다.","ox":"X","m":"②","c":"A","tp":"지방세법"},{"y":2015,"e":"지방직 9급","qn":19,"i":"L92015-19-3","t":"종합부동산세 과세에 필요한 재산세 과세자료 등의 수집·처리 및 제공을 위하여 행정안전부에 종합부동산세 과세자료 전담 기구를 설치한다.","ox":"O","m":"③","c":"A","tp":"지방세법","t0":"종합부동산세 과세에 필요한 재산세 과세자료 등의 수집·처리 및 제공을 위하여 행정자치부에 종합부동산세 과세자료 전담 기구를 설치한다.","ox0":"O","rv":"행정자치부에→행정안전부에"},{"y":2015,"e":"지방직 9급","qn":19,"i":"L92015-19-4","t":"지방자치단체의 장은 취득세 납세의무가 있는 법인이 취득 당시의 가액을 증명할 수 있는 장부와 관련 증거서류를 작성 하여 갖춰 두지 않은 경우에는 산출된 세액 또는 부족세액의 100분의 10에 상당하는 금액을 징수하여야 할 세액에 가산한다.","ox":"O","m":"④","c":"A","tp":"지방세법"},{"y":2016,"e":"지방직 9급","qn":2,"i":"L92016-02","t":"지방세기본법 상 납세의무의 성립시기로 옳지 않은 것은?","c":"A","mc":{"s":"지방세기본법 상 납세의무의 성립시기로 옳지 않은 것은?","d":"(단, 수시부과사유는 없음)","o":["종업원분 주민세: 과세기준일","지방소비세: 국세기본법 에 따른 부가가치세의 납세의무가 성립하는 때","레저세: 승자투표권, 승마투표권 등을 발매하는 때","특별징수하는 지방소득세: 그 과세표준이 되는 소득에 대하여 소득세․법인세를 원천징수하는 때"],"a":1}},{"y":2016,"e":"지방직 9급","qn":3,"i":"L92016-03-1","t":"교부로 서류를 송달하는 경우 송달할 장소에서 서류의 송달을 받아야 할 자를 만나지 못하였을 때에는 그 사용인, 그 밖의 종업원 또는 동거인으로서 사리를 판별할 수 있는 사람에게 서류를 송달할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2016,"e":"지방직 9급","qn":3,"i":"L92016-03-2","t":"우편송달의 경우 송달하는 서류는 그 송달을 받아야 할 자에게 발송한 때부터 효력이 발생한다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2016,"e":"지방직 9급","qn":3,"i":"L92016-03-3","t":"전자송달의 경우에는 송달받을 자가 지정한 전자우편주소에 입력된 때 또는 지방세정보통신망의 전자사서함에 저장하는 경우에는 저장된 때에 송달의 효력이 발생한 것으로 본다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2016,"e":"지방직 9급","qn":3,"i":"L92016-03-4","t":"서류의 송달을 받아야 할 자의 주소 또는 영업소가 국외에 있고 그 송달이 곤란한 경우에는 서류의 요지를 공고한 날부터 14일이 지나면 서류의 송달이 된 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2016,"e":"지방직 9급","qn":8,"i":"L92016-08-1","t":"지방세기본법 또는 지방세관계법에 따른 법정신고기한까지 과세표준신고서를 제출하지 않은 자는 수정신고를 할 수 없다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 수정신고 및 경정 등의 청구"},{"y":2016,"e":"지방직 9급","qn":8,"i":"L92016-08-2","t":"지방세의 법정신고기한이 지난 후에 발생한 사유를 근거로 경정청구를 할 수 있는 경우가 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 수정신고 및 경정 등의 청구"},{"y":2016,"e":"지방직 9급","qn":8,"i":"L92016-08-3","t":"경정청구를 받은 지방자치단체의 장은 그 청구를 받은 날부터 2개월 이내에 과세표준 및 세액을 경정하거나 경정하여야 할 이유가 없다는 것을 그 청구를 한 자에게 통지하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 수정신고 및 경정 등의 청구"},{"y":2016,"e":"지방직 9급","qn":8,"i":"L92016-08-4","t":"수정신고로 인하여 추가납부할 세액이 있는 경우 수정신고와 동시에 해당 세액을 납부하지 아니하는 경우에는 수정신고로 인한 과소신고가산세를 감면하지 아니한다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 수정신고 및 경정 등의 청구"},{"y":2016,"e":"지방직 9급","qn":9,"i":"L92016-09-1","t":"납세자의 재산을 지방자치단체의 징수금의 체납처분에 따라 압류한 경우 다른 지방자치단체의 징수금 또는 국세의 교부 청구가 있으면 압류에 관계되는 지방자치단체의 징수금은 교부 청구한 다른 지방자치단체의 징수금 또는 국세에 우선하여 징수한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세와 타 채권과의 관계"},{"y":2016,"e":"지방직 9급","qn":9,"i":"L92016-09-2","t":"납세담보가 되어 있는 재산을 매각하였을 때에는 해당 지방 자치단체에서 다른 지방자치단체의 징수금과 국세에 우선하여 징수한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세와 타 채권과의 관계"},{"y":2016,"e":"지방직 9급","qn":9,"i":"L92016-09-3","t":"납세자의 재산을 지방자치단체의 징수금 체납을 이유로 체납 처분을 하였을 경우 그 체납처분비는 해당 재산에 납세담보가 설정되어 있는 다른 지방자치단체의 징수금과 국세 및 그 밖의 채권에 우선하여 징수한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 지방세와 타 채권과의 관계"},{"y":2016,"e":"지방직 9급","qn":9,"i":"L92016-09-4","t":"납세자에게 부과된 지방세의 법정기일 전에 해당 납세자의 부동산에 대하여 저당권이 설정되어 있는 경우 그 저당권에 의하여 담보된 채권은 그 납세자에게 부과된 모든 지방세보다 우선한다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 지방세와 타 채권과의 관계"},{"y":2016,"e":"지방직 9급","qn":13,"i":"L92016-13-1","t":"세무공무원은 세무조사를 하는 경우에 납세자권리헌장의 내용이 수록된 문서를 납세자에게 내주어야 하지만 지방세의 포탈에 따른 범칙사건조사의 경우에는 이를 생략할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2016,"e":"지방직 9급","qn":13,"i":"L92016-13-2","t":"세무공무원은 세무조사를 시작할 때 그 신분을 표시하는 증표를 납세자 또는 관계인에게 제시하여야 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2016,"e":"지방직 9급","qn":13,"i":"L92016-13-3","t":"납세자는 범칙사건의 조사 및 세무조사를 받는 경우 변호사, 공인회계사, 세무사로 하여금 조사에 참석하게 하거나 의견을 진술하게 할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2016,"e":"지방직 9급","qn":13,"i":"L92016-13-4","t":"납세자가 세무조사를 신청하는 경우에는 지방자치단체의 장은 정기선정에 의한 조사 외에도 세무조사를 할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2016,"e":"지방직 9급","qn":15,"i":"L92016-15-1","t":"지방세기본법에 따른 과태료 부과 행위에 대하여는 이의 신청을 할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2016,"e":"지방직 9급","qn":15,"i":"L92016-15-2","t":"이의신청은 그 처분의 집행에 효력이 미치지 아니하지만 압류한 재산에 대하여는 그 공매처분을 보류할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2016,"e":"지방직 9급","qn":15,"i":"L92016-15-3","t":"이의신청 또는 심사청구에 대한 결정에 오기, 계산착오, 그 밖에 이와 비슷한 잘못이 있는 것이 명백할 때에는 시장·군수 또는 도지사는 직권 또는 이의신청인·심사청구인의 신청을 받아 지방세심의위원회의 의결을 거쳐 결정을 경정할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2016,"e":"지방직 9급","qn":15,"i":"L92016-15-4","t":"심판청구가 있는 경우 처분청은 그 청구에 관계되는 서류를 열람할 수 있으며 대통령령으로 정하는 바에 따라 조세심판원장에게 의견을 진술할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2016,"e":"지방직 9급","qn":19,"i":"L92016-19","t":"다음 중 지방세법 상 부동산 등의 시가표준액에 대한 설명으로 옳은 것만을 고른 것은?","c":"A","mc":{"s":"다음 중 지방세법 상 부동산 등의 시가표준액에 대한 설명으로 옳은 것만을 고른 것은?","d":"ㄱ. 부동산 가격공시 및 감정평가에 관한 법률 (이하 ‘부동산 가격공시법’이라 함)에 의하여 개별공시지가가 공시되지 않은 토지의 경우에는 이 법에 따라 국토교통부장관이 제공한 토지가격비준표를 사용하여 시장․군수 또는 자치구의 구청장(이하 ‘시장․군수’라 함)이 산정한 가액을 그 토지의 시가표준액으로 한다.\nㄴ. 부동산가격공시법에 의하여 개별주택가격이 공시되지 않은 경우에는 대통령령으로 정하는 기준에 따라 시장․ 군수가 산정한 가액을 그 주택의 시가표준액으로 한다.\nㄷ. 부동산가격공시법에 의하여 공동주택가격이 공시되지 않은 경우에는 대통령령으로 정하는 기준에 따라 시장․ 군수가 산정한 가액을 그 주택의 시가표준액으로 한다.\nㄹ. 주택 이외의 건축물의 경우에는 국세청장이 정하는 가액을 그 건축물의 시가표준액으로 한다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":2}},{"y":2017,"e":"지방직 9급","qn":1,"i":"L92017-01-1","t":"지방세징수권의 소멸시효는 지방세징수법에 따른 징수유예 기간에는 진행되지 아니한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세 부과의 제척기간과 지방세징수권의 소멸시효"},{"y":2017,"e":"지방직 9급","qn":1,"i":"L92017-01-2","t":"지방세 부과의 제척기간에도 불구하고 행정소송에 대한 판결이 확정된 날부터 1년이 지나기 전까지는 해당 판결에 따라 경정결정이나 그 밖에 필요한 처분을 할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세 부과의 제척기간과 지방세징수권의 소멸시효"},{"y":2017,"e":"지방직 9급","qn":1,"i":"L92017-01-3","t":"지방세징수권의 소멸시효는 납세고지, 독촉 또는 납부최고, 교부청구, 압류로 중단된다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 지방세 부과의 제척기간과 지방세징수권의 소멸시효"},{"y":2017,"e":"지방직 9급","qn":1,"i":"L92017-01-4","t":"납세자가 사기나 그 밖의 부정한 행위로 지방세를 포탈하거나 환급·공제 또는 감면받은 경우 그 지방세 부과의 제척기간은 7년이다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 지방세 부과의 제척기간과 지방세징수권의 소멸시효"},{"y":2017,"e":"지방직 9급","qn":3,"i":"L92017-03","t":"지방세징수법 상 지방자치단체의 장이 납세자가 지방자치단체의 징수금을 납부할 수 없다고 인정하여 징수유예등을 결정할 수 있는 사유에 해당하는 경우는 모두 몇 개인가?","c":"A","mc":{"s":"지방세징수법 상 지방자치단체의 장이 납세자가 지방자치단체의 징수금을 납부할 수 없다고 인정하여 징수유예등을 결정할 수 있는 사유에 해당하는 경우는 모두 몇 개인가?","d":"○ 사업에 현저한 손실을 입은 경우\n○ 사업이 중대한 위기에 처한 경우\n○ 납세자의 동거가족이 중상해(重傷害)로 장기치료를 받아야 하는 경우\n○ 풍수해, 벼락, 화재, 전쟁, 그 밖의 재해 또는 도난으로 재산에 심한 손실을 입은 경우","o":["1개","2개","3개","4개"],"a":4}},{"y":2017,"e":"지방직 9급","qn":4,"i":"L92017-04","t":"지방세기본법 상 법정신고기한이 지난 후 법령에 따른 수정 신고를 하여 지방자치단체의 장이 과소신고가산세․초과환급신고 가산세를 감면하는 경우 그 감면금액으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세기본법 상 법정신고기한이 지난 후 법령에 따른 수정 신고를 하여 지방자치단체의 장이 과소신고가산세․초과환급신고 가산세를 감면하는 경우 그 감면금액으로 옳지 않은 것은?","d":"(단, 지방자치단체의 장이 과세표준과 세액을 경정할 것을 미리 알고 과세표준 수정신고서를 제출한 경우는 제외한다)","o":["1년 8개월 만에 수정신고한 경우: 해당 가산세액의 100분의 5에 상당하는 금액","1년 3개월 만에 수정신고한 경우: 해당 가산세액의 100분의 10에 상당하는 금액","7개월 5일 만에 수정신고한 경우: 해당 가산세액의 100분의 20에 상당하는 금액","25일 만에 수정신고한 경우: 해당 가산세액의 100분의 50에 상당하는 금액"],"a":1}},{"y":2017,"e":"지방직 9급","qn":10,"i":"L92017-10-1","t":"지방세기본법 및 지방세관계법의 해석 또는 지방세 행정의 관행이 일반적으로 납세자에게 받아들여진 후에는 그 해석 또는 관행에 따른 행위나 계산은 정당한 것으로 보며, 이와 달리 소급하여 과세하기 위해서는 새로운 해석이나 지침이 공표되어야 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2017,"e":"지방직 9급","qn":10,"i":"L92017-10-2","t":"납세의무자가 지방세관계법에 따라 장부를 갖추어 기록하고 있을 때에는 해당 지방세의 과세표준 조사 및 결정은 기록한 장부와 이에 관계되는 증거자료에 따라야 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2017,"e":"지방직 9급","qn":10,"i":"L92017-10-3","t":"지방자치단체는 법령에 따라 기록 내용과 다른 사실이나 누락된 것을 조사하여 결정하였으면 지방자치단체가 조사한 사실과 결정의 근거를 결정서에 덧붙여 적어야 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2017,"e":"지방직 9급","qn":10,"i":"L92017-10-4","t":"지방세기본법 또는 지방세관계법 중 과세표준 또는 세액의 계산에 관한 규정은 소득·수익·재산·행위 또는 거래의 명칭이나 형식에 관계없이 그 실질내용에 따라 적용한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2017,"e":"지방직 9급","qn":11,"i":"L92017-11","t":"지방세법 상 지방세의 징수방법으로 특별징수제도가 있는 것으로만 묶은 것은?","c":"A","mc":{"s":"지방세법 상 지방세의 징수방법으로 특별징수제도가 있는 것으로만 묶은 것은?","d":"ㄱ. 취득세\nㄴ. 등록에 대한 등록면허세\nㄷ. 담배소비세\nㄹ. 주민세\nㅁ. 레저세\nㅂ. 자동차 주행에 대한 자동차세","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄹ, ㅁ","ㄴ, ㄷ, ㅂ","ㄹ, ㅁ, ㅂ"],"a":3}},{"y":2017,"e":"지방직 9급","qn":13,"i":"L92017-13","t":"지방세징수법 상 지방자치단체의 장이 압류를 즉시 해제하여야 하는 경우가 아닌 것은?","c":"A","mc":{"s":"지방세징수법 상 지방자치단체의 장이 압류를 즉시 해제하여야 하는 경우가 아닌 것은?","d":"","o":["압류할 수 있는 다른 재산을 체납자가 제공하여 그 재산을 압류하였을 때","제3자가 체납자를 상대로 소유권에 관한 소송을 제기하여 승소 판결을 받고 그 사실을 증명하였을 때","압류한 금융재산 중 한부모가족지원법 에 따른 복지급여로서 법률에 따라 압류가 금지된 재산임을 증명한 때","압류한 재산에 대한 제3자의 소유권 주장이 상당한 이유가 있다고 인정할 때"],"a":1}},{"y":2017,"e":"지방직 9급","qn":16,"i":"L92017-16-1","t":"과세전적부심사의 청구에 대한 처분이 위법·부당하여 권리 또는 이익을 침해당한 자는 이의신청, 심사청구 또는 심판 청구를 할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2017,"e":"지방직 9급","qn":16,"i":"L92017-16-2","t":"시장·군수·구청장으로부터 이의신청에 대한 결정 통지를 받은 자가 심사청구 또는 심판청구를 할 때에는 그 통지를 받은 날부터 90일 이내에 특별시장·광역시장·도지사에게 심사청구를 하거나 조세심판원장에게 심판청구를 하여야 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2017,"e":"지방직 9급","qn":16,"i":"L92017-16-3","t":"이의신청, 심사청구 또는 심판청구는 그 처분의 집행에 효력이 미치지 아니하지만, 압류한 재산에 대해서는 이의신청, 심사 청구 또는 심판청구의 결정이 있는 날부터 60일까지 그 공매 처분을 보류할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2017,"e":"지방직 9급","qn":16,"i":"L92017-16-4","t":"심사청구를 받은 지방자치단체의 장이 그 청구의 서식 또는 절차에 결함이 있어서 20일간의 보정기간을 정하여 문서로 그 결함의 보정을 요구한 경우 이에 따른 보정기간은 심사 청구에 대한 결정기간에 포함한다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 이의신청 및 심사청구와 심판청구"},{"y":2018,"e":"지방직 9급","qn":1,"i":"L92018-01","t":"지방세법 상 표준세율이 적용되는 지방세 세목이 아닌 것은?","c":"A","mc":{"s":"지방세법 상 표준세율이 적용되는 지방세 세목이 아닌 것은?","d":"","o":["취득세","지방소비세","재산세","법인균등분 주민세"],"a":2}},{"y":2018,"e":"지방직 9급","qn":4,"i":"L92018-04-1","t":"‘납세자’란 지방세법에 따라 지방세를 납부할 의무(지방세를 특별징수하여 납부할 의무는 제외)가 있는 자를 말한다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"지방직 9급","qn":4,"i":"L92018-04-2","t":"‘표준세율’이란 지방자치단체가 지방세를 부과할 경우에 통상 적용하여야 할 세율로서 조례에 의해서도 가감할 수 없는 세율을 말한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"지방직 9급","qn":4,"i":"L92018-04-4","t":"‘지방자치단체의 징수금’이란 지방세와 체납처분비를 말한다.","ox":"O","m":"④","c":"A","t0":"‘지방자치단체의 징수금’이란 지방세와 가산금 및 체납처분비를 말한다.","ox0":"O","rv":"개정 반영"},{"y":2018,"e":"지방직 9급","qn":8,"i":"L92018-08","t":"지방세기본법 상 지방세 납세의무의 성립시기에 대한 설명으로 옳지 않은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세기본법 상 지방세 납세의무의 성립시기에 대한 설명으로 옳지 않은 것만을 모두 고르면?","d":"ㄱ. 면허에 대한 등록면허세 － 각종 면허를 받는 때와 납기가 있는 달의 말일\nㄴ. 담배소비세－소비자가 소매점에서 담배를 구입하는 때\nㄷ. 지방소득세－과세표준이 되는 소득에 대하여 소득세․ 법인세의 납세의무가 성립하는 때\nㄹ. 자동차 주행에 대한 자동차세－납기가 있는 달의 1일\nㅁ. 원자력발전에 대한 지역자원시설세－원자력발전소에서 발전하는 때","o":["ㄱ, ㅁ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄹ, ㅁ"],"a":2}},{"y":2018,"e":"지방직 9급","qn":9,"i":"L92018-09-1","t":"법인이 해산한 경우에 그 법인에 부과되거나 그 법인이 납부할 지방자치단체의 징수금을 납부하지 아니하고 남은 재산을 분배하거나 인도하여, 그 법인에 대하여 체납처분을 집행 하여도 징수할 금액보다 적은 경우에는 청산인과 남은 재산을 분배받거나 인도받은 자는 그 부족한 금액에 대하여 한도 없이 제2차 납세의무를 진다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 제2차 납세의무"},{"y":2018,"e":"지방직 9급","qn":9,"i":"L92018-09-2","t":"사업의 양도·양수가 있는 경우 그 사업에 관하여 양도일 이전에 양도인의 납세의무가 확정된 지방자치단체의 징수금을 양도인의 재산으로 충당하여도 부족할 때에는 양수인은 그 부족한 금액에 대하여 양수한 재산의 가액 한도 내에서 제2차 납세의무를 진다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 제2차 납세의무"},{"y":2018,"e":"지방직 9급","qn":9,"i":"L92018-09-3","t":"지방세의 납부기한 종료일 현재 법인의 유한책임사원 또는 과점주주가 자신이 부담하여야 할 징수금에 대해 자신의 재산으로 충당하여도 부족한 경우 일정한 요건하에 그 법인은 제2차 납세의무를 진다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 제2차 납세의무"},{"y":2018,"e":"지방직 9급","qn":9,"i":"L92018-09-4","t":"법인(주식을 자본시장과 금융투자업에 관한 법률에 따른 증권시장으로서 대통령령으로 정하는 증권시장에 상장한 법인은 포함)의 재산으로 그 법인에 부과되거나 그 법인이 납부할 지방자치단체의 징수금에 충당하여도 부족한 경우에는 그 지방자치단체의 징수금의 과세기준일 또는 납세의무성립일 (이에 관한 규정이 없는 세목의 경우에는 납기개시일) 현재 출자자는 그 부족액에 대하여 제2차 납세의무를 진다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 제2차 납세의무"},{"y":2018,"e":"지방직 9급","qn":13,"i":"L92018-13-1","t":"연대납세의무자에게 납세의 고지와 독촉에 관한 서류를 송달하려면 그 대표자를 명의인으로 하며 대표자가 없을 때에는 연대납세 의무자 중 지방세를 징수하기 유리한 자를 명의인으로 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2018,"e":"지방직 9급","qn":13,"i":"L92018-13-2","t":"서류의 교부송달은 송달할 장소에서 그 송달을 받아야 할 자에게 서류를 건네줌으로써 이루어진다. 다만, 송달을 받아야 할 자가 송달받기를 거부하지 아니하면 다른 장소에서 교부할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2018,"e":"지방직 9급","qn":13,"i":"L92018-13-3","t":"서류를 교부 송달하는 경우, 송달할 장소에서 서류의 송달을 받아야 할 자를 만나지 못하였을 때에는 그의 사용인, 그 밖의 종업원 또는 동거인으로서 사리를 분별할 수 있는 사람에게 서류를 송달할 수 있으며, 서류의 송달을 받아야 할 자 또는 그의 사용인, 그 밖의 종업원 또는 동거인으로서 사리를 분별할 수 있는 사람이 정당한 사유 없이 서류의 수령을 거부하면 송달할 장소에 서류를 둘 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2018,"e":"지방직 9급","qn":13,"i":"L92018-13-4","t":"전자송달의 경우에는 송달받을 자가 지정한 전자우편주소에 저장된 때 또는 지방세정보통신망의 전자사서함에 저장된 때에 그 송달을 받아야 할 자에게 도달된 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2018,"e":"지방직 9급","qn":17,"i":"L92018-17-1","t":"법정신고기한까지 과세표준 신고서를 제출하지 아니한 자는 지방자치단체의 장이 과세표준과 세액을 결정할 것을 미리 안 경우에도 지방자치단체의 장이 지방세의 과세표준과 세액을 결정하여 통지하기 전에는 기한후신고서를 제출할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 기한 후 신고제도"},{"y":2018,"e":"지방직 9급","qn":17,"i":"L92018-17-2","t":"기한후신고서를 제출한 자로서 지방세관계법에 따라 납부하여야 할 세액이 있는 자는 기한후신고서의 제출과 동시에 그 세액을 납부하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 기한 후 신고제도"},{"y":2018,"e":"지방직 9급","qn":17,"i":"L92018-17-3","t":"기한후신고서를 제출받은 지방자치단체의 장은 과세표준과 세액을 조사할 때 조사 등에 장기간이 걸리는 등 부득이한 사유로 신고일부터 3개월 이내에 결정할 수 없는 경우에는 그 사유를 신고인에게 통지하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 기한 후 신고제도"},{"y":2018,"e":"지방직 9급","qn":17,"i":"L92018-17-4","t":"법정신고기한이 지난 후 1개월 이내에 기한 후 신고를 한 경우 (무신고가산세만 해당하며, 지방자치단체의 장이 과세표준과 세액을 결정할 것을 미리 알고 기한후신고서를 제출한 경우는 제외)에는 해당 가산세액의 100분의 50에 상당하는 금액을 감면한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 기한 후 신고제도"},{"y":2018,"e":"지방직 9급","qn":20,"i":"L92018-20-1","t":"해당 지방세의 법정신고기한이 지난 후 최초의 신고·결정 또는 경정을 할 때 과세표준 및 세액의 계산근거가 된 거래 또는 행위 등의 효력과 관계되는 계약이 해당 계약의 성립 후 발생한 부득이한 사유로 해제되거나 취소된 경우는 후발적 사유로 인한 경정 등의 청구 대상이 된다.","ox":"O","m":"①","c":"A","tp":"지방세기본법령상 경정 등의 청구"},{"y":2018,"e":"지방직 9급","qn":20,"i":"L92018-20-2","t":"지방세기본법 또는 지방세관계법에 따른 과세표준 신고서를 법정신고기한까지 제출한 자 또는 지방세의 과세표준 및 세액의 결정을 받은 자로서 조세조약에 따른 상호합의가 최초의 신고·결정 또는 경정의 내용과 다르게 이루어졌을 때는 그 사유가 발생한 날부터 3개월 이내에 결정 또는 경정을 청구할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세기본법령상 경정 등의 청구"},{"y":2018,"e":"지방직 9급","qn":20,"i":"L92018-20-3","t":"지방세기본법 제50조제1항 및 제2항에 따라 해당 지방자치 단체의 장에게 결정 또는 경정의 청구를 한 자가 청구한 날부터 2개월 이내에 아무런 통지를 받지 못한 경우에는 통지를 받기 전이라도 2개월이 되는 날의 다음 날부터 지방세 기본법 제7장에 따른 이의신청, 심사청구 또는 심판청구를 할 수 있으며, 이 경우 감사원법에 따른 심사청구는 할 수 없다.","ox":"X","m":"③","c":"A","tp":"지방세기본법령상 경정 등의 청구"},{"y":2018,"e":"지방직 9급","qn":20,"i":"L92018-20-4","t":"지방세기본법 또는 지방세관계법에 따른 과세표준 신고서를 법정신고기한까지 제출한 자로서 과세표준 신고서에 기재된 과세표준 및 세액이 신고하여야 할 과세표준 및 세액을 초과할 때 또는 환급세액이 신고하여야 할 환급세액보다 적을 때에는 법정신고기한이 지난 후 7년 이내에 결정 또는 경정을 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세기본법령상 경정 등의 청구"},{"y":2019,"e":"지방직 9급","qn":1,"i":"L92019-01","t":"지방세기본법 상 세무공무원이 그 사용 목적에 맞는 범위에서 납세자의 과세정보를 제공할 수 있는 경우에 해당하지 않는 것은?","c":"A","mc":{"s":"지방세기본법 상 세무공무원이 그 사용 목적에 맞는 범위에서 납세자의 과세정보를 제공할 수 있는 경우에 해당하지 않는 것은?","d":"","o":["공공기관이 급부․지원 등을 위한 자격심사에 필요한 과세 정보를 당사자의 동의를 받지 않고 요구하는 경우","국가기관이 조세쟁송을 할 목적으로 과세정보를 요구하는 경우","사회보장기본법 에 따른 사회보험의 운영을 목적으로 설립된 기관이 관련 법률에 따른 소관업무의 수행을 위하여 과세 정보를 요구하는 경우","국가데이터처장이 국가통계 작성 목적으로 과세정보를 요구하는 경우"],"a":1},"mc0":{"s":"지방세기본법 상 세무공무원이 그 사용 목적에 맞는 범위에서 납세자의 과세정보를 제공할 수 있는 경우에 해당하지 않는 것은?","d":"","o":["공공기관이 급부․지원 등을 위한 자격심사에 필요한 과세 정보를 당사자의 동의를 받지 않고 요구하는 경우","국가기관이 조세쟁송을 할 목적으로 과세정보를 요구하는 경우","사회보장기본법 에 따른 사회보험의 운영을 목적으로 설립된 기관이 관련 법률에 따른 소관업무의 수행을 위하여 과세 정보를 요구하는 경우","통계청장이 국가통계 작성 목적으로 과세정보를 요구하는 경우"],"a":1},"rv":"통계청→국가데이터처"},{"y":2019,"e":"지방직 9급","qn":6,"i":"L92019-06-1","t":"이의신청을 거친 후에 심사청구 또는 심판청구를 할 때에는 이의신청에 대한 결정 통지를 받은 날부터 30일 이내에 하여야 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 권리구제절차"},{"y":2019,"e":"지방직 9급","qn":6,"i":"L92019-06-2","t":"이의신청인, 심사청구인은 신청 또는 청구 금액이 1천만 원 미만인 경우에는 그의 배우자, 4촌 이내의 혈족 또는 그의 배우자의 4촌 이내 혈족을 대리인으로 선임할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 권리구제절차"},{"y":2019,"e":"지방직 9급","qn":6,"i":"L92019-06-3","t":"세무조사결과에 대한 서면 통지를 받은 자는 과세전적부심사를 청구하지 아니하고 그 통지를 한 지방자치단체의 장에게 통지받은 내용의 전부 또는 일부에 대하여 과세표준 및 세액을 조기에 결정 또는 경정결정을 해 줄 것을 신청할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 권리구제절차"},{"y":2019,"e":"지방직 9급","qn":6,"i":"L92019-06-4","t":"통고처분을 받은 자는 그 처분으로 인하여 권리 또는 이익을 침해당한 경우에도 이의신청, 심사청구 또는 심판청구를 할 수 없다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 권리구제절차"},{"y":2019,"e":"지방직 9급","qn":9,"i":"L92019-09","t":"지방세기본법령상 과세표준 신고서를 법정신고기한까지 제출한 자 또는 지방세의 과세표준 및 세액의 결정을 받은 자가 법정신고 기한으로부터 5년이 지난 후 사유가 발생한 것을 안 날부터 3개월 이내에 결정 또는 경정을 청구할 수 있는 경우에 해당하지 않는 것은?","c":"A","mc":{"s":"지방세기본법령상 과세표준 신고서를 법정신고기한까지 제출한 자 또는 지방세의 과세표준 및 세액의 결정을 받은 자가 법정신고 기한으로부터 5년이 지난 후 사유가 발생한 것을 안 날부터 3개월 이내에 결정 또는 경정을 청구할 수 있는 경우에 해당하지 않는 것은?","d":"","o":["최초의 신고․결정 또는 경정에서 과세표준 및 세액의 계산 근거가 된 거래 또는 행위 등이 그에 관한 세무조사의 결과 통지에 의하여 다른 것으로 확인된 경우","최초의 신고․결정 또는 경정을 할 때 과세표준 및 세액의 계산근거가 된 거래 또는 행위 등의 효력과 관계되는 관청의 허가나 그 밖의 처분이 해당 지방세의 법정신고기한이 지난 후에 취소된 경우","최초의 신고․결정 또는 경정을 할 때 과세표준 및 세액의 계산근거가 된 거래 또는 행위 등의 효력과 관계되는 계약이 해당 계약의 성립 후 발생한 부득이한 사유로 해당 지방세의 법정신고기한이 지난 후에 해제되거나 취소된 경우","최초의 신고․결정 또는 경정을 할 때 장부 및 증명서류의 압수, 그 밖의 부득이한 사유로 과세표준 및 세액을 계산할 수 없었으나 그 후 해당 지방세의 법정신고기한이 지난 후에 해당 사유가 소멸한 경우"],"a":1}},{"y":2019,"e":"지방직 9급","qn":11,"i":"L92019-11-1","t":"지방자치단체의 장은 납세자보호관을 배치하여 지방세 관련 고충민원의 처리, 세무상담 등 대통령령으로 정하는 납세자 권리보호업무를 전담하여 수행하게 하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2019,"e":"지방직 9급","qn":11,"i":"L92019-11-2","t":"지방자치단체의 장은 납세자가 장부·서류 등의 은닉, 제출지연, 제출거부 등 조사를 기피하는 행위가 명백한 경우 그 사유가 해소되는 날부터 20일 이내로 세무조사 기간을 연장할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2019,"e":"지방직 9급","qn":11,"i":"L92019-11-3","t":"지방자치단체의 장은 거래상대방에 대한 조사가 필요한 경우라도 같은 세목 및 같은 과세연도에 대하여 재조사를 할 수 없다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2019,"e":"지방직 9급","qn":11,"i":"L92019-11-4","t":"납세자는 범칙사건조사 및 세무조사를 받는 경우에 변호사, 공인회계사, 세무사로 하여금 조사에 참석하게 하거나 의견을 진술하게 할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 납세자의 권리"},{"y":2019,"e":"지방직 9급","qn":12,"i":"L92019-12-1","t":"‘납세자’란 납세의무자(연대납세의무자와 제2차 납세의무자 및 보증인을 포함)와 특별납세의무자를 말한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"지방직 9급","qn":12,"i":"L92019-12-2","t":"‘표준세율’이란 지방자치단체가 지방세를 부과할 경우에 조례의 위임을 받은 지방자치단체장이 정하는 바에 따라 가감하여 적용하여야 할 세율을 말한다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"지방직 9급","qn":12,"i":"L92019-12-3","t":"‘공과금’이란 지방세징수법 또는 국세징수법에서 규정하는 체납처분의 예에 따라 징수할 수 있는 채권 중 국세·관세·임시수입부가세 및 지방세와 이에 관계되는 체납처분비를 제외한 것을 말한다.","ox":"O","m":"③","c":"A","t0":"‘공과금’이란 지방세징수법 또는 국세징수법에서 규정하는 체납처분의 예에 따라 징수할 수 있는 채권 중 국세·관세·임시수입부가세 및 지방세와 이에 관계되는 가산금 및 체납처분비를 제외한 것을 말한다.","ox0":"O","rv":"개정 반영"},{"y":2019,"e":"지방직 9급","qn":12,"i":"L92019-12-4","t":"‘체납처분비’란 지방세를 체납한 경우 지방세기본법에 따라 고지세액에 가산하여 징수하는 금액과 행정처리에 드는 비용을 말한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"지방직 9급","qn":14,"i":"L92019-14-1","t":"사업에 현저한 손실을 입어 징수유예등을 받으려는 납세자는 대통령령으로 정하는 바에 따라 지방자치단체의 장에게 신청할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세징수법 상 징수유예등"},{"y":2019,"e":"지방직 9급","qn":14,"i":"L92019-14-2","t":"지방자치단체의 장은 징수유예등을 한 기간 중에는 그 유예한 지방자치단체의 징수금에 대하여 교부청구를 할 수 없다.","ox":"X","m":"②","c":"A","tp":"지방세징수법 상 징수유예등"},{"y":2019,"e":"지방직 9급","qn":14,"i":"L92019-14-3","t":"지방자치단체의 장은 징수유예등을 결정할 때에는 그 유예에 관계되는 금액에 상당하는 납세담보의 제공을 요구할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세징수법 상 징수유예등"},{"y":2019,"e":"지방직 9급","qn":14,"i":"L92019-14-4","t":"지방자치단체의 장은 징수유예등을 받은 자가 지방세와 체납액을 지정된 기한까지 납부하지 아니하면 그 징수유예등을 취소하고 그 징수유예에 관계되는 지방자치단체의 징수금 또는 체납액을 한꺼번에 징수할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세징수법 상 징수유예등"},{"y":2019,"e":"지방직 9급","qn":18,"i":"L92019-18-1","t":"특별징수하는 지방소득세를 납부할 의무는 과세표준이 되는 소득에 대하여 소득세·법인세를 원천징수하는 때에 성립한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2019,"e":"지방직 9급","qn":18,"i":"L92019-18-2","t":"수시로 부과하여 징수하는 지방세를 납부할 의무는 수시부과할 사유가 발생하는 때에 성립한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2019,"e":"지방직 9급","qn":18,"i":"L92019-18-3","t":"징수유예결정이 내려지면 지방세징수권의 소멸시효가 중단되고, 그 유예기간이 지난 때부터 그 시효는 새로 진행한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2019,"e":"지방직 9급","qn":18,"i":"L92019-18-4","t":"특별징수하는 지방소득세는 납세의무가 성립하는 때에 특별한 절차 없이 세액이 확정된다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2019,"e":"지방직 9급","qn":19,"i":"L92019-19-1","t":"가산세는 해당 의무가 규정된 지방세관계법의 해당 지방세의 세목으로 하지만, 지방세를 감면하는 경우에 가산세는 감면대상에 포함시키지 아니한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 가산세"},{"y":2019,"e":"지방직 9급","qn":19,"i":"L92019-19-2","t":"납세의무자가 사기나 그 밖의 부정한 행위로 법정신고기한까지 과세표준 신고를 하지 아니한 경우에는 무신고납부세액의 100분의 20에 상당하는 금액을 가산세로 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 가산세"},{"y":2019,"e":"지방직 9급","qn":19,"i":"L92019-19-3","t":"과세표준 신고 당시 소유권에 대한 소송으로 상속재산으로 확정되지 아니하여 과소신고한 경우에는 과소신고납부세액의 100분의 10에 상당하는 금액을 가산세로 부과한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 가산세"},{"y":2019,"e":"지방직 9급","qn":19,"i":"L92019-19-4","t":"납세의무자가 과소납부한 경우 과소납부분 세액의 100분의 20에 상당하는 금액을 가산세로 부과한다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 가산세"},{"y":2020,"e":"지방직 9급","qn":1,"i":"L92020-01","t":"지방세징수법 상 체납자가 체납액에 충당할 만한 다른 재산을 제공할 때에는 압류할 수 없는 조건부 압류금지재산에 해당하는 것은?","c":"A","mc":{"s":"지방세징수법 상 체납자가 체납액에 충당할 만한 다른 재산을 제공할 때에는 압류할 수 없는 조건부 압류금지재산에 해당하는 것은?","d":"","o":["체납자와 그 동거가족에게 필요한 3개월간의 식료와 연료","족보나 그 밖에 체납자의 가정에 필요한 장부․서류","의료․조산(助産)의 업(業) 또는 동물진료업에 필요한 기구․ 약품과 그 밖의 재료","직업 또는 사업에 필요한 기계․기구와 비품"],"a":4}},{"y":2020,"e":"지방직 9급","qn":2,"i":"L92020-02-1","t":"지방자치단체의 장은 압류를 한 날부터 3개월이 지날 때까지 압류에 의하여 징수하려는 지방세를 확정하지 아니하였을 때에는 재산의 압류를 즉시 해제하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2020,"e":"지방직 9급","qn":2,"i":"L92020-02-2","t":"급료·연금·임금·봉급·상여금·세비·퇴직연금, 그 밖에 이와 비슷한 성질을 가진 급여채권에 대해서는 총액을 압류할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2020,"e":"지방직 9급","qn":2,"i":"L92020-02-3","t":"지방자치단체의 장은 납세자가 국세, 지방세, 그 밖의 공과금에 대하여 체납처분을 받을 때에는 납기 전이라도 이미 납세의무가 성립된 지방세를 확정하여 지방자치단체의 징수금을 징수할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2020,"e":"지방직 9급","qn":2,"i":"L92020-02-4","t":"세무공무원이 질권이 설정된 재산을 압류하려는 경우에는 그 질권자에게 문서로써 그 질권의 대상물의 인도를 요구하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2020,"e":"지방직 9급","qn":4,"i":"L92020-04-1","t":"납세자가 국가·지방자치단체 또는 대통령령으로 정하는 정부관리기관이 발주하는 건설공사를 수주하고 건설공사계약을 체결하는 때에 대통령령으로 정하는 바에 따라 납세증명서를 제출하여야 한다.","ox":"X","m":"①","c":"A","tp":"지방세징수법 상 지방세의 납부를 강제하는 수단"},{"y":2020,"e":"지방직 9급","qn":4,"i":"L92020-04-2","t":"지방자치단체의 장은 납세자가 대통령령으로 정하는 사유 없이 지방세를 체납하면 허가등이 필요한 사업의 주무관청에 그 납세자에게 허가등을 하지 아니할 것을 요구할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세징수법 상 지방세의 납부를 강제하는 수단"},{"y":2020,"e":"지방직 9급","qn":4,"i":"L92020-04-3","t":"주택임대차보호법 제2조에 따른 주거용 건물 또는 상가건물 임대차보호법 제2조에 따른 상가건물을 임차하여 사용하려는 자는 건물에 대한 임대차계약을 하기 전에 임대인의 동의를 받아 임대인이 납부하지 아니한 지방세의 열람을 임차할 건물 소재지의 지방자치단체의 장에게 신청할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세징수법 상 지방세의 납부를 강제하는 수단"},{"y":2020,"e":"지방직 9급","qn":4,"i":"L92020-04-4","t":"행정안전부장관 또는 지방자치단체의 장은 지방세를 체납한 외국인에 대한 관리와 지방세 징수 등을 위하여 법무부장관에게 지방세를 3회 이상 체납하고 체납액이 5만원 이상의 범위에서 대통령령으로 정하는 금액 이상인 외국인 체납자의 인적사항, 체납액에 관한 자료를 제공할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세징수법 상 지방세의 납부를 강제하는 수단"},{"y":2020,"e":"지방직 9급","qn":5,"i":"L92020-05-1","t":"납세보증서를 납세담보로 제공하려는 자는 그 보증서를 지방 자치단체의 장에게 제출하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 납세담보의 제공방법"},{"y":2020,"e":"지방직 9급","qn":5,"i":"L92020-05-2","t":"납세보증보험증권을 납세담보로 제공하려는 자는 그 보험증권을 지방자치단체의 장에게 제출하여야 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 납세담보의 제공방법"},{"y":2020,"e":"지방직 9급","qn":5,"i":"L92020-05-3","t":"등록된 국채 또는 지방채를 납세담보로 제공하려는 자는 이를 공탁하고 그 공탁영수증을 지방자치단체의 장에게 제출하여야 한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 납세담보의 제공방법"},{"y":2020,"e":"지방직 9급","qn":5,"i":"L92020-05-4","t":"토지, 주택, 주택 외 건물, 선박, 항공기, 건설기계 또는 공장재단·광업재단을 납세담보로 제공하려는 자는 등기필증, 등기완료통지서 또는 등록확인증을 지방자치단체의 장에게 제시하여야 하며, 지방자치단체의 장은 이에 따라 저당권 설정을 위한 등기 또는 등록의 절차를 밟아야 한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 납세담보의 제공방법"},{"y":2020,"e":"지방직 9급","qn":7,"i":"L92020-07","t":"지방세기본법 상 지방세 부과의 제척기간에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세기본법 상 지방세 부과의 제척기간에 대한 설명으로 옳은 것은?","d":"(단, 조세조약에 따라 상호합의절차가 진행 중인 경우는 제외한다)","o":["납세자가 법정신고기한까지 지방세의 과세표준 신고서를 제출하지 아니한 경우에 그 지방세 부과의 제척기간은 5년이다.","납세자가 사기나 그 밖의 부정한 행위로 지방세를 포탈하거나 환급 또는 감면받은 경우에 그 지방세 부과의 제척기간은 7년이다.","상속을 원인으로 취득하는 경우로서 납세자가 법정신고기한까지 과세표준 신고서를 제출하지 아니한 경우에 그 지방세 부과의 제척기간은 7년이다.","부동산 실권리자명의 등기에 관한 법률 에 따른 명의신탁 약정으로 실권리자가 사실상 취득하는 경우로서 납세자가 법정신고기한까지 과세표준 신고서를 제출하지 아니한 경우 에 그 지방세 부과의 제척기간은 10년이다."],"a":4}},{"y":2020,"e":"지방직 9급","qn":11,"i":"L92020-11","t":"지방세법 상 보통징수 방법으로만 부과․징수하는 것은?","c":"A","mc":{"s":"지방세법 상 보통징수 방법으로만 부과․징수하는 것은?","d":"","o":["취득세","레저세","등록면허세","재산세"],"a":4}},{"y":2020,"e":"지방직 9급","qn":12,"i":"L92020-12-1","t":"지방세관계법에 따른 처분으로서 위법·부당한 처분을 받았거나 필요한 처분을 받지 못하여 권리 또는 이익을 침해당한 자는 지방세기본법에 따른 이의신청을 할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 이의신청"},{"y":2020,"e":"지방직 9급","qn":12,"i":"L92020-12-2","t":"이의신청이 있는 경우 압류한 재산에 대해서는 대통령령으로 정하는 바에 따라 그 공매처분을 보류할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 이의신청"},{"y":2020,"e":"지방직 9급","qn":12,"i":"L92020-12-3","t":"이의신청에 대한 결정에 오기가 있는 것이 명백할 때에도 지방자치단체의 장은 직권으로 결정을 경정할 수 없다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 이의신청"},{"y":2020,"e":"지방직 9급","qn":12,"i":"L92020-12-4","t":"과세전적부심사의 청구에 대한 처분에 대해서는 이의신청을 할 수 없다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 이의신청"},{"y":2020,"e":"지방직 9급","qn":19,"i":"L92020-19","t":"지방세기본법 상 지방세징수권의 시효에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세기본법 상 지방세징수권의 시효에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 지방세징수권의 시효는 교부청구로 인하여 중단된다.\nㄴ. 납세고지로 중단된 지방세징수권의 시효는 고지한 납부기간이 지난 때부터 새로 진행한다.\nㄷ. 지방세징수권의 소멸시효는 지방세징수법 에 따른 징수유예 기간에도 진행한다.\nㄹ. 지방자치단체의 장이 민법 제404조에 따른 채권자대위 소송을 제기하여 그 소송이 진행 중인 기간에는 지방세 징수권의 소멸시효는 진행되지 아니한다.","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2020,"e":"지방직 9급","qn":20,"i":"L92020-20","t":"지방세기본법 상 범칙사건에 대한 처분의 종류만을 고르면?","c":"A","mc":{"s":"지방세기본법 상 범칙사건에 대한 처분의 종류만을 고르면?","d":"ㄱ. 고발\nㄴ. 몰수\nㄷ. 무혐의\nㄹ. 통고처분","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2021,"e":"지방직 9급","qn":1,"i":"L92021-01-1","t":"법인이 합병한 경우에 합병 후 존속하는 법인은 합병으로 인하여 소멸된 법인에 부과된 지방자치단체의 징수금에 대하여는 납부할 의무를 지지 않는다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 납세의무의 확장 및 보충적 납세의무"},{"y":2021,"e":"지방직 9급","qn":1,"i":"L92021-01-2","t":"공유물(공동주택의 공유물은 제외한다), 공동사업 또는 그 공동사업에 속하는 재산에 관계되는 지방자치단체의 징수금은 공유자 또는 공동사업자가 연대하여 납부할 의무를 진다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 납세의무의 확장 및 보충적 납세의무"},{"y":2021,"e":"지방직 9급","qn":1,"i":"L92021-01-3","t":"법인이 해산할 때 징수금을 납부하지 아니하고 남은 재산을 분배하여 체납처분을 집행하더라도 징수할 금액이 부족한 경우 청산인은 부족한 금액 전부에 대하여 연대하여 납부할 의무를 진다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 납세의무의 확장 및 보충적 납세의무"},{"y":2021,"e":"지방직 9급","qn":1,"i":"L92021-01-4","t":"사업양수인은 양도일 이후에 양도인의 납세의무가 확정된 지방자치단체의 징수금을 양도인의 재산으로 충당하여도 부족할 때에는 그 부족한 금액에 대하여 제2차 납세의무를 진다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 납세의무의 확장 및 보충적 납세의무"},{"y":2021,"e":"지방직 9급","qn":2,"i":"L92021-02-1","t":"연대납세의무자에게 대표자가 없으면 납세의 고지와 독촉에 관한 서류는 연대납세의무자 중 지방세를 징수하기 유리한 자에게만 송달하여야 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2021,"e":"지방직 9급","qn":2,"i":"L92021-02-2","t":"서류를 교부하였을 때에는 수령인이 서명 또는 날인을 거부하면 그 사실을 송달서에 적어야 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2021,"e":"지방직 9급","qn":2,"i":"L92021-02-3","t":"서류의 송달을 받아야 할 자가 사전 반대한 경우가 아니면 전자송달의 방식으로 서류를 송달할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2021,"e":"지방직 9급","qn":2,"i":"L92021-02-4","t":"서류를 송달받을 자가 주소, 거소, 사무소 및 영업소 외의 다른 장소를 송달받을 장소로 요청한 경우 그 장소에 송달하여야 한다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 서류의 송달"},{"y":2021,"e":"지방직 9급","qn":3,"i":"L92021-03-1","t":"재산세의 납세의무는 과세기준일에 성립하며, 재산세의 과세 기준일은 매년 6월 1일로 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 및 지방세법 상 지방세 등"},{"y":2021,"e":"지방직 9급","qn":3,"i":"L92021-03-2","t":"가산세는 해당 의무가 규정된 지방세관계법의 해당 지방세의 세목으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 및 지방세법 상 지방세 등"},{"y":2021,"e":"지방직 9급","qn":3,"i":"L92021-03-3","t":"환급가산금을 포함한 지방세환급금에 관한 납세자의 권리는 타인에게 양도할 수 없다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 및 지방세법 상 지방세 등"},{"y":2021,"e":"지방직 9급","qn":3,"i":"L92021-03-4","t":"특별징수의무자가 정당한 사유 없이 지방세를 징수하지 아니한 경우에는 1천만원 이하의 벌금에 처한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 및 지방세법 상 지방세 등"},{"y":2021,"e":"지방직 9급","qn":4,"i":"L92021-04-1","t":"공유자가 공매재산인 공유물의 지분을 우선매수하겠다는 신고를 한 경우에는 매각결정 기일이 지날 때까지 공매보증금의 제공은 필요하지 않다.","ox":"X","m":"①","c":"A","tp":"지방세징수법 상 공유재산의 공매"},{"y":2021,"e":"지방직 9급","qn":4,"i":"L92021-04-2","t":"공매재산이 압류된 부부공유의 유가증권인 경우에는 체납자의 배우자는 우선매수권을 가지는 자에 해당하지 않는다.","ox":"X","m":"②","c":"A","tp":"지방세징수법 상 공유재산의 공매"},{"y":2021,"e":"지방직 9급","qn":4,"i":"L92021-04-3","t":"체납자의 배우자는 공매재산이 압류한 부부공유의 동산에 해당하는 경우 배분요구의 종기까지 매각대금 중 공유지분에 상응하는 대금을 지급하여 줄 것을 지방자치단체의 장에게 요구할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세징수법 상 공유재산의 공매"},{"y":2021,"e":"지방직 9급","qn":4,"i":"L92021-04-4","t":"우선매수 신고를 한 공유자에게 우선매각결정을 한 후에 그 매수인이 매각대금을 납부하지 아니하면 공매를 집행하는 공무원은 재공매를 하여야 한다.","ox":"X","m":"④","c":"A","tp":"지방세징수법 상 공유재산의 공매"},{"y":2021,"e":"지방직 9급","qn":5,"i":"L92021-05-1","t":"범칙사건조사를 하는 경우 과세예고통지를 받은 자는 과세 전적부심사를 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 과세전적부심사제도"},{"y":2021,"e":"지방직 9급","qn":5,"i":"L92021-05-2","t":"과세예고통지를 하는 날부터 지방세 부과 제척기간 만료일까지의 기간이 3개월을 초과하는 경우 과세전적부심사를 청구할 수 없다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 과세전적부심사제도"},{"y":2021,"e":"지방직 9급","qn":5,"i":"L92021-05-3","t":"세무조사결과에 대한 서면 통지를 받은 자가 과세전적부심사를 청구하려는 경우 통지받은 날부터 30일 이내에 하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 과세전적부심사제도"},{"y":2021,"e":"지방직 9급","qn":5,"i":"L92021-05-4","t":"과세전적부심사의 청구에 대한 처분에 대해서는 이의신청 또는 심판청구를 할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 과세전적부심사제도"},{"y":2021,"e":"지방직 9급","qn":7,"i":"L92021-07-1","t":"재산세의 물납(物納) 후 재산세 부과를 취소한 경우 물납재산이 매각된 경우가 아니면 그 물납재산으로 환급하여야 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 지방세환급금 또는 납세담보"},{"y":2021,"e":"지방직 9급","qn":7,"i":"L92021-07-2","t":"지방세환급금의 소멸시효는 지방자치단체의 장이 납세자의 지방세 환급청구를 촉구하기 위하여 납세자에게 하는 지방세 환급청구의 안내·통지 등으로 인하여 중단되지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세환급금 또는 납세담보"},{"y":2021,"e":"지방직 9급","qn":7,"i":"L92021-07-3","t":"납세담보로 금전을 제공한 자는 그 금전으로 담보한 지방 자치단체의 징수금을 납부할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 지방세환급금 또는 납세담보"},{"y":2021,"e":"지방직 9급","qn":7,"i":"L92021-07-4","t":"납세보증보험증권 또는 납세보증서를 납세담보로 제공하려는 자는 그 보험증권 또는 보증서를 지방자치단체의 장에게 제출하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 지방세환급금 또는 납세담보"},{"y":2021,"e":"지방직 9급","qn":8,"i":"L92021-08","t":"지방세기본법 상 수정신고 또는 경정청구에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세기본법 상 수정신고 또는 경정청구에 대한 설명으로 옳은 것은?","d":"(단, 납기 후의 과세표준 신고서는 지방세기본법 에 따라 제출함)","o":["납기 후의 과세표준 신고서를 제출한 자는 과세표준 수정 신고서를 제출할 수 없다.","수정신고는 지방세의 세액을 결정하여 통지하기 전이면 지방세 부과의 제척기간이 지난 후에도 가능하다.","조세조약에 따른 상호합의가 경정의 내용과 다르게 이루어졌을 때에는 그 사유가 발생한 날부터 90일 이내에 경정을 청구할 수 있다.","지방세기본법 또는 지방세관계법에 따른 과세표준 신고서를 법정신고기한까지 제출한 자뿐만 아니라 납기 후의 과세표준 신고서를 제출한 자도 경정청구를 할 수 있는 자에 해당한다."],"a":4}},{"y":2021,"e":"지방직 9급","qn":10,"i":"L92021-10-1","t":"상속이 개시된 경우에 상속인(상속인이 1인인 경우로 한정함)은 피상속인에 대한 지방자치단체의 징수금을 상속으로 얻은 재산의 한도 내에서 납부할 의무를 진다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2021,"e":"지방직 9급","qn":10,"i":"L92021-10-2","t":"과세표준 신고서를 법정신고기한까지 제출한 자의 수정신고는 당초의 신고에 따라 확정된 과세표준과 세액을 증액하여 확정하는 효력을 가진다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2021,"e":"지방직 9급","qn":10,"i":"L92021-10-3","t":"납세자가 상속을 원인으로 취득한 경우로서 법정신고기한까지 과세표준 신고서를 제출하지 아니한 경우 지방세 부과의 제척기간은 7년으로 한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2021,"e":"지방직 9급","qn":10,"i":"L92021-10-4","t":"지방세징수권의 시효는 납세고지에 의해 중단되며, 중단된 시효는 고지한 납부기간이 지난 때부터 새로 진행한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 납세의무"},{"y":2022,"e":"지방직 9급","qn":1,"i":"L92022-01-1","t":"지방세관계법에서 규정하는 신고기한이 되는 날에 대통령령으로 정하는 장애로 인하여 지방세정보통신망의 가동이 정지되어 전자신고를 할 수 없는 경우에는 그 장애가 복구된 날을 기한으로 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 기한"},{"y":2022,"e":"지방직 9급","qn":1,"i":"L92022-01-2","t":"지방세관계법에서 규정하는 신청, 청구, 그 밖의 서류 제출, 통지에 관한 기한이 공휴일, 토요일이거나 근로자의 날 제정에 관한 법률에 따른 근로자의 날일 때에는 그 다음 날을 기한으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 기한"},{"y":2022,"e":"지방직 9급","qn":1,"i":"L92022-01-3","t":"우편으로 과세표준 신고서, 과세표준 수정신고서를 제출한 경우 우편법령에 따른 통신날짜도장이 찍힌 날짜가 분명하지 아니할 때에는 통상 걸리는 우편 송달 일수를 기준으로 발송한 날에 해당한다고 인정되는 날에 신고된 것으로 본다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 기한"},{"y":2022,"e":"지방직 9급","qn":1,"i":"L92022-01-4","t":"지방자치단체의 장은 천재지변, 사변(事變), 화재(火災) 등의 사유로 납세자가 지방세관계법에서 규정하는 신고·신청·청구 또는 납부를 정해진 기한까지 할 수 없다고 인정되는 경우에는 대통령령으로 정하는 바에 따라 직권 또는 납세자의 신청으로 그 기한을 연장할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 기한"},{"y":2022,"e":"지방직 9급","qn":2,"i":"L92022-02-1","t":"납세자가 지방세법에 따라 재산세를 물납한 후 그 부과의 일부를 취소하거나 감액하는 경정결정에 따라 환급하는 경우에는 그 물납재산이 다른 행정용도로 사용되고 있는 경우에도 그 물납재산으로 환급하여야 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법령상 물납재산의 환급"},{"y":2022,"e":"지방직 9급","qn":2,"i":"L92022-02-2","t":"물납재산을 환급하는 경우에 지방자치단체가 물납재산에 대하여 법인세법 시행령 제31조 제2항에 따른 자본적 지출을 한 경우에는 이를 납세자의 부담으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법령상 물납재산의 환급"},{"y":2022,"e":"지방직 9급","qn":2,"i":"L92022-02-3","t":"물납재산으로 환급하는 경우에는 지방세환급가산금에 관한 지방세기본법 제62조를 적용하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법령상 물납재산의 환급"},{"y":2022,"e":"지방직 9급","qn":2,"i":"L92022-02-4","t":"물납재산의 수납 이후 발생한 과실(법정과실 및 천연과실을 말함)은 납세자에게 환급하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법령상 물납재산의 환급"},{"y":2022,"e":"지방직 9급","qn":3,"i":"L92022-03","t":"지방세징수법 상 지방자치단체의 장이 압류를 즉시 해제하여야 하는 사유로 옳지 않은 것은?","c":"A","mc":{"s":"지방세징수법 상 지방자치단체의 장이 압류를 즉시 해제하여야 하는 사유로 옳지 않은 것은?","d":"","o":["납부로 압류가 필요 없게 되었을 때","공매의 중지로 압류가 필요 없게 되었을 때","압류한 재산에 대한 제3자의 소유권 주장이 상당한 이유가 있다고 인정할 때","압류할 수 있는 다른 재산을 체납자가 제공하여 그 재산을 압류하였을 때"],"a":4}},{"y":2022,"e":"지방직 9급","qn":5,"i":"L92022-05","t":"지방세기본법 상 이의신청의 대상에 해당하는 것은?","c":"A","mc":{"s":"지방세기본법 상 이의신청의 대상에 해당하는 것은?","d":"","o":["제2차 납세의무자에 대한 납부고지","감사원법 에 따라 심사청구를 한 처분","과세전적부심사의 청구에 대한 처분","지방세기본법 에 따른 과태료의 부과"],"a":1}},{"y":2022,"e":"지방직 9급","qn":6,"i":"L92022-06-1","t":"납세자와 세무공무원은 신의에 따라 성실하게 그 의무를 이행하거나 직무를 수행하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2022,"e":"지방직 9급","qn":6,"i":"L92022-06-2","t":"지방세기본법 제19조 제1항에 따라 지방세를 조사·결정할 때 기록 내용이 사실과 다르거나 누락된 것이 있을 때에는 그 부분에 대해서만 지방자치단체가 조사한 사실에 따라 결정할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2022,"e":"지방직 9급","qn":6,"i":"L92022-06-3","t":"지방세관계법 중 과세표준 또는 세액의 계산에 관한 규정은 소득·수익·재산·행위 또는 거래의 실질내용과 관계없이 그 명칭이나 형식에 따라 적용한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2022,"e":"지방직 9급","qn":6,"i":"L92022-06-4","t":"세무공무원은 지방세기본법 또는 지방세관계법의 목적에 따른 한계를 준수하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 지방세 부과 등의 원칙"},{"y":2022,"e":"지방직 9급","qn":8,"i":"L92022-08","t":"지방세징수법령상 체납처분에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세징수법령상 체납처분에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 세무공무원이 체납처분을 하기 위하여 질문할 때에는 신분을 표시하는 증표를 지니고 관계자에게 보여 주어야 한다.\nㄴ. 지방자치단체의 장은 지방세징수법 제33조 제2항에 따라 압류한 유가증권을 확정되리라고 추정되는 지방자치단체의 징수금에 충당할 수 있다.\nㄷ. 주로 야간에 주류를 제공하는 영업을 하는 장소에 대해서는 해가 진 후에는 영업 중에 수색을 시작할 수 없다.\nㄹ. 납세의 고지를 받고 납세자가 도피할 우려가 있어 납부기한까지 기다려서는 고지한 지방세를 징수할 수 없다고 인정되는 경우에는 지방자치단체의 장은 납세자의 재산을 납기 전이라도 압류할 수 있다. 이 경우 지방자치단체의 장은 납세의무가 확정되리라고 추정되는 금액의 한도에서 압류하여야 한다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":2}},{"y":2022,"e":"지방직 9급","qn":9,"i":"L92022-09-1","t":"지방자치단체의 장은 지방자치단체의 징수금의 부과·징수가 위법·부당한 것임을 확인하면 즉시 그 처분을 취소하거나 변경하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 부과"},{"y":2022,"e":"지방직 9급","qn":9,"i":"L92022-09-2","t":"법정신고기한까지 과세표준 신고서를 제출하지 아니한 자는 지방자치단체의 장이 지방세법에 따라 그 지방세의 과세표준과 세액을 결정하여 통지하기 전에는 납기 후의 과세표준 신고서를 제출할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 부과"},{"y":2022,"e":"지방직 9급","qn":9,"i":"L92022-09-3","t":"법정신고기한까지 과세표준 신고를 한 경우로서 신고 당시 소유권에 대한 소송으로 상속재산으로 확정되지 아니하여 과소신고한 경우에는 가산세를 부과하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 부과"},{"y":2022,"e":"지방직 9급","qn":9,"i":"L92022-09-4","t":"부정행위로 과소신고하더라도 지방소득세를 과세기간을 잘못 적용하여 신고납부한 경우에는 실제 신고납부한 날에 실제 신고납부한 금액의 범위에서 당초 신고납부하였어야 할 과세기간에 대한 지방소득세를 신고납부한 것으로 본다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 부과"},{"y":2022,"e":"지방직 9급","qn":10,"i":"L92022-10-1","t":"특별징수하는 지방소득세는 과세표준이 되는 소득에 대하여 소득세·법인세를 원천징수하는 때에 납부할 의무가 성립한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세를 납부할 의무"},{"y":2022,"e":"지방직 9급","qn":10,"i":"L92022-10-2","t":"면허에 대한 등록면허세는 각종의 면허를 받는 때와 납기가 있는 달의 1일에 납부할 의무가 성립한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세를 납부할 의무"},{"y":2022,"e":"지방직 9급","qn":10,"i":"L92022-10-3","t":"자동차 소유에 대한 자동차세는 교통·에너지·환경세의 납세의무가 성립하는 때에 납부할 의무가 성립한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 지방세를 납부할 의무"},{"y":2022,"e":"지방직 9급","qn":10,"i":"L92022-10-4","t":"특별징수하는 지방소득세는 납세의무가 성립하는 때에 특별한 절차 없이 세액이 확정된다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 지방세를 납부할 의무"},{"y":2022,"e":"지방직 9급","qn":15,"i":"L92022-15-1","t":"지방자치단체의 장은 징수유예등을 받은 자가 지방세와 체납액을 지정된 기한까지 납부하지 아니하였을 때에는 그 징수유예등을 취소하고 그 징수유예등에 관계되는 지방세 또는 체납액을 한꺼번에 징수할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세징수법 상 징수유예"},{"y":2022,"e":"지방직 9급","qn":15,"i":"L92022-15-2","t":"지방자치단체의 장은 제26조(송달불능으로 인한 징수유예등과 부과철회) 제1항에 따라 징수유예등을 한 지방세의 징수를 확보할 수 없다고 인정할 때에는 그 부과결정을 철회할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세징수법 상 징수유예"},{"y":2022,"e":"지방직 9급","qn":15,"i":"L92022-15-3","t":"지방자치단체의 장은 제25조의2(고지된 지방세 등의 징수유예)에 따라 징수유예를 한 기간 중에는 그 유예한 지방세 또는 체납액에 대하여 체납처분(교부청구를 포함한다)을 할 수 없다.","ox":"X","m":"③","c":"A","tp":"지방세징수법 상 징수유예"},{"y":2022,"e":"지방직 9급","qn":15,"i":"L92022-15-4","t":"지방자치단체의 장은 징수유예등을 결정할 때에는 그 유예에 관계되는 금액에 상당하는 납세담보의 제공을 요구할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세징수법 상 징수유예"},{"y":2023,"e":"지방직 9급","qn":2,"i":"L92023-02-1","t":"처분의 통지를 받은 자가 이의신청을 거치지 아니하고 바로 심판청구를 할 때에는 통지받은 날부터 90일 이내에 조세 심판원장에게 심판청구를 하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 이의신청과 심판청구"},{"y":2023,"e":"지방직 9급","qn":2,"i":"L92023-02-2","t":"과세전적부심사의 청구에 대한 처분이 위법하여 이익을 침해당한 자는 그 처분에 대하여 이의신청과 심판청구를 할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 이의신청과 심판청구"},{"y":2023,"e":"지방직 9급","qn":2,"i":"L92023-02-3","t":"이의신청인은 신청 또는 청구 금액이 1천만원 미만인 경우에는 그의 배우자, 4촌 이내의 혈족 또는 그의 배우자의 4촌 이내 혈족을 대리인으로 선임할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 이의신청과 심판청구"},{"y":2023,"e":"지방직 9급","qn":2,"i":"L92023-02-4","t":"이의신청에 대한 결정에 계산착오가 있는 것이 명백할 때에는 지방자치단체의 장은 직권으로 그 결정을 경정할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 이의신청과 심판청구"},{"y":2023,"e":"지방직 9급","qn":3,"i":"L92023-03-1","t":"시효는 지방세법에 따른 분할납부기간에는 진행되지 아니한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효의 중단과 정지"},{"y":2023,"e":"지방직 9급","qn":3,"i":"L92023-03-2","t":"납부최고에 의해 중단된 시효는 납부최고에 따른 납부기간이 지난 때부터 새로 진행한다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효의 중단과 정지"},{"y":2023,"e":"지방직 9급","qn":3,"i":"L92023-03-3","t":"시효는 지방세징수법에 따른 체납처분유예기간에는 진행되지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효의 중단과 정지"},{"y":2023,"e":"지방직 9급","qn":3,"i":"L92023-03-4","t":"지방자치단체의 장이 민법에 따라 제기한 채권자대위 소송이 기각되더라도 그 소송의 제기로 인한 시효정지는 효력이 있다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효의 중단과 정지"},{"y":2023,"e":"지방직 9급","qn":7,"i":"L92023-07-1","t":"전자송달을 받을 자가 전자송달된 서류를 5회 이상 송달의 효력이 발생한 때부터 60일 동안 확인하지 아니한 경우에는 그 사유가 발생한 날 전자송달의 신청을 철회한 것으로 본다.","ox":"X","m":"①","c":"A","tp":"지방세기본법령상 서류의 송달"},{"y":2023,"e":"지방직 9급","qn":7,"i":"L92023-07-2","t":"교부의 방법으로 서류를 송달하려는 경우에는 지방자치단체의 조례로 정하는 바에 따라 지방자치단체의 하부조직을 통하여 송달할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법령상 서류의 송달"},{"y":2023,"e":"지방직 9급","qn":7,"i":"L92023-07-3","t":"연대납세의무자에게 납세의 고지와 독촉에 관한 서류를 송달할 때에는 대표자가 없으면 연대납세의무자 중 지방세를 징수하기 유리한 자를 명의인으로 한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법령상 서류의 송달"},{"y":2023,"e":"지방직 9급","qn":7,"i":"L92023-07-4","t":"송달받아야 할 자의 주소가 국외에 있는 경우에는 서류의 주요 내용을 공고하면 공고한 날에 서류의 송달이 된 것으로 본다.","ox":"X","m":"④","c":"A","tp":"지방세기본법령상 서류의 송달"},{"y":2023,"e":"지방직 9급","qn":8,"i":"L92023-08","t":"지방세기본법 상 지방세 부과 등의 원칙에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세기본법 상 지방세 부과 등의 원칙에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 지방세관계법의 해석이 일반적으로 납세자에게 받아들여진 후에는 새로운 해석이 있는 날 이후에 납세의무가 성립하는 행위에 대해서도 새로운 해석에 따라 과세할 수 없다.\nㄴ. 납세의무자가 지방세관계법에 따라 장부를 갖추어 기록하고 있을 때에는 기록 내용이 사실과 다르거나 누락된 것이 없으면 해당 지방세의 과세표준 조사 및 결정은 기록한 장부와 이에 관계되는 증거자료에 따라야 한다.\nㄷ. 세무공무원은 지방세의 과세표준과 세액을 조사ㆍ결정할 때에는 지방세법 에 다른 규정을 두고 있더라도 해당 납세의무자가 계속하여 적용하는 기업회계의 기준 또는 관행에 따라야 한다.\nㄹ. 과세의 대상이 되는 거래가 서류상 귀속되는 자는 명의만 있을 뿐 사실상 귀속되는 자가 따로 있을 때에는 사실상 귀속되는 자를 납세의무자로 하여 지방세기본법 또는 지방세관계법을 적용한다.","o":["ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2023,"e":"지방직 9급","qn":10,"i":"L92023-10-1","t":"재판상의 가압류 또는 가처분 재산이 체납처분 대상인 경우에는 체납처분을 할 수 없다.","ox":"X","m":"①","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2023,"e":"지방직 9급","qn":10,"i":"L92023-10-2","t":"체납자가 압류재산을 사용하는 경우에는 그 재산의 매각으로 인하여 권리를 이전할 때까지 거두어들이지 아니한 천연과실에 대해서는 압류의 효력이 미치지 아니한다.","ox":"X","m":"②","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2023,"e":"지방직 9급","qn":10,"i":"L92023-10-3","t":"체납자의 재산에 대하여 체납처분을 집행한 후 체납자가 사망하였을 때에도 그 재산에 대한 체납처분은 계속 진행하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2023,"e":"지방직 9급","qn":10,"i":"L92023-10-4","t":"체납자와 그 동거가족에게 필요한 3개월간의 연료는 체납자가 체납액에 충당할 만한 다른 재산을 제공하지 않으면 압류할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2023,"e":"지방직 9급","qn":15,"i":"L92023-15-1","t":"특별시의 세목에는 등록면허세가 포함되지 않는다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세와 지방자치단체의 세목"},{"y":2023,"e":"지방직 9급","qn":15,"i":"L92023-15-2","t":"특별자치시의 세목에는 지역자원시설세가 포함된다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 지방세와 지방자치단체의 세목"},{"y":2023,"e":"지방직 9급","qn":15,"i":"L92023-15-3","t":"시ㆍ군의 세목에는 목적세인 지방교육세가 포함된다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 지방세와 지방자치단체의 세목"},{"y":2023,"e":"지방직 9급","qn":15,"i":"L92023-15-4","t":"광역시의 군(郡) 지역에서는 도세를 광역시세로 한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 지방세와 지방자치단체의 세목"},{"y":2023,"e":"지방직 9급","qn":16,"i":"L92023-16","t":"지방세기본법 상 가산세에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세기본법 상 가산세에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 가산세는 해당 의무가 규정된 지방세관계법의 해당 지방세의 세목으로 한다.\nㄴ. 납세의무자가 사기로 법정신고기한까지 과세표준 신고를 하지 아니한 경우에는 무신고납부세액의 100분의 20에 상당하는 금액을 가산세로 부과한다.\nㄷ. 지방세를 감면하는 경우에 가산세는 그 감면대상에 포함한다.\nㄹ. 납부세액 신고 당시 소유권에 대한 소송으로 상속재산으로 확정되지 아니하여 과소신고한 경우에는 과소신고가산세를 부과하지 아니한다.","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":2}},{"y":2023,"e":"지방직 9급","qn":17,"i":"L92023-17-1","t":"독촉장 또는 납부최고서를 발급할 때에는 납부기한을 발급일부터 20일 이내로 한다.","ox":"O","m":"①","c":"A","tp":"지방세징수법 상 징수절차"},{"y":2023,"e":"지방직 9급","qn":17,"i":"L92023-17-2","t":"법령에 따라 기간을 정하여 징수유예를 한 경우 납세고지서의 발급시기는 그 기간이 만료한 날이다.","ox":"X","m":"②","c":"A","tp":"지방세징수법 상 징수절차"},{"y":2023,"e":"지방직 9급","qn":17,"i":"L92023-17-3","t":"지방자치단체의 징수금과 지방자치단체에 대한 채권으로서 금전의 급부를 목적으로 하는 것은 법률에 따로 규정이 있는 것을 제외 하고는 상계할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세징수법 상 징수절차"},{"y":2023,"e":"지방직 9급","qn":17,"i":"L92023-17-4","t":"납세자를 위하여 지방자치단체의 징수금을 납세자의 명의로 납부한 제3자는 지방자치단체에 대하여 그 반환을 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세징수법 상 징수절차"},{"y":2024,"e":"지방직 9급","qn":2,"i":"L92024-02-1","t":"세무조사결과에 대한 서면 통지를 받은 자는 통지받은 날부터 90일 이내에 지방자치단체의 장에게 통지내용의 적법성에 관한 심사 (과세전적부심사)를 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 과세전적부심사"},{"y":2024,"e":"지방직 9급","qn":2,"i":"L92024-02-2","t":"세무조사결과 통지 및 과세예고통지를 하는 날부터 지방세 부과 제척기간의 만료일까지의 기간이 3개월 이하인 경우에는 과세전 적부심사를 청구할 수 없다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 과세전적부심사"},{"y":2024,"e":"지방직 9급","qn":2,"i":"L92024-02-3","t":"과세전적부심사청구를 받은 지방자치단체의 장은 지방세심의 위원회의 심사를 거쳐 결정을 하고 그 결과를 결정한 날부터 30일 이내에 청구인에게 알려야 한다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 과세전적부심사"},{"y":2024,"e":"지방직 9급","qn":2,"i":"L92024-02-4","t":"과세전적부심사의 청구에 대한 처분에 대해서는 이의신청 또는 심판청구를 할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 과세전적부심사"},{"y":2024,"e":"지방직 9급","qn":3,"i":"L92024-03","t":"지방세징수법 상 압류재산을 수의계약으로 매각할 수 있는 경우만을 모두 고르면?","c":"A","mc":{"s":"지방세징수법 상 압류재산을 수의계약으로 매각할 수 있는 경우만을 모두 고르면?","d":"ㄱ. 압류한 재산의 추산 가격이 5백만원인 경우\nㄴ. 부패ㆍ변질 또는 감량되기 쉬운 재산으로서 속히 매각하지 아니하면 재산가액이 줄어들 우려가 있는 경우\nㄷ. 제1회 공매 후 1년간 5회 이상 공매하여도 매각되지 아니한 경우","o":["ㄴ","ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":4}},{"y":2024,"e":"지방직 9급","qn":4,"i":"L92024-04-1","t":"부동산에 대한 취득세: 취득자의 주소지","ox":"X","m":"①","c":"A"},{"y":2024,"e":"지방직 9급","qn":4,"i":"L92024-04-2","t":"선박 등기 또는 등록에 대한 등록면허세: 선적항 소재지","ox":"O","m":"②","c":"A"},{"y":2024,"e":"지방직 9급","qn":4,"i":"L92024-04-3","t":"건축물에 대한 재산세: 건축물의 소재지","ox":"O","m":"③","c":"A"},{"y":2024,"e":"지방직 9급","qn":4,"i":"L92024-04-4","t":"골프회원권에 대한 취득세: 골프장의 소재지","ox":"O","m":"④","c":"A"},{"y":2024,"e":"지방직 9급","qn":6,"i":"L92024-06-1","t":"세무조사는 지방세기본법 및 지방세관계법에 따라 납세자가 납부하여야 하는 모든 지방세 세목을 통합하여 실시하는 것을 원칙으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 세무조사"},{"y":2024,"e":"지방직 9급","qn":6,"i":"L92024-06-2","t":"조세채권의 확보 등을 위하여 특정 세목만을 긴급히 조사할 필요가 있는 경우에는 특정한 세목만을 조사할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 세무조사"},{"y":2024,"e":"지방직 9급","qn":6,"i":"L92024-06-3","t":"납세자는 범칙사건조사 및 세무조사를 받는 경우에 변호사, 공인 회계사, 세무사로 하여금 조사에 참석하게 하거나 의견을 진술하게 할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 세무조사"},{"y":2024,"e":"지방직 9급","qn":6,"i":"L92024-06-4","t":"지방자치단체의 장은 정기선정에 의한 조사 외에 납세자가 세무 조사를 신청하는 경우에는 세무조사를 할 수 없다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 세무조사"},{"y":2024,"e":"지방직 9급","qn":10,"i":"L92024-10-1","t":"취득세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 징수"},{"y":2024,"e":"지방직 9급","qn":10,"i":"L92024-10-2","t":"지방소비세의 납세지를 관할하는 세무서장 또는 부가가치세법에 따라 재화의 수입에 대한 부가가치세를 징수하는 세관장을 지방 소비세의 특별징수의무자로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 징수"},{"y":2024,"e":"지방직 9급","qn":10,"i":"L92024-10-3","t":"담배를 다른 담배의 원료로 사용하기 위하여 반출하는 경우에는 담배소비세를 징수하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 징수"},{"y":2024,"e":"지방직 9급","qn":10,"i":"L92024-10-4","t":"재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 징수"},{"y":2024,"e":"지방직 9급","qn":11,"i":"L92024-11","t":"지방세기본법 상 납세의무의 성립시기로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세기본법 상 납세의무의 성립시기로 옳은 것만을 모두 고르면?","d":"(단, 수시부과할 사유는 없음)\nㄱ. 지방소비세: 국세기본법 에 따른 부가가치세의 납세의무가 확정되는 때\nㄴ. 자동차 소유에 대한 자동차세: 과세기준일(매년 1월 1일)\nㄷ. 선박에 대한 지역자원시설세: 선박의 건조가 완료되는 때\nㄹ. 레저세: 승자투표권, 승마투표권 등을 발매하는 때\nㅁ. 담배소비세: 담배를 제조장 또는 보세구역으로부터 반출하거나 국내로 반입하는 때","o":["ㄴ, ㄷ","ㄹ, ㅁ","ㄱ, ㄴ, ㄷ","ㄱ, ㄹ, ㅁ"],"a":2}},{"y":2024,"e":"지방직 9급","qn":13,"i":"L92024-13-1","t":"거주자는 양도차익이 없거나 양도차손이 발생한 경우 소득세법에 따라 양도소득과세표준 예정신고만 하면 되고, 양도소득에 대한 개인지방소득세 과세표준과 세액을 예정신고할 의무는 없다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 신고납부"},{"y":2024,"e":"지방직 9급","qn":13,"i":"L92024-13-2","t":"레저세 납세의무자는 승자투표권, 승마투표권 등의 발매일이 속하는 달의 다음 달 20일까지 산출세액을 대통령령으로 정하는 바에 따라 안분계산하여 해당 경륜장등이 소재하는 지방자치단체의 장에게 신고하고 납부하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 신고납부"},{"y":2024,"e":"지방직 9급","qn":13,"i":"L92024-13-3","t":"담배 제조자는 매월 1일부터 말일까지 제조장에서 반출한 담배에 대한 산출세액을 대통령령으로 정하는 안분기준에 따라 다음 달 25일까지 각 지방자치단체의 장에게 신고납부하여야 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 신고납부"},{"y":2024,"e":"지방직 9급","qn":13,"i":"L92024-13-4","t":"취득세 과세물건을 무상취득(상속은 제외함)한 자는 취득일이 속하는 달의 말일부터 3개월 이내에 그 과세표준에 법정 세율을 적용하여 산출한 세액을 대통령령으로 정하는 바에 따라 신고하고 납부하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 신고납부"},{"y":2024,"e":"지방직 9급","qn":18,"i":"L92024-18-1","t":"외국정부의 취득에 대해서는 취득세를 부과하지 아니하지만, 대한민국 정부기관의 취득에 대하여 과세하는 외국정부의 취득에 대해서는 취득세를 부과한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 비과세"},{"y":2024,"e":"지방직 9급","qn":18,"i":"L92024-18-2","t":"외국정부가 자기를 위하여 받는 등록 또는 면허에 대하여는 등록면허세를 부과하지 아니하지만, 대한민국 정부기관의 등록 또는 면허에 대하여 과세하는 외국정부의 등록 또는 면허의 경우에는 등록면허세를 부과한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 비과세"},{"y":2024,"e":"지방직 9급","qn":18,"i":"L92024-18-3","t":"국가 또는 지방자치단체에 기부채납을 조건으로 부동산을 취득하고 기부채납의 반대급부로 기부채납 대상물의 무상사용권을 제공받는 경우에는 취득세를 부과하지 아니한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 비과세"},{"y":2024,"e":"지방직 9급","qn":18,"i":"L92024-18-4","t":"소득세법, 법인세법 및 조세특례제한법에 따라 소득세 또는 법인세가 비과세되는 소득에 대하여는 지방소득세를 과세하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 비과세"},{"y":2025,"e":"지방직 9급","qn":1,"i":"L92025-01-1","t":"가산세를 제외한 지방세의 금액이 5천만원 이상인 경우 소멸시효 기간은 10년이다.","ox":"O","m":"①","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효"},{"y":2025,"e":"지방직 9급","qn":1,"i":"L92025-01-2","t":"체납자가 국외에 6개월 이상 계속하여 체류하는 경우 해당 국외 체류기간에는 소멸시효가 중단된다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효"},{"y":2025,"e":"지방직 9급","qn":1,"i":"L92025-01-3","t":"특별징수의무자로부터 징수하는 지방세로서 납세고지한 특별 징수세액의 경우 납세고지서에 따른 납부기한의 다음 날을 지방세 징수권을 행사할 수 있는 때로 본다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효"},{"y":2025,"e":"지방직 9급","qn":1,"i":"L92025-01-4","t":"납세고지에 따라 중단된 시효는 고지한 납부기간이 지난 때부터 새로 진행한다.","ox":"O","m":"④","c":"A","tp":"지방세기본법 상 지방세징수권의 소멸시효"},{"y":2025,"e":"지방직 9급","qn":4,"i":"L92025-04","t":"지방세법 상 조례로 정하는 바에 따라 세율을 표준세율의 100분의 50의 범위에서 가감할 수 있는 것만을 모두 고르면?","c":"A","mc":{"s":"지방세법 상 조례로 정하는 바에 따라 세율을 표준세율의 100분의 50의 범위에서 가감할 수 있는 것만을 모두 고르면?","d":"ㄱ. 취득세\nㄴ. 자동차 주행에 대한 자동차세\nㄷ. 주민세 종업원분\nㄹ. 레저세","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":1}},{"y":2025,"e":"지방직 9급","qn":7,"i":"L92025-07-1","t":"체납자는 체납처분의 목적물인 총재산의 추산가액이 체납처분비에 충당하고 남을 여지가 없을 때에는 체납처분의 중지를 지방자치 단체의 장에게 요청할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2025,"e":"지방직 9급","qn":7,"i":"L92025-07-2","t":"지방자치단체의 장은 지방세징수권의 소멸시효가 완성되거나 체납처분을 유예하였을 때에는 정리보류를 할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2025,"e":"지방직 9급","qn":7,"i":"L92025-07-3","t":"지방자치단체의 장은 압류를 유예하는 경우 납세담보의 제공을 요구할 수 있지만, 압류를 해제하는 경우에는 납세담보의 제공을 요구할 수 없다.","ox":"X","m":"③","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2025,"e":"지방직 9급","qn":7,"i":"L92025-07-4","t":"지방자치단체의 장은 체납자가 성실납부자로 인정되고 체납처분을 유예함으로써 사업을 정상적으로 운영할 수 있다고 인정되는 경우에는 체납처분을 유예하여야 한다.","ox":"X","m":"④","c":"A","tp":"지방세징수법 상 체납처분"},{"y":2025,"e":"지방직 9급","qn":10,"i":"L92025-10-1","t":"차량 취득세의 납세지는 자동차관리법에 따른 등록지가 사용 본거지와 다른 경우에는 등록지로 한다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 납세지"},{"y":2025,"e":"지방직 9급","qn":10,"i":"L92025-10-2","t":"등록에 대한 등록면허세의 납세지는 상호 등기의 경우에는 주사무소 소재지로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 납세지"},{"y":2025,"e":"지방직 9급","qn":10,"i":"L92025-10-3","t":"주민세 사업소분의 납세지는 과세기준일 현재 각 사업소 소재지로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 납세지"},{"y":2025,"e":"지방직 9급","qn":10,"i":"L92025-10-4","t":"면허에 대한 등록면허세의 납세지는 해당 면허에 대한 별도의 영업장이 있는 면허의 경우에는 면허를 받은 자의 주소지로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 납세지"},{"y":2025,"e":"지방직 9급","qn":12,"i":"L92025-12-1","t":"주택 외 건축물의 담보가액은 대통령령으로 정하는 바에 따라 시가를 고려하여 결정한 가액으로 한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 납세담보"},{"y":2025,"e":"지방직 9급","qn":12,"i":"L92025-12-2","t":"납세보증보험증권을 납세담보로 제공하려는 자는 그 보험증권에 담보제공의 뜻을 등록하고 등록확인증을 지방자치단체의 장에게 제출하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세기본법 상 납세담보"},{"y":2025,"e":"지방직 9급","qn":12,"i":"L92025-12-3","t":"보험에 든 등록된 건설기계를 납세담보로 제공하려는 자는 등록확인증을 지방자치단체의 장에게 제시하여야 하며, 지방자치 단체의 장은 저당권 설정을 위한 등록의 절차를 밟아야 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법 상 납세담보"},{"y":2025,"e":"지방직 9급","qn":12,"i":"L92025-12-4","t":"납세담보로 납세보증서를 제공한 자는 담보한 지방자치단체의 징수금을 그 납세보증서로 납부할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 납세담보"},{"y":2025,"e":"지방직 9급","qn":15,"i":"L92025-15-1","t":"적법하게 납부된 지방세의 감면으로 환급하는 경우 지방세환급 가산금은 그 감면 결정일부터 지방세환급금을 지급하는 날까지의 기간과 기본이자율에 따라 계산한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법령상 지방세환급금과 지방세환급가산금"},{"y":2025,"e":"지방직 9급","qn":15,"i":"L92025-15-2","t":"체납액의 징수금에 지방세환급금을 충당하는 경우 체납액과 지방세환급금은 체납된 지방세의 법정납부기한에 소급하여 같은 금액만큼 소멸한 것으로 본다.","ox":"X","m":"②","c":"A","tp":"지방세기본법령상 지방세환급금과 지방세환급가산금"},{"y":2025,"e":"지방직 9급","qn":15,"i":"L92025-15-3","t":"지방자치단체의 장은 납세자의 동의와 관계없이 지방세환급금으로 결정한 금액을 대통령령으로 정하는 바에 따라 체납액의 징수금에 충당하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세기본법령상 지방세환급금과 지방세환급가산금"},{"y":2025,"e":"지방직 9급","qn":15,"i":"L92025-15-4","t":"지방세환급금의 소멸시효는 지방자치단체의 장이 납세자의 지방세 환급청구를 촉구하기 위하여 납세자에게 하는 지방세 환급청구의 안내ㆍ통지 등으로 인하여 중단된다.","ox":"X","m":"④","c":"A","tp":"지방세기본법령상 지방세환급금과 지방세환급가산금"},{"y":2025,"e":"지방직 9급","qn":19,"i":"L92025-19-1","t":"사기로 포탈한 지방세액이 3억원 이상이거나, 포탈한 지방세액이 신고납부하여야 할 세액의 100분의 30 이상인 경우 3년 이하의 징역에 처한다.","ox":"X","m":"①","c":"A","tp":"지방세기본법 상 범칙행위 처벌"},{"y":2025,"e":"지방직 9급","qn":19,"i":"L92025-19-2","t":"지방세기본법 제102조(지방세의 포탈)제1항에서 규정하는 포탈범칙행위의 기수 시기는 지방자치단체의 장이 세액을 결정하여 부과하는 세목의 경우 납부기한이 지난 때이다.","ox":"O","m":"②","c":"A","tp":"지방세기본법 상 범칙행위 처벌"},{"y":2025,"e":"지방직 9급","qn":19,"i":"L92025-19-3","t":"범칙사건에 대한 처분의 종류는 통고처분, 고발, 체납처분이다.","ox":"X","m":"③","c":"A","tp":"지방세기본법 상 범칙행위 처벌"},{"y":2025,"e":"지방직 9급","qn":19,"i":"L92025-19-4","t":"범칙행위는 행정안전부장관의 고발이 있어야 공소를 제기할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세기본법 상 범칙행위 처벌"}],"7":[{"y":2015,"e":"지방직 9급","qn":3,"i":"L92015-03-1","t":"부가가치세의 납세지를 관할하는 세무서장 또는 재화수입에 대한 부가가치세를 징수하는 세관장을 지방소비세의 특별징수 의무자로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2015,"e":"지방직 9급","qn":3,"i":"L92015-03-2","t":"지방소비세는 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 금액의 1천분의 253으로 하며, 부가 가치세를 신고하지 않은 경우에도 지방소비세는 신고하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지방소비세","t0":"지방소비세는 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 금액의 100분의 11로 하며, 부가 가치세를 신고하지 않은 경우에도 지방소비세는 신고하여야 한다.","ox0":"X","rv":"개정 반영"},{"y":2015,"e":"지방직 9급","qn":3,"i":"L92015-03-3","t":"지방소비세의 특별징수의무자는 징수한 지방소비세를 납입 관리자에게 다음 달 20일까지 납입하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2015,"e":"지방직 9급","qn":3,"i":"L92015-03-4","t":"지방소비세에 대한 불복절차는 국세의 예를 따르며, 이 경우 지방소비세의 특별징수의무자를 그 처분청으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2015,"e":"지방직 9급","qn":7,"i":"L92015-07-1","t":"재산분의 납세의무자는 매년 7월 1일 현재 과세대장에 등재된 사업주로 하며, 사업소용 건축물의 소유자와 사업주가 다른 경우에는 건축물의 소유자가 주민세의 비과세대상자가 아닌 경우에 한하여 그에게 제2차납세의무를 지울 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 주민세의 납세의무자"},{"y":2015,"e":"지방직 9급","qn":7,"i":"L92015-07-2","t":"국민기초생활 보장법에 따른 수급자에 대하여는 균등분을 부과하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 주민세의 납세의무자"},{"y":2015,"e":"지방직 9급","qn":7,"i":"L92015-07-3","t":"지방자치단체에 사업소를 둔 법인(법인세의 과세대상이 되는 법인격 없는 사단·재단 및 단체를 포함)은 균등분 납세의무자이다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 주민세의 납세의무자"},{"y":2015,"e":"지방직 9급","qn":7,"i":"L92015-07-4","t":"지방자치단체에 사업소를 둔 담배소매인인 개인사업자는 직전 연도의 부가가치세법에 따른 부가가치세 과세표준액이 5,500만원이고 다른 업종의 영업을 겸업하지 않으면 균등분의 납세의무를 지지 않는다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 주민세의 납세의무자"},{"y":2016,"e":"지방직 9급","qn":1,"i":"L92016-01-1","t":"사업소분 주민세의 과세기준일은 매년 7월 1일로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 주민세","t0":"균등분 주민세의 과세기준일은 매년 8월 1일로 한다.","ox0":"O","rv":"개정 반영"},{"y":2016,"e":"지방직 9급","qn":1,"i":"L92016-01-2","t":"재산분 주민세의 과세표준은 7월 1일 현재 보유부동산 가액으로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 주민세"},{"y":2016,"e":"지방직 9급","qn":1,"i":"L92016-01-3","t":"종업원분 주민세는 보통징수의 방법으로 징수한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 주민세"},{"y":2016,"e":"지방직 9급","qn":1,"i":"L92016-01-4","t":"지방자치단체의 장은 조례로 정하는 바에 따라 재산분 주민세를 법률에서 정하는 표준세율의 100분의 50의 범위를 한도로 하여 가감할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 주민세"},{"y":2016,"e":"지방직 9급","qn":12,"i":"L92016-12-1","t":"재화의 수입(輸入)은 지방소비세의 과세대상이 아니다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2016,"e":"지방직 9급","qn":12,"i":"L92016-12-2","t":"지방소비세의 납세지는 부가가치세법에 따른 부가가치세의 납세지로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2016,"e":"지방직 9급","qn":12,"i":"L92016-12-3","t":"지방소비세는 부가가치세법에 따라 부가가치세를 납부할 의무가 있는 자에게 부과한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2016,"e":"지방직 9급","qn":12,"i":"L92016-12-4","t":"부가가치세법에 따라 부가가치세를 신고·납부한 경우에는 지방소비세도 신고·납부한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2017,"e":"지방직 9급","qn":9,"i":"L92017-09-1","t":"특별징수의무자는 징수한 지방소비세를 다음 달 20일까지 관할 구역의 인구 등을 고려하여 대통령령으로 정하는 납입관리자에게 행정안전부령으로 정하는 징수명세서와 함께 납입하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세의 납입","t0":"특별징수의무자는 징수한 지방소비세를 다음 달 20일까지 관할 구역의 인구 등을 고려하여 대통령령으로 정하는 납입관리자에게 행정자치부령으로 정하는 징수명세서와 함께 납입하여야 한다.","ox0":"O","rv":"행정자치부령→행정안전부령"},{"y":2017,"e":"지방직 9급","qn":9,"i":"L92017-09-2","t":"특별징수의무자가 지방세법 제70조제1항에 따라 지방소비세를 환급하는 경우에는 납입관리자에게 납입하여야 할 금액에서 지방소비세환급금을 공제한다. 다만, 지방소비세환급금이 납입 하여야 할 금액을 초과하는 경우에는 초과된 지방소비세환급금은 그 다음 달로 이월한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소비세의 납입"},{"y":2017,"e":"지방직 9급","qn":9,"i":"L92017-09-3","t":"납입관리자는 지방세법 제71조제1항에 따라 납입된 지방 소비세를 지역별 소비지출 및 동법 제11조제1항제8호에 따른 취득세 감소분 등을 고려하여 대통령령으로 정하는 안분기준 및 안분방식에 따라 대통령령으로 정하는 기간 이내에 지방자치 단체의 장 및 시·도 교육감에게 납입하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소비세의 납입"},{"y":2017,"e":"지방직 9급","qn":9,"i":"L92017-09-4","t":"특별징수의무자가 징수하였거나 징수할 세액을 법령에 따른 기한까지 납입하지 아니하거나 부족하게 납입하는 경우에는 특별징수의무자에게 지방세기본법 제56조에 따른 특별징수 납부 등 불성실가산세를 부과한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지방소비세의 납입"},{"y":2017,"e":"지방직 9급","qn":19,"i":"L92017-19-1","t":"종업원분의 과세표준은 종업원에게 그 달에 지급한 소득세법 제12조제3호에 따른 비과세 대상 급여를 포함한 급여 총액으로 하고, 종업원분의 표준세율은 종업원 급여총액의 1천분의 5로 한다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 주민세의 과세표준과 세율"},{"y":2017,"e":"지방직 9급","qn":19,"i":"L92017-19-2","t":"재산분의 과세표준은 과세기준일 현재의 사업소 연면적으로 하고, 재산분의 표준세율은 사업소 연면적 1제곱미터당 250원으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 주민세의 과세표준과 세율"},{"y":2017,"e":"지방직 9급","qn":19,"i":"L92017-19-3","t":"지방자치단체에 사업소를 둔 개인의 균등분의 표준세율은 5만원이며, 지방자치단체의 장은 조례로 정하는 바에 따라 균등분의 세율을 표준세율의 100분의 50의 범위에서 가감할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 주민세의 과세표준과 세율"},{"y":2017,"e":"지방직 9급","qn":19,"i":"L92017-19-4","t":"지방자치단체의 관할구역에 주소를 둔 개인의 균등분의 세율은 지방자치단체의 장이 1만원을 초과하지 아니하는 범위에서 조례로 정하는 세액으로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 주민세의 과세표준과 세율"},{"y":2018,"e":"지방직 9급","qn":6,"i":"L92018-06-1","t":"출입국관리법에 따른 외국인등록을 한 날부터 과세기준일 현재 1년이 경과되지 아니한 외국인에 대해서는 지방세법 제78조제1항제1호가목에 따른 개인균등분과 재산분 주민세를 부과하지 아니한다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 주민세"},{"y":2018,"e":"지방직 9급","qn":6,"i":"L92018-06-2","t":"재산분의 납세의무자는 매년 6월 1일 현재 과세대장에 등재된 사업주로 한다. 다만, 사업소용 건축물의 소유자와 사업주가 다른 경우에는 대통령령으로 정하는 바에 따라 건축물의 소유자에게 제2차 납세의무를 지울 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 주민세"},{"y":2018,"e":"지방직 9급","qn":6,"i":"L92018-06-3","t":"지방세기본법 제34조에 따른 납세의무 성립일이 속하는 달부터 최근 1년간 해당 사업소 종업원 급여총액의 월평균 금액이 360만원에 50을 곱한 금액 이하인 경우에는 종업원분을 부과하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 주민세","t0":"지방세기본법 제34조에 따른 납세의무 성립일이 속하는 달부터 최근 1년간 해당 사업소 종업원 급여총액의 월평균 금액이 270만원에 50을 곱한 금액 이하인 경우에는 종업원분을 부과하지 아니한다.","ox0":"O","rv":"개정 반영"},{"y":2018,"e":"지방직 9급","qn":6,"i":"L92018-06-4","t":"재산분의 표준세율은 사업소 연면적 1제곱미터당 300원으로 하며, 폐수 또는 폐기물관리법에 따른 사업장폐기물 등을 배출하는 사업소로서 대통령령으로 정하는 오염물질 배출 사업소에 대하여는 해당세율의 100분의 200으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 주민세"},{"y":2018,"e":"지방직 9급","qn":12,"i":"L92018-12-1","t":"특별징수의무자는 납세지를 관할하는 세무서장 또는 부가가치 세법에 따라 재화의 수입에 대한 부가가치세를 징수하는 세관장이다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2018,"e":"지방직 9급","qn":12,"i":"L92018-12-2","t":"특별징수의무자가 징수하였거나 징수할 세액을 법정기한까지 납입하지 아니하면 특별징수의무자에게 지방세기본법상 특별징수납부 등 불성실가산세를 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2018,"e":"지방직 9급","qn":12,"i":"L92018-12-3","t":"특별징수의무자는 징수한 지방소비세를 다음 달 10일까지 관할구역의 인구 등을 고려하여 납입관리자에게 행정안전부령으로 정하는 징수명세서와 함께 납입하여야 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2018,"e":"지방직 9급","qn":12,"i":"L92018-12-4","t":"지방소비세의 세액은 지방소비세의 과세표준에 100분의 5를 적용하여 계산한 금액으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2019,"e":"지방직 9급","qn":7,"i":"L92019-07-1","t":"지방소비세의 납세지를 관할하는 세무서장 또는 부가가치세법에 따라 재화의 수입에 대한 부가가치세를 징수하는 세관장을 지방소비세의 특별징수의무자로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2019,"e":"지방직 9급","qn":7,"i":"L92019-07-2","t":"지방소비세의 세액은 부가가치세법에 따른 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 세액에 1천분의 253을 적용하여 계산한 금액으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소비세","t0":"지방소비세의 세액은 부가가치세법에 따른 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 세액에 100분의 15를 적용하여 계산한 금액으로 한다.","ox0":"O","rv":"개정 반영"},{"y":2019,"e":"지방직 9급","qn":7,"i":"L92019-07-3","t":"지방소비세는 부가가치세의 부과대상인 재화와 용역을 소비하는 자의 주소지 또는 소재지를 관할하는 특별시·광역시·특별자치시·도 또는 특별자치도에서 부가가치세법에 따라 부가가치세를 납부할 의무가 있는 자에게 부과한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2019,"e":"지방직 9급","qn":7,"i":"L92019-07-4","t":"특별징수의무자가 징수하였거나 징수할 세액을 납부기한까지 납입관리자에게 납입하지 아니하거나 부족하게 납입하는 경우, 납부하지 아니한 세액 또는 과소납부분 세액의 100분의 10을 한도로 특별징수의무자에게 지방세기본법에 따른 가산세를 부과한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2020,"e":"지방직 9급","qn":18,"i":"L92020-18-1","t":"지방소비세의 과세대상은 부가가치세법에서 정한 재화의 수입 및 사업자가 행하는 재화 또는 용역의 공급이다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2020,"e":"지방직 9급","qn":18,"i":"L92020-18-2","t":"부가가치세법에 따른 납세지를 관할하는 세무서장 또는 재화의 수입에 대한 부가가치세를 징수하는 세관장을 지방소비세의 특별징수의무자로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2020,"e":"지방직 9급","qn":18,"i":"L92020-18-3","t":"지방소비세의 부과·징수 및 불복절차 등에 관하여는 국세의 예를 따른다. 이 경우 국세청장을 그 처분청으로 본다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2020,"e":"지방직 9급","qn":18,"i":"L92020-18-4","t":"지방소비세의 과세표준은 부가가치세법에 따른 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 세액으로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2021,"e":"지방직 9급","qn":6,"i":"L92021-06-1","t":"지방소비세의 과세표준은 부가가치세법에 따른 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 세액으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2021,"e":"지방직 9급","qn":6,"i":"L92021-06-2","t":"지방소비세 특별징수의무자가 징수하였거나 징수할 세액을 다음 달 20일까지 납입하지 아니하거나 부족하게 납입한 경우에는 특별징수의무자에게 지방세기본법 제56조에 따른 특별징수 납부지연가산세를 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2021,"e":"지방직 9급","qn":6,"i":"L92021-06-3","t":"지방소비세는 지방세법 제65조에 따른 재화와 용역을 소비하는 자의 주소지 또는 소재지를 관할하는 특별시·광역시·특별자치시·도 또는 특별자치도에서 부가가치세법 제3조에 따라 부가가치세를 납부할 의무가 있는 자에게 부과한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2021,"e":"지방직 9급","qn":6,"i":"L92021-06-4","t":"지방소비세의 부과·징수 및 불복절차 등에 관하여는 국세의 예를 따르며, 이 경우 지방소비세 특별징수의무자를 그 처분청으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2022,"e":"지방직 9급","qn":14,"i":"L92022-14-1","t":"지방소비세의 과세대상은 부가가치세법 제4조에 따른 부가가치세의 과세대상과 동일하다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2022,"e":"지방직 9급","qn":14,"i":"L92022-14-2","t":"지방소비세는 지방세법 제68조에 따른 특별징수의무자가 징수한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2022,"e":"지방직 9급","qn":14,"i":"L92022-14-3","t":"지방소비세의 부과·징수 및 불복절차 등에 관하여는 지방세의 예를 따르며, 이 경우 지방자치단체의 장을 그 처분청으로 본다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2022,"e":"지방직 9급","qn":14,"i":"L92022-14-4","t":"지방소비세와 관련하여 지방세법 제6장(지방소비세)에 규정 되어 있지 아니한 사항에 관하여는 부가가치세법을 준용한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2023,"e":"지방직 9급","qn":4,"i":"L92023-04-1","t":"지방소비세와 부가가치세를 신고ㆍ납부ㆍ경정 및 환급할 경우에는 지방세법 제69조제2항에 따른 지방소비세와 부가가치세법 제72조(부가가치세의 세액 등에 관한 특례)에 따른 부가가치세가 합쳐진 금액으로 신고ㆍ납부ㆍ경정 및 환급하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2023,"e":"지방직 9급","qn":4,"i":"L92023-04-2","t":"부가가치세법 제58조제2항에 따라 재화의 수입에 대한 부가 가치세를 징수하는 세관장은 지방소비세의 납세의무자이다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2023,"e":"지방직 9급","qn":4,"i":"L92023-04-3","t":"지방소비세의 과세표준은 부가가치세법에 따른 부가가치세의 납부세액이며 부가가치세법에 따른 가산세를 더하지 아니한 세액으로 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2023,"e":"지방직 9급","qn":4,"i":"L92023-04-4","t":"지방소비세와 관련하여 지방세법 제6장(지방소비세)에 규정되어 있지 아니한 사항에 관하여는 지방자치단체의 조례로 정한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지방소비세"},{"y":2023,"e":"지방직 9급","qn":14,"i":"L92023-14","t":"지방세법령상 주민세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법령상 주민세에 대한 설명으로 옳은 것은?","d":"(단, 조례 및 지방세 특례는 고려하지 않는다)","o":["주민세 사업소분이란 지방자치단체에 소재한 사업소 연면적 및 종업원 수를 과세표준으로 하여 부과하는 주민세를 말한다.","과세기준일 현재 자본금액이 40억원이고 사업소 연면적이 300제곱 미터인 영리내국법인의 주민세 사업소분은 기본세율에 따라 산출한 세액인 10만원으로 한다.","주민세 사업소분의 과세표준인 사업소 연면적은 건축법 제2조 제1항제2호에 따른 건축물의 연면적으로 하며, 여기에는 종업원의 후생에 직접 사용하는 기숙사와 사택의 연면적이 포함된다.","지방세기본법 제35조에 따른 납세의무 확정일이 속하는 달부터 최근 1년간 해당 사업소 종업원 급여총액의 월평균금액이 2억원 이하인 경우에는 주민세 종업원분을 부과하지 아니한다."],"a":2}},{"y":2024,"e":"지방직 9급","qn":8,"i":"L92024-08-1","t":"국민기초생활 보장법에 따른 수급자, 출입국관리법에 따른 외국인등록을 한 날부터 1년이 경과되지 아니한 외국인은 개인분의 납세의무자에서 제외한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 주민세"},{"y":2024,"e":"지방직 9급","qn":8,"i":"L92024-08-2","t":"지방자치단체에 사업소를 둔 법인으로서 과세기준일 현재 1년 이상 계속하여 휴업하고 있는 법인은 사업소분의 납세의무자에서 제외한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 주민세"},{"y":2024,"e":"지방직 9급","qn":8,"i":"L92024-08-3","t":"개인분의 징수는 신고납부의 방법으로 하고, 사업소분과 종업원분은 납세지를 관할하는 지방자치단체의 장이 보통징수의 방법으로 징수한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 주민세"},{"y":2024,"e":"지방직 9급","qn":8,"i":"L92024-08-4","t":"국가, 지방자치단체 및 지방자치단체조합에 대하여는 주민세를 부과하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 주민세"},{"y":2025,"e":"지방직 9급","qn":13,"i":"L92025-13-1","t":"지방소비세는 과세대상이 되는 재화와 용역을 소비하는 자의 주소지 또는 소재지를 관할하는 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도에서 부가가치세법에 따라 부가가치세를 납부할 의무가 있는 자에게 부과한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소비세"},{"y":2025,"e":"지방직 9급","qn":13,"i":"L92025-13-2","t":"지방소비세의 납세지를 관할하는 세무서장 또는 부가가치세법에 따라 재화의 수입에 대한 부가가치세를 징수하는 세관장을 지방소비세의 특별징수의무자로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소비세"},{"y":2025,"e":"지방직 9급","qn":13,"i":"L92025-13-3","t":"지방소비세의 부과ㆍ징수 및 불복절차 등에 관하여는 국세의 예를 따른다. 이 경우 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ 특별자치도지사 등을 그 처분청으로 본다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방소비세"},{"y":2025,"e":"지방직 9급","qn":13,"i":"L92025-13-4","t":"지방소비세와 관련하여 지방세법에 규정되어 있지 아니한 사항에 관하여는 부가가치세법을 준용한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소비세"}],"2":[{"y":2015,"e":"지방직 9급","qn":4,"i":"L92015-04-1","t":"승마회원권, 콘도미니엄 회원권을 취득한 자는 취득세의 납세 의무자가 된다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세"},{"y":2015,"e":"지방직 9급","qn":4,"i":"L92015-04-2","t":"취득세의 과세대상이 되는 취득이란 원시취득과 승계취득을 말하므로 차량, 기계장비, 항공기 및 주문을 받아 건조하는 선박의 원시취득은 취득세의 과세대상이 된다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 취득세"},{"y":2015,"e":"지방직 9급","qn":4,"i":"L92015-04-3","t":"취득세 과세물건을 취득한 자는 그 취득한 날부터 60일 이내 (상속이나 실종에 의한 경우는 별도 규정 적용)에 그 과세표준에 세율을 적용하여 산출한 세액을 대통령령으로 정하는 바에 따라 신고하고 납부하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세"},{"y":2015,"e":"지방직 9급","qn":4,"i":"L92015-04-4","t":"지방자치단체의 장은 조례로 정하는 바에 따라 취득세율을 지방세법 제11조와 제12조에 따른 세율의 100분의 50의 범위에서 가감할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 취득세"},{"y":2015,"e":"지방직 9급","qn":6,"i":"L92015-06-1","t":"연부로 취득하는 것(취득가액 총액이 50만원 이하인 것은 제외)은 그 사실상의 연부금 지급일을 취득일로 본다. 단, 취득일 전에 등기 또는 등록한 경우에는 그 등기일 또는 등록일에 취득한 것으로 본다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세 부과와 관련한 취득시기"},{"y":2015,"e":"지방직 9급","qn":6,"i":"L92015-06-2","t":"취득자의 편의에 따라 수입물건을 우리나라에 반입하지 아니 하거나 보세구역을 경유하지 아니하고 외국에서 직접 사용하는 경우에는 그 수입물건의 등기 또는 등록일을 취득일로 본다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세 부과와 관련한 취득시기"},{"y":2015,"e":"지방직 9급","qn":6,"i":"L92015-06-3","t":"선박의 종류변경에 따른 취득은 사실상 변경한 날과 공부상 변경한 날 중 빠른 날을 취득일로 본다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세 부과와 관련한 취득시기"},{"y":2015,"e":"지방직 9급","qn":6,"i":"L92015-06-4","t":"관계 법령에 따라 매립·간척 등으로 토지를 원시취득하는 경우로서 공사준공인가일 전에 사실상 사용하다가 사용허가를 받은 경우에는 사용허가일을 취득일로 본다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 취득세 부과와 관련한 취득시기"},{"y":2015,"e":"지방직 9급","qn":12,"i":"L92015-12-1","t":"취득세의 과세표준은 취득 당시의 가액(연부취득의 경우 연부금액)으로 한다. 취득 당시의 가액은 취득자가 신고한 가액으로 하는 것이 원칙이지만, 신고 또는 신고가액의 표시가 없거나 그 신고가액이 지방세법상 시가표준액보다 적을 때에는 그 시가표준액으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2015,"e":"지방직 9급","qn":12,"i":"L92015-12-2","t":"국가로부터 유상취득하는 경우에는 신고 또는 신고가액의 표시가 없거나 그 신고가액이 시가표준액에 미달하더라도 그 사실상의 취득가격 또는 연부금액을 과세표준으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2015,"e":"지방직 9급","qn":12,"i":"L92015-12-3","t":"토지의 지목을 사실상 변경하여 토지의 가액이 증가한 경우에는 그로 인하여 증가한 가액을 취득세의 과세표준으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2015,"e":"지방직 9급","qn":12,"i":"L92015-12-4","t":"개인사업자가 작성한 장부(원장)에 의하여 취득가격이 증명 되는 경우로서 그 가액으로 신고한 경우에는 그 신고가액이 시가표준액에 미달하여도 그 신고가액을 취득세의 과세표준으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2016,"e":"지방직 9급","qn":4,"i":"L92016-04-1","t":"권리의 이전이나 행사에 등기 또는 등록이 필요한 부동산 등을 직계존비속 간에 서로 교환하여 취득한 경우에는 유상으로 취득한 것으로 본다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세"},{"y":2016,"e":"지방직 9급","qn":4,"i":"L92016-04-2","t":"토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세"},{"y":2016,"e":"지방직 9급","qn":4,"i":"L92016-04-3","t":"법인설립 시에 발행하는 주식 또는 지분을 취득함으로써 지방세기본법 제46조(출자자의 제2차 납세의무)제2호에 따른 과점주주가 되었을 때에는 그 과점주주가 해당 법인의 부동산 등을 취득한 것으로 보지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세","t0":"법인설립 시에 발행하는 주식 또는 지분을 취득함으로써 지방세기본법 제47조(출자자의 제2차 납세의무)제2호에 따른 과점주주가 되었을 때에는 그 과점주주가 해당 법인의 부동산 등을 취득한 것으로 보지 아니한다.","ox0":"O","rv":"개정 반영"},{"y":2016,"e":"지방직 9급","qn":4,"i":"L92016-04-4","t":"상속으로 인하여 재산을 취득하는 경우에는 상속인 전부가 상속받은 재산을 공동으로 취득한 것으로 본다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 취득세"},{"y":2016,"e":"지방직 9급","qn":17,"i":"L92016-17-1","t":"대한민국 정부기관의 취득에 대하여 취득세를 부과하지 아니 하는 외국정부의 취득에 대하여는 취득세를 부과하지 아니한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세의 과세"},{"y":2016,"e":"지방직 9급","qn":17,"i":"L92016-17-2","t":"국가 또는 지방자치단체에 귀속 또는 기부채납할 것을 조건으로 부동산을 취득하는 경우라도 그 반대급부로 기부채납 대상물의 무상사용권을 제공받는 때에는 취득세를 부과한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세의 과세"},{"y":2016,"e":"지방직 9급","qn":17,"i":"L92016-17-3","t":"주택법 제11조에 따른 주택조합이 해당 조합원용으로 취득 하는 조합주택용 부동산(공동주택과 부대시설·복리시설 및 그 부속토지를 말한다)은 주택조합이 취득한 것으로 본다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 취득세의 과세"},{"y":2016,"e":"지방직 9급","qn":17,"i":"L92016-17-4","t":"존속기간이 1년을 초과하는 임시흥행장이나 공사현장사무소의 취득에 대하여는 취득세를 부과한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 취득세의 과세"},{"y":2016,"e":"지방직 9급","qn":20,"i":"L92016-20-1","t":"토지의 지목변경에 따른 취득은 토지의 지목이 사실상 변경된 날과 공부상 변경된 날 중 빠른 날을 취득일로 보지만, 토지의 지목변경일 이전에 사용하는 부분에 대하여는 그 사실상의 사용일을 취득일로 본다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세"},{"y":2016,"e":"지방직 9급","qn":20,"i":"L92016-20-2","t":"무상승계취득의 경우 해당 취득물건을 등기·등록하였더라도 화해조서·인낙조서·공정증서에 의하여 60일 이내에 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 아니 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 취득세"},{"y":2016,"e":"지방직 9급","qn":20,"i":"L92016-20-3","t":"골프회원권, 승마회원권, 콘도미니엄 회원권의 존속기한 또는 입회기간을 연장하는 경우에는 기간이 새로 시작되는 날을 취득일로 본다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세"},{"y":2016,"e":"지방직 9급","qn":20,"i":"L92016-20-4","t":"국가, 지방자치단체로부터의 유상승계취득은 사실상의 잔금 지급일 전에 등기 또는 등록을 한 경우에는 그 등기일 또는 등록일에 취득한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 취득세"},{"y":2017,"e":"지방직 9급","qn":15,"i":"L92017-15","t":"지방세법 상 취득세가 과세되는 경우 중과(重課)하지 아니하는 것은?","c":"A","mc":{"s":"지방세법 상 취득세가 과세되는 경우 중과(重課)하지 아니하는 것은?","d":"(단, 취득한 날 이후 다른 용도로 사용하기 위한 용도변경 공사 등은 없다고 가정한다)","o":["1구의 건축물에 에스컬레이터 또는 67제곱미터 이상의 수영장 중 1개 이상의 시설이 설치된 주거용 건축물과 그 부속토지 (공동주택과 그 부속토지 제외)를 취득하고 그 날부터 계속 하여 주거용으로 사용한 경우","시가표준액이 4억원인 비업무용 자가용 선박을 실험․실습 등의 용도 외에 사용할 목적으로 취득하는 경우","체육시설의 설치ㆍ이용에 관한 법률 에 따른 회원제 골프장용 부동산 중 구분등록의 대상이 되는 토지와 건축물 및 그 토지 상(上)의 입목을 취득하는 경우","고급오락장용 건축물을 취득하고 그 날부터 계속하여 고급 오락장이 아닌 용도로 사용한 경우"],"a":4}},{"y":2017,"e":"지방직 9급","qn":20,"i":"L92017-20","t":"지방세법 상 甲이 다음 사례와 같이 주식등을 취득하여 과점주주 로서 취득세가 과세되는 경우, 과점주주 甲이 취득한 것으로 보는 주식등의 비율로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법 상 甲이 다음 사례와 같이 주식등을 취득하여 과점주주 로서 취득세가 과세되는 경우, 과점주주 甲이 취득한 것으로 보는 주식등의 비율로 옳지 않은 것은?","d":"(단위: %) 사례 구 분 설립 시 주식등의 비율 증가한 주식등의 비율 주식등의 비율 누계 취득한 것으로 보는 주식등의 비율 A 법인설립 시 취득 35 － 35 － 증자 등으로 취득 － 25 60 60 B 법인설립 시 취득 60 － 60 － 증자 등으로 취득 － 20 80 80 C 법인설립 시 취득 10 － 10 － 1차 증자 등으로 취득 － 50 60 60 2차 증자 등으로 취득 － 10 70 10 D 법인설립 시 취득 10 － 10 － 1차 증자 등으로 취득 － 20 30 － 2차 증자 등으로 취득 － 35 65 65","o":["A","B","C","D"],"a":2}},{"y":2018,"e":"지방직 9급","qn":7,"i":"L92018-07","t":"지방세법 상 취득세가 과세되지 않는 경우는?","c":"A","mc":{"s":"지방세법 상 취득세가 과세되지 않는 경우는?","d":"","o":["선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우의 취득","외국인 소유의 취득세 과세대상 물건(차량, 기계장비, 항공기 및 선박만 해당)을 직접 사용하거나 국내의 대여시설 이용자에게 대여하기 위하여 임차하여 수입하는 경우의 취득","권리의 이전이나 행사에 등기 또는 등록이 필요한 부동산등을 배우자간 서로 교환한 경우의 취득","민법 에 따른 채권자대위권의 행사에 의하여 공동상속인들의 법정상속분대로 등기 등이 된 상속재산을 상속인사이의 협의 분할에 의하여 재분할하는 경우의 취"],"a":4}},{"y":2018,"e":"지방직 9급","qn":15,"i":"L92018-15-1","t":"화해조서에 의하여 취득가격이 입증되면 그 취득가격을 과세 표준으로 한다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 취득세 과세표준"},{"y":2018,"e":"지방직 9급","qn":15,"i":"L92018-15-2","t":"부동산을 연부로 취득하는 경우 과세표준은 연부금액으로 하되, 취득금액에 포함되는 계약보증금을 포함한다.","ox":"O","m":"②","c":"A","tp":"지방세법령상 취득세 과세표준"},{"y":2018,"e":"지방직 9급","qn":15,"i":"L92018-15-3","t":"취득세의 과세표준인 취득 당시의 가액은 취득자가 신고한 가액으로 한다. 다만, 신고 또는 신고가액의 표시가 없거나 그 신고가액이 지방세법상 시가표준액보다 적을 때에는 그 시가표준액으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 취득세 과세표준"},{"y":2018,"e":"지방직 9급","qn":15,"i":"L92018-15-4","t":"외국으로부터의 수입에 의하여 취득세 과세대상 자산을 유상 취득하는 경우에는(소득세법 및 법인세법상 부당행위 계산부인의 경우는 제외) 그 사실상의 취득가격 또는 연부금액이 시가표준액보다 적더라도 그 사실상의 취득가격 또는 연부 금액을 과세표준으로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법령상 취득세 과세표준"},{"y":2019,"e":"지방직 9급","qn":2,"i":"L92019-02-1","t":"토지의 지목을 사실상 변경한 경우에는 그 가액의 증가 여부에 관계없이 취득으로 본다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 취득세의 납세의무자"},{"y":2019,"e":"지방직 9급","qn":2,"i":"L92019-02-2","t":"파산선고로 인하여 처분되는 배우자 또는 직계존비속의 부동산등을 취득하는 경우에는 유상으로 취득한 것으로 본다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세의 납세의무자"},{"y":2019,"e":"지방직 9급","qn":2,"i":"L92019-02-3","t":"외국인 소유의 취득세 과세대상인 선박을 직접 사용하거나 국내의 대여시설 이용자에게 대여하기 위하여 임차하여 수입하는 경우에는 수입하는 자가 취득한 것으로 본다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세의 납세의무자"},{"y":2019,"e":"지방직 9급","qn":2,"i":"L92019-02-4","t":"건축물 중 조작(造作) 설비, 그 밖의 부대설비에 속하는 부분으로서 그 주체구조부(主體構造部)와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설(加設)한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 취득세의 납세의무자"},{"y":2019,"e":"지방직 9급","qn":15,"i":"L92019-15","t":"지방세법 상 부동산의 취득으로 취득세를 납부하는 때에 함께 납부하여야 하는 조세에 해당하는 것은?","c":"A","mc":{"s":"지방세법 상 부동산의 취득으로 취득세를 납부하는 때에 함께 납부하여야 하는 조세에 해당하는 것은?","d":"","o":["주민세","지방교육세","등록면허세","지방소득세"],"a":2}},{"y":2019,"e":"지방직 9급","qn":20,"i":"L92019-20-1","t":"법인 설립 시 40 %의 주식을 가진 주주가 추가로 20 %의 주식을 취득하여 총 60 %의 주식을 소유하게 되었다면, 취득으로 간주되는 비율은 60 %이다.","ox":"O","m":"①","c":"A","tp":"지방세법령상 취득세를 납부해야 하는 과점주주의 간주취득"},{"y":2019,"e":"지방직 9급","qn":20,"i":"L92019-20-2","t":"법인 설립 시 60 %의 주식을 가진 주주가 추가로 10 %의 주식을 취득하여 총 70 %의 주식을 소유하게 되었다면, 취득으로 간주되는 비율은 10 %이다.","ox":"O","m":"②","c":"A","tp":"지방세법령상 취득세를 납부해야 하는 과점주주의 간주취득"},{"y":2019,"e":"지방직 9급","qn":20,"i":"L92019-20-3","t":"법인 설립 후 60 %의 주식을 가진 주주가 추가로 10 %의 주식을 취득하여 총 70 %의 주식을 소유하게 되었다면, 취득으로 간주되는 비율은 10 %이다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 취득세를 납부해야 하는 과점주주의 간주취득"},{"y":2019,"e":"지방직 9급","qn":20,"i":"L92019-20-4","t":"법인 설립 후 60 %의 주식을 가진 주주가 15 %의 주식을 양도하여 총 45 %의 주식을 소유하던 중 추가로 10 %의 주식을 취득하여 총 55 %의 주식을 소유하게 되었다면, 취득으로 간주되는 비율은 5 %이다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 취득세를 납부해야 하는 과점주주의 간주취득"},{"y":2020,"e":"지방직 9급","qn":10,"i":"L92020-10-1","t":"취득세의 과세표준은 취득 당시의 가액으로 한다. 다만, 연부(年賦)로 취득하는 경우에는 연부금액(매회 사실상 지급되는 금액을 말하며, 취득금액에 포함되는 계약보증금을 포함)으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2020,"e":"지방직 9급","qn":10,"i":"L92020-10-2","t":"취득 당시의 가액은 취득자가 신고한 가액으로 한다. 다만, 신고 또는 신고가액의 표시가 없거나 그 신고가액이 지방세법에서 정하고 있는 시가표준액보다 적을 때에는 그 시가표준액으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2020,"e":"지방직 9급","qn":10,"i":"L92020-10-3","t":"건축물을 건축(신축과 재축은 제외)하거나 개수한 경우와 대통령령으로 정하는 선박, 차량 및 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경한 경우에는 그로 인하여 증가한 가액을 각각 과세표준으로 한다. 이 경우 신고 또는 신고가액의 표시가 없거나 신고가액이 대통령령으로 정하는 시가표준액보다 적을 때에는 그 시가표준액으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2020,"e":"지방직 9급","qn":10,"i":"L92020-10-4","t":"국가, 지방자치단체 또는 지방자치단체조합으로부터 취득한 경우 신고 또는 신고가액의 표시가 없거나 신고가액이 대통령령으로 정하는 시가표준액보다 적을 때에는 그 시가 표준액으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 취득세의 과세표준"},{"y":2020,"e":"지방직 9급","qn":17,"i":"L92020-17","t":"지방세법령상 취득세의 과세표준을 사실상의 취득가격 또는 연부금액으로 하는 경우로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법령상 취득세의 과세표준을 사실상의 취득가격 또는 연부금액으로 하는 경우로 옳지 않은 것은?","d":"(단, 소득세법 상 양도소득의 부당행위계산 및 법인세법 상 부당행위계산 부인에 따른 거래로 인한 취득은 제외함)","o":["화해조서에 의하여 취득가격이 입증되는 유상승계취득","외국으로부터 수입에 의한 유상승계취득","법인장부 중 대통령령으로 정하는 것에 따라 취득가격이 증명되는 유상승계취득","국가․지방자치단체 및 지방자치단체조합으로부터의 유상승계 취득"],"a":1}},{"y":2021,"e":"지방직 9급","qn":9,"i":"L92021-09","t":"지방세법 상 취득세 표준세율에서 중과기준세율을 뺀 세율로 산출한 금액을 취득세액으로 하지 않는 것은?","c":"A","mc":{"s":"지방세법 상 취득세 표준세율에서 중과기준세율을 뺀 세율로 산출한 금액을 취득세액으로 하지 않는 것은?","d":"(단, 취득물건은 지방세법 제13조제2항에 해당되지 않고, 제11조제1항제8호에 따른 주택은 제외하며, 지방세특례는 고려하지 않음)","o":["환매등기를 병행하는 부동산의 매매로서 환매기간 내에 매도자가 환매한 경우의 그 매도자와 매수자의 취득","공유물의 분할로 인한 취득(등기부등본상 본인 지분을 초과하지 아니함)","건축물의 이전으로 인한 취득(이전한 건축물의 가액이 종전 건축물의 가액을 초과하지 아니함)","개수로 인한 취득(개수로 인하여 건축물 면적이 증가하지 아니함)"],"a":4}},{"y":2022,"e":"지방직 9급","qn":19,"i":"L92022-19","t":"甲이 비상장법인 (주)A의 의결권 있는 주식의 취득 및 양도 행위를 반복하여 (주)A의 주식 총액에 대한 甲이 가진 주식의 비율이 다음과 같이 변동되었다. 甲이 75 %를 보유하게 된 시점에 취득세의 부과범위는?","c":"A","mc":{"s":"甲이 비상장법인 (주)A의 의결권 있는 주식의 취득 및 양도 행위를 반복하여 (주)A의 주식 총액에 대한 甲이 가진 주식의 비율이 다음과 같이 변동되었다. 甲이 75 %를 보유하게 된 시점에 취득세의 부과범위는?","d":"(단, 甲은 지방세법 에 따른 과점주주의 취득세 과세요건을 충족하고, 주식의 비율 변동과 관련된 체납세액이 없으며, 지방세 특례는 고려하지 않는다) 변동 순서 구분 (주)A의 주식 총액에 대한 甲이 가진 주식의 비율\n(1)\n(2)\n(3)\n(4) (주)A 설립 시 취득 51 % 추가 취득 9 % 일부 양도 20 % 추가 취득 35 % 51 % 60 % 40 % 75 %","o":["주식의 비율 15 % 증가분","주식의 비율 24 % 증가분","주식의 비율 35 % 증가분","주식의 비율 75 % 증가분"],"a":1}},{"y":2023,"e":"지방직 9급","qn":18,"i":"L92023-18","t":"(단, 취득물건은 지방세법 제13조(과밀억제권역 안 취득 등 중과)제1항 및 제5항에 해당하지 않는다) ㄱ.","c":"A","mc":{"s":"(단, 취득물건은 지방세법 제13조(과밀억제권역 안 취득 등 중과)제1항 및 제5항에 해당하지 않는다) ㄱ.","d":"지방세법령상 취득세액을 계산할 때 중과기준세율을 적용하는 것만을 모두 고르면?  외국인 소유의 취득세 과세대상 차량을 임차하여 수입하는 경우의 취득(연부로 취득한 경우가 아님)\nㄴ. 지방세법 제7조제5항에 따른 과점주주의 취득\nㄷ. 여신전문금융업법 제33조제1항에 따라 차량을 등록한 대여시설이용자가 그 시설대여업자로부터 취득하는 차량의 취득\nㄹ. 존속기간이 1년을 초과하는 임시건축물의 취득","o":["ㄱ, ㄹ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2024,"e":"지방직 9급","qn":12,"i":"L92024-12-1","t":"토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세"},{"y":2024,"e":"지방직 9급","qn":12,"i":"L92024-12-2","t":"증여자의 채무를 인수하는 부담부 증여의 경우(배우자 또는 직계 존비속으로부터의 부담부 증여는 아님)에는 그 채무액에 상당하는 부분은 부동산등을 유상으로 취득하는 것으로 본다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 취득세"},{"y":2024,"e":"지방직 9급","qn":12,"i":"L92024-12-3","t":"주택법에 따른 주택조합이 해당 조합원용으로 취득하는 조합 주택용 부동산(조합원에게 귀속되지 아니하는 부동산은 제외함)은 그 주택조합이 취득한 것으로 본다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 취득세"},{"y":2024,"e":"지방직 9급","qn":12,"i":"L92024-12-4","t":"기계장비나 차량을 기계장비대여업체 또는 운수업체의 명의로 등록하는 경우(영업용으로 등록하는 경우로 한정함)라도 해당 기계장비나 차량의 구매계약서, 세금계산서, 차주대장 등에 비추어 기계장비나 차량의 취득대금을 지급한 자가 따로 있음이 입증되는 경우 그 기계장비나 차량은 취득대금을 지급한 자가 취득한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 취득세"},{"y":2024,"e":"지방직 9급","qn":17,"i":"L92024-17","t":"지방세법 상 부동산에 대한 취득세를 계산할 때 적용되는 표준세율이 다른 것은?","c":"A","mc":{"s":"지방세법 상 부동산에 대한 취득세를 계산할 때 적용되는 표준세율이 다른 것은?","d":"(단, 조례에 따른 세율 조정 및 세율의 특례 등 별도로 제시되지 않은 사항은 고려하지 않음)","o":["상속으로 인한 농지 외의 것의 취득","상속으로 인한 취득 외의 무상취득 중 대통령령으로 정하는 비영리사업자의 취득","원시취득","합유물 및 총유물의 분할로 인한 취득"],"a":4}},{"y":2025,"e":"지방직 9급","qn":8,"i":"L92025-08-1","t":"차량과 기계장비의 종류를 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 취득세의 납세의무자 등"},{"y":2025,"e":"지방직 9급","qn":8,"i":"L92025-08-2","t":"도시개발법에 따른 환지방식에 의한 도시개발사업의 시행으로 토지의 지목이 사실상 변경되어 그 가액이 증가한 때에는 그 환지계획에 따라 공급되는 환지는 사업시행자가 취득한 것으로 본다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 취득세의 납세의무자 등"},{"y":2025,"e":"지방직 9급","qn":8,"i":"L92025-08-3","t":"광업법에 따른 등록을 하지 아니한 광업권을 사실상 취득한 경우에는 광업권을 취득한 것으로 본다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 취득세의 납세의무자 등"},{"y":2025,"e":"지방직 9급","qn":8,"i":"L92025-08-4","t":"직계비속의 부동산을 경매를 통하여 취득하는 경우에는 유상으로 취득한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 취득세의 납세의무자 등"},{"y":2025,"e":"지방직 9급","qn":11,"i":"L92025-11","t":"지방세법령상 취득세의 과세표준에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법령상 취득세의 과세표준에 대한 설명으로 옳지 않은 것은?","d":"(단, 시가표준액은 지방세법 제4조에 따른 시가표준액을 말한다)","o":["취득세의 과세표준은 취득 당시의 가액으로 한다. 다만, 연부로 취득하는 경우에는 연부금액으로 한다.","시가표준액이 1억원을 초과하는 부동산을 상속 외의 원인으로 무상 취득하는 경우 취득당시가액은 시가인정액으로 하되, 시가인정액을 산정하기 어려운 경우에는 시가표준액으로 한다.","부동산을 원시취득하는 경우 취득당시가액은 사실상취득가격으로 하되, 법인이 아닌 자가 건축물을 건축하여 취득하는 경우로서 사실상취득가격을 확인할 수 없는 경우의 취득당시가액은 시가 표준액으로 한다.","특수관계인이 아닌 자로부터 대물변제로 부동산을 취득하는 경우 취득당시가액은 대물변제액(대물변제액 외에 추가로 지급한 금액이 있는 경우에는 그 금액을 차감한다)으로 한다."],"a":4}},{"y":2025,"e":"지방직 9급","qn":14,"i":"L92025-14","t":"지방세법령상 취득세에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세법령상 취득세에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 납세의무자가 지목변경으로 토지를 사실상 취득한 후 산출세액 신고를 하지 아니하고 매각하는 경우에는 산출세액에 100분의 80을 가산한 금액을 세액으로 하여 징수한다.\nㄴ. 외국인 소유의 취득세 과세대상 물건(차량, 기계장비, 항공기 및 선박만 해당한다)을 직접 사용하거나 국내의 대여시설 이용자에게 대여하기 위하여 소유권을 이전 받는 조건으로 임차하여 수입하는 경우에는 수입하는 자가 취득한 것으로 본다.\nㄷ. 증여자의 채무를 인수하는 부담부 증여로 인해 취득세 과세물건을 취득한 자는 취득일이 속하는 달의 말일부터 3개월 이내에 그 과세표준에 지방세법 제11조부터 제15조의 세율을 적용하여 산출한 세액을 대통령령으로 정하는 바에 따라 신고하고 납부하여야 한다.","o":["ㄴ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ"],"a":4}}],"4":[{"y":2015,"e":"지방직 9급","qn":5,"i":"L92015-05","t":"지방세법령에 규정된 재산세 비과세대상으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법령에 규정된 재산세 비과세대상으로 옳지 않은 것은?","d":"(단, 해당 재산은 대통령령으로 정하는 수익사업에 사용되거나 유료로 사용되지 아니하며 지방세법 제13조 제5항에 규정된 중과대상 재산에도 해당하지 아니한다)","o":["재산세를 부과하는 해당 연도에 철거하기로 계획이 확정되어 재산세 과세기준일 현재 행정관청으로부터 철거명령을 받았거나 철거보상계약이 체결된 건축물","농업용 구거와 자연유수의 배수처리에 제공하는 구거","임시로 사용하기 위하여 건축된 건축물로서 재산세 과세기준일 현재 2년 미만의 것","비상재해구조용, 무료도선용, 선교(船橋)구성용 및 본선에 속하는 전마용(傳馬用) 등으로 사용하는 선박"],"a":3}},{"y":2015,"e":"지방직 9급","qn":8,"i":"L92015-08-1","t":"상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 때에는 행정안전부령으로 정하는 주된 상속자를 재산세의 납세의무자로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세 납세의무자","t0":"상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 때에는 행정자치부령으로 정하는 주된 상속자를 재산세의 납세의무자로 한다.","ox0":"O","rv":"행정자치부령→행정안전부령"},{"y":2015,"e":"지방직 9급","qn":8,"i":"L92015-08-2","t":"재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 재산세 납세의무자"},{"y":2015,"e":"지방직 9급","qn":8,"i":"L92015-08-3","t":"공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중 재산인 경우 종중소유임을 신고하지 아니하였을 경우에도 그 종중을 납세의무자로 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 재산세 납세의무자"},{"y":2015,"e":"지방직 9급","qn":8,"i":"L92015-08-4","t":"국가, 지방자치단체, 지방자치단체조합과 재산세 과세대상 재산을 연부로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우에는 그 매수계약자를 납세의무자로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 재산세 납세의무자"},{"y":2016,"e":"지방직 9급","qn":11,"i":"L92016-11-1","t":"항공기, 선박 및 자동차는 재산세의 과세대상이다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 재산세"},{"y":2016,"e":"지방직 9급","qn":11,"i":"L92016-11-2","t":"재산세 납세의무자는 과세기준일 현재 재산의 등기부 또는 등록부상 소유자로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 재산세"},{"y":2016,"e":"지방직 9급","qn":11,"i":"L92016-11-3","t":"재산세는 신고납부의 방법으로 징수한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 재산세"},{"y":2016,"e":"지방직 9급","qn":11,"i":"L92016-11-4","t":"지방자치단체의 장은 재산세의 납부세액이 1천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 재산세"},{"y":2017,"e":"지방직 9급","qn":12,"i":"L92017-12-1","t":"주택에 대한 재산세는 주택의 소재지를 관할하는 지방자치단체에서 부과한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세"},{"y":2017,"e":"지방직 9급","qn":12,"i":"L92017-12-2","t":"주택에 대한 과세표준은 지방세법 제4조제1항 및 제2항에 따른 시가표준액에 부동산 시장의 동향과 지방재정 여건 등을 고려하여 시가표준액의 100분의 40부터 100분의 80까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱하여 산정한 가액으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 재산세"},{"y":2017,"e":"지방직 9급","qn":12,"i":"L92017-12-3","t":"지방자치단체의 장은 특별한 재정수요나 재해 등의 발생으로 재산세의 세율 조정이 불가피하다고 인정되는 경우 조례로 정하는 바에 따라 지방세법 제111조제1항의 표준세율의 100분의 50의 범위에서 가감할 수 있으며, 그 가감한 세율은 해당 연도에만 적용한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 재산세"},{"y":2017,"e":"지방직 9급","qn":12,"i":"L92017-12-4","t":"주택의 건물과 부속토지의 소유자가 같은 경우 그 주택에 대한 재산세는 해당 연도에 부과할 세액을 건물분 세액과 토지분 세액으로 구분하여 각각 연 2회 부과한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":3,"i":"L92018-03-1","t":"재산세는 토지, 건축물, 주택, 항공기 및 선박을 과세대상으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":3,"i":"L92018-03-2","t":"공유재산으로서 그 지분의 표시가 없는 경우에는 각 납세 의무자의 지분이 균등한 것으로 본다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":3,"i":"L92018-03-3","t":"재산세 과세기준일 현재 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 사실상 소유자를 납세의무자로 본다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":3,"i":"L92018-03-4","t":"재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":11,"i":"L92018-11-1","t":"지방자치단체의 장은 재산세의 납부세액이 1천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":11,"i":"L92018-11-2","t":"고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":11,"i":"L92018-11-3","t":"재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과·징수한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 재산세"},{"y":2018,"e":"지방직 9급","qn":11,"i":"L92018-11-4","t":"주택에 대한 재산세의 산출세액이 직전 연도의 해당 주택에 대한 재산세액 상당액의 100분의 150을 초과하는 경우에는 100분의 150에 해당하는 금액을 해당 연도에 징수할 세액으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 재산세"},{"y":2019,"e":"지방직 9급","qn":13,"i":"L92019-13-1","t":"재산세의 과세대상 물건이 공부상 등재 현황과 사실상의 현황이 다른 경우에는 공부상 등재 현황에 따라 재산세를 부과한다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 재산세"},{"y":2019,"e":"지방직 9급","qn":13,"i":"L92019-13-2","t":"주택의 건물과 부속토지의 소유자가 다를 경우 건물의 소유자를 부속토지에 대한 재산세의 납세의무자로 본다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 재산세"},{"y":2019,"e":"지방직 9급","qn":13,"i":"L92019-13-3","t":"재산세 과세기준일 현재 공부상의 소유자가 매매 등의 사유로 소유권이 변동되었는데도 신고하지 아니하여 사실상의 소유자를 알 수 없는 경우 공부상 소유자는 재산세를 납부할 의무가 있다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 재산세"},{"y":2019,"e":"지방직 9급","qn":13,"i":"L92019-13-4","t":"국가가 1년 이상 공용 또는 공공용으로 사용하는 재산에 대하여는 유료로 사용하는 경우 재산세를 부과하지 아니한다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 재산세"},{"y":2020,"e":"지방직 9급","qn":8,"i":"L92020-08-1","t":"재산세는 토지, 건축물, 주택, 항공기 및 선박을 과세대상으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세와 자동차 소유"},{"y":2020,"e":"지방직 9급","qn":8,"i":"L92020-08-2","t":"토지에 대한 재산세 과세대상 중 과세기준일 현재 납세의무자가 소유하고 있는 토지 중 종합합산과세대상 또는 분리과세대상이 되는 토지를 제외한 토지는 원칙적으로 별도합산과세대상에 해당한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 재산세와 자동차 소유"},{"y":2020,"e":"지방직 9급","qn":8,"i":"L92020-08-3","t":"과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매수인이 자동차세를 납부할 의무를 진다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 재산세와 자동차 소유"},{"y":2020,"e":"지방직 9급","qn":8,"i":"L92020-08-4","t":"지방자치단체가 환자수송·청소·오물제거 또는 도로공사를 위하여 제공하는 자동차를 소유하는 자에 대하여는 자동차세를 부과하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 재산세와 자동차 소유"},{"y":2020,"e":"지방직 9급","qn":13,"i":"L92020-13","t":"지방세법 상 재산세의 비과세대상이 아닌 것은?","c":"A","mc":{"s":"지방세법 상 재산세의 비과세대상이 아닌 것은?","d":"","o":["소유권의 유상이전 약정이 없는 재산을 국가가 1년 이상 공용으로 무료 사용하는 경우","일반인의 통행을 위하여 제공할 목적으로 개설한 사설의 유료도로","대한민국 정부기관의 재산에 대하여 비과세하는 외국정부의 재산","소유권의 유상이전 약정이 없는 재산을 지방자치단체조합이 1년 이상 공공용으로 무료 사용하는 경우"],"a":2}},{"y":2021,"e":"지방직 9급","qn":13,"i":"L92021-13-1","t":"토지와 건축물에 대한 재산세의 납기는 매년 7월 16일부터 7월 31일까지이다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 재산세"},{"y":2021,"e":"지방직 9급","qn":13,"i":"L92021-13-2","t":"납부통지서를 수탁자에게 고지한 후 재산세 납세의무자인 위탁자가 신탁의 이익을 받을 권리를 포기하는 경우에는 고지된 재산세에 대한 신탁재산 수탁자의 물적납세의무는 소멸한다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 재산세"},{"y":2021,"e":"지방직 9급","qn":13,"i":"L92021-13-3","t":"재산세 과세기준일 현재 상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상 소유자를 신고하지 아니하였을 때에는 행정안전부령으로 정하는 주된 상속자가 재산세를 납부할 의무가 있다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 재산세"},{"y":2021,"e":"지방직 9급","qn":13,"i":"L92021-13-4","t":"지방자치단체의 장은 재산세의 납부할 세액이 950만원인 경우 500만원은 납부기한이 지난 날부터 2개월 이내 분납하게 할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 재산세"},{"y":2022,"e":"지방직 9급","qn":4,"i":"L92022-04","t":"지방세법령상 재산세의 과세표준 등에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법령상 재산세의 과세표준 등에 대한 설명으로 옳은 것은?","d":"(단, 비과세 및 지방세 특례는 고려하지 않는다)","o":["토지의 공정시장가액비율은 시가표준액의 100분의 95이다.","주택을 제외한 건축물의 공정시장가액비율은 시가표준액의 100분의 80이다.","주택의 공정시장가액비율은 시가표준액의 100분의 75이다.","선박 및 항공기에 대한 재산세의 과세표준은 지방세법 제4조 (부동산 등의 시가표준액) 제2항에 따른 시가표준액으로 한다."],"a":4}},{"y":2023,"e":"지방직 9급","qn":6,"i":"L92023-06","t":"지방세법령상 재산세 과세기준일 현재 납세의무자에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법령상 재산세 과세기준일 현재 납세의무자에 대한 설명으로 옳은 것은?","d":"(단, 비과세, 지방세 특례, 부칙 제11조(신탁재산에 대한 재산세 납세의무자 등에 관한 적용례) 및 제16조(신탁재산에 대한 재산세 납세의무자 변경에 관한 경과조치)는 고려하지 않는다)","o":["상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 경우에는 납세의무자는 민법 상 상속지분이 가장 높은 사람으로 하되, 상속지분이 가장 높은 사람이 두 명 이상이면 그 중 나이가 가장 적은 사람으로 한다.","신탁법 제2조에 따른 수탁자의 명의로 등기 또는 등록된 신탁 재산의 경우에는 수탁자가 재산세를 납부할 의무가 있다.","지방자치단체와 재산세 과세대상 재산을 연부(年賦)로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우에는 그 매도 계약자가 재산세를 납부할 의무가 있다.","채무자 회생 및 파산에 관한 법률 에 따른 파산선고 이후 파산 종결의 결정까지 파산재단에 속하는 재산의 경우에는 공부상 소유자가 재산세를 납부할 의무가 있다."],"a":4}},{"y":2024,"e":"지방직 9급","qn":19,"i":"L92024-19-1","t":"재산세는 토지, 건축물, 주택, 항공기 및 선박을 과세대상으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세"},{"y":2024,"e":"지방직 9급","qn":19,"i":"L92024-19-2","t":"재산세 과세기준일 현재 지방자치단체와 재산세 과세대상 재산을 연부로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우에는 그 매수계약자가 재산세를 납부할 의무가 있다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 재산세"},{"y":2024,"e":"지방직 9급","qn":19,"i":"L92024-19-3","t":"재산세 과세기준일 현재 공부상의 소유자가 매매 등의 사유로 소유권이 변동되었는데도 신고하지 아니하여 사실상의 소유자를 알 수 없을 때에는 공부상의 소유자가 재산세를 납부할 의무가 있다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 재산세"},{"y":2024,"e":"지방직 9급","qn":19,"i":"L92024-19-4","t":"국가, 지방자치단체가 유료로 1년 이상 공용 또는 공공용으로 사용하는 재산에 대하여는 재산세를 부과하지 아니한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 재산세"},{"y":2025,"e":"지방직 9급","qn":3,"i":"L92025-03-1","t":"재산세를 징수하려면 토지, 건축물, 주택, 선박 및 항공기로 구분한 납세고지서에 과세표준과 세액을 적어 늦어도 납기개시 5일 전까지 발급하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 재산세"},{"y":2025,"e":"지방직 9급","qn":3,"i":"L92025-03-2","t":"1세대 1주택에 대한 주택 세율 특례에 따라 1세대 1주택 해당여부를 판단할 때 신탁법에 따라 신탁된 주택은 수탁자의 주택 수에 가산한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 재산세"},{"y":2025,"e":"지방직 9급","qn":3,"i":"L92025-03-3","t":"재산세의 과세기준일은 매년 6월 1일로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 재산세"},{"y":2025,"e":"지방직 9급","qn":3,"i":"L92025-03-4","t":"토지에 대한 재산세 과세대상은 종합합산과세대상, 별도합산과세대상 및 분리과세대상으로 구분한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 재산세"},{"y":2025,"e":"지방직 9급","qn":17,"i":"L92025-17","t":"지방세법령상 재산세에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세법령상 재산세에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 주택의 건물과 부속토지의 소유자가 다를 경우 건물의 소유자를 부속토지에 대한 재산세의 납세의무자로 본다.\nㄴ. 재산세 과세기준일 현재의 사용이 일시적으로 공부상 등재현황과 달리 사용하는 것으로 인정되는 경우에는 공부상 등재현황에 따라 재산세를 부과한다.\nㄷ. 신탁재산 수탁자의 물적납세의무에 따라 수탁자로부터 납세의무자의 재산세를 징수하려는 지방자치단체의 장이 납부통지서를 수탁자에게 고지한 후 재산세 납세의무자인 위탁자가 신탁의 이익을 받을 권리를 포기하는 경우에는 고지된 부분에 대한 납세의무는 소멸한다.","o":["ㄴ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ"],"a":1}}],"9":[{"y":2015,"e":"지방직 9급","qn":10,"i":"L92015-10","t":"지방세법 상 지방교육세의 납세의무자에 해당하지 않는 자는?","c":"A","mc":{"s":"지방세법 상 지방교육세의 납세의무자에 해당하지 않는 자는?","d":"","o":["항공기 및 선박의 취득에 대한 취득세의 납세의무자","레저세의 납세의무자","담배소비세의 납세의무자","주민세 재산분의 납세의무자"],"a":4}},{"y":2015,"e":"지방직 9급","qn":15,"i":"L92015-15-1","t":"화물을 싣지 아니한 입출항 컨테이너는 지역자원시설세의 과세대상이 아니다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2015,"e":"지방직 9급","qn":15,"i":"L92015-15-2","t":"지하수에 대한 지역자원시설세의 납세의무자는 해당 채수공 (採水孔) 토지의 소유자와 채수자가 다른 경우 토지의 소유자로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2015,"e":"지방직 9급","qn":15,"i":"L92015-15-3","t":"지방자치단체의 장은 화력발전과 원자력발전에 대한 지역자원 시설세의 세율을 가감할 수 없다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2015,"e":"지방직 9급","qn":15,"i":"L92015-15-4","t":"지역자원시설세로 징수할 세액이 고지서 1장당 2천원 미만인 경우에는 그 지역자원시설세를 징수하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2016,"e":"지방직 9급","qn":10,"i":"L92016-10","t":"지방세법 상 지역자원시설세에 대한 설명으로 옳지 않는 것은?","c":"A","mc":{"s":"지방세법 상 지역자원시설세에 대한 설명으로 옳지 않는 것은?","d":"","o":["원자력발전 및 화력발전에 대한 지역자원시설세는 신고납부의 방법으로 징수한다.","지하수에 대한 지역자원시설세의 경우 조례로 정하는 바에 따라 보통징수의 방법으로 징수할 수 있다.","지하자원에 대한 지역자원시설세의 납세의무자는 광업권이 등록된 토지의 소유자이다.","컨테이너에 대한 지역자원시설세의 납세의무자는 컨테이너를 취급하는 부두를 이용하여 컨테이너를 입항․출항시키는 자이다."],"a":3}},{"y":2016,"e":"지방직 9급","qn":14,"i":"L92016-14-1","t":"레저세의 납세의무자는 지방교육세의 납세의무자에 해당 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방교육세"},{"y":2016,"e":"지방직 9급","qn":14,"i":"L92016-14-2","t":"담배소비세 납세의무자(제조자 또는 수입판매업자에 한정한다)의 주사무소 소재지를 관할하는 지방자치단체의 장이 지방세법 제64조제1항에 따라 담보 제공을 요구하는 경우에 담배소비세분 지방교육세에 대한 담보 제공도 함께 요구할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방교육세"},{"y":2016,"e":"지방직 9급","qn":14,"i":"L92016-14-3","t":"지방교육세를 신고하고 납부하여야 하는 자가 신고의무를 다하지 아니한 경우에는 무신고가산세 또는 과소신고가산세를 부과한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방교육세"},{"y":2016,"e":"지방직 9급","qn":14,"i":"L92016-14-4","t":"지방교육세의 지방세환급금은 해당 지방자치단체의 장이 지방교육세의 과세표준이 되는 세목별 세액의 환급의 예에 따라 환급한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방교육세"},{"y":2017,"e":"지방직 9급","qn":7,"i":"L92017-07","t":"지방세법 상 지역자원시설세의 납세의무자에 해당하는 것으로만 묶은 것은?","c":"A","mc":{"s":"지방세법 상 지역자원시설세의 납세의무자에 해당하는 것으로만 묶은 것은?","d":"(단, 특정자원에 대한 지역자원시설세의 비과세 규정은 적용되지 않는 것으로 가정한다)\nㄱ. 석탄을 채광(採鑛)하는 자\nㄴ. 지하수를 개발하여 먹는 물로 제조․판매하기 위하여 채수(採水)하는 자\nㄷ. 컨테이너를 취급하는 부두를 이용하여 컨테이너를 입항․출항시키는 자\nㄹ. 흐르는 물을 이용하여 직접 양수발전을 하는 자\nㅁ. 원자력을 이용하여 발전을 하는 자","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㅁ","ㄴ, ㄹ, ㅁ"],"a":3}},{"y":2017,"e":"지방직 9급","qn":17,"i":"L92017-17","t":"기계장비( 지방세법 제124조에 해당하는 자동차 제외)의 취득에 대한 취득세의 납세의무자 ㄹ.","c":"A","mc":{"s":"기계장비( 지방세법 제124조에 해당하는 자동차 제외)의 취득에 대한 취득세의 납세의무자 ㄹ.","d":"지방세법 상 지방교육세의 납세의무자에 해당하는 것으로만 묶은 것은?\nㄱ. 주민세 균등분의 납세의무자\nㄴ. 지방세법 제127조제1항제1호 및 제3호에 따른 영업용 승용자동차에 대한 자동차세의 납세의무자\nㄷ.  등록에 대한 등록면허세( 지방세법 제124조에 해당하는 자동차에 대한 등록면허세 제외)의 납세의무자","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2018,"e":"지방직 9급","qn":5,"i":"L92018-05-1","t":"지방자치단체의 장은 지방교육투자재원의 조달을 위하여 필요한 경우에는 해당 지방자치단체의 조례로 정하는 바에 따라 지방교육세의 세율을 지방세법 제151조제1항[같은 항제3호(지방세법 및 지방세감면법령에 따라 납부하여야 할 레저세액의 100분의 40)는 제외]의 표준세율의 100분의 50의 범위에서 가감할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세법령상 지방교육세"},{"y":2018,"e":"지방직 9급","qn":5,"i":"L92018-05-2","t":"지방자치단체의 장이 지방세법에 따라 납세의무자에게 주민세 균등분·재산세 및 자동차세를 부과·징수하거나 지방세법 제60조제6항에 따라 세관장이 담배소비세를 부과·징수하는 때에는 그에 대한 지방교육세를 함께 부과·징수한다.","ox":"O","m":"②","c":"A","tp":"지방세법령상 지방교육세"},{"y":2018,"e":"지방직 9급","qn":5,"i":"L92018-05-3","t":"자동차관리법에 따라 등록되거나 신고된 차량의 등록에 대한 등록면허세의 납세의무자는 지방교육세의 납세의무자에 해당한다.","ox":"X","m":"③","c":"A","tp":"지방세법령상 지방교육세"},{"y":2018,"e":"지방직 9급","qn":5,"i":"L92018-05-4","t":"지방교육세를 납부하여야 할 자가 지방교육세의 과세표준이 되는 지방세를 납부하지 아니하거나 부족하게 납부함으로써 해당 세액에 가산세가 가산되었을 때에는 그 가산세액은 지방교육세의 과세표준에 산입하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법령상 지방교육세"},{"y":2018,"e":"지방직 9급","qn":18,"i":"L92018-18-1","t":"소방시설, 그 밖의 공공시설로 인하여 이익을 받는 자의 건축물은 지역자원시설세의 과세대상이 아니다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 지역자원시설세"},{"y":2018,"e":"지방직 9급","qn":18,"i":"L92018-18-2","t":"국가, 지방자치단체 및 지방자치단체조합이 직접 개발하여 이용하는 원자력발전·화력발전에 대해서 지역자원시설세를 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 지역자원시설세"},{"y":2018,"e":"지방직 9급","qn":18,"i":"L92018-18-3","t":"컨테이너를 취급하는 부두를 이용하여 화물을 싣지 아니한 컨테이너를 입·출항시키는 자는 지역자원시설세의 납세의무자가 아니다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 지역자원시설세"},{"y":2018,"e":"지방직 9급","qn":18,"i":"L92018-18-4","t":"농어촌정비법 제2조제3호에 따른 농어촌용수 중 행정안전부령으로 정하는 생활용수 및 공업용수로 이용하기 위하여 퍼 올린 지하수는 지역자원시설세의 과세대상이 아니다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 지역자원시설세"},{"y":2019,"e":"지방직 9급","qn":4,"i":"L92019-04","t":"지방세법 상 지방교육세의 납세의무자에 해당하지 않는 자는?","c":"A","mc":{"s":"지방세법 상 지방교육세의 납세의무자에 해당하지 않는 자는?","d":"","o":["담배소비세의 납세의무자","주민세 재산분의 납세의무자","선박의 취득에 대한 취득세의 납세의무자","레저세의 납세의무자"],"a":2}},{"y":2019,"e":"지방직 9급","qn":16,"i":"L92019-16-1","t":"소방시설로 인하여 이익을 받는 자의 건축물은 지역자원시설세의 과세대상이다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2019,"e":"지방직 9급","qn":16,"i":"L92019-16-2","t":"지방세법에 따라 재산세가 비과세되는 건축물과 선박에 대하여는 지역자원시설세를 부과하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2019,"e":"지방직 9급","qn":16,"i":"L92019-16-3","t":"특정부동산에 대한 지역자원시설세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과·징수한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2019,"e":"지방직 9급","qn":16,"i":"L92019-16-4","t":"지방자치단체의 장은 조례로 정하는 바에 따라 화력발전에 대한 지역자원시설세의 세율을 법정 표준세율의 100분의 50의 범위에서 가감할 수 있다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2020,"e":"지방직 9급","qn":15,"i":"L92020-15","t":"지방세법 상 지방교육세의 납세의무자만을 모두 고르면?","c":"A","mc":{"s":"지방세법 상 지방교육세의 납세의무자만을 모두 고르면?","d":"ㄱ. 레저세 납세의무자\nㄴ. 담배소비세 납세의무자\nㄷ. 주민세 재산분 납세의무자\nㄹ. 선박의 취득에 대한 취득세 납세의무자\nㅁ. 항공기 소유에 대한 재산세 납세의무자\nㅂ. 지방소비세 납세의무자","o":["ㄱ, ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄹ, ㅁ","ㄴ, ㄷ, ㄹ, ㅁ","ㄴ, ㄷ, ㄹ, ㅂ"],"a":2}},{"y":2021,"e":"지방직 9급","qn":14,"i":"L92021-14-1","t":"지방세법 제124조에 해당하는 자동차의 등록에 대한 등록 면허세의 납세의무자는 지방교육세의 납세의무가 있다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 지방교육세"},{"y":2021,"e":"지방직 9급","qn":14,"i":"L92021-14-2","t":"지방교육세를 납부하여야 할 자가 지방교육세의 과세표준이 되는 지방세를 납부하지 아니하거나 부족하게 납부함으로써 해당 세액에 가산세가 가산되었을 때에는 그 가산세액은 지방교육세의 과세표준에 산입한다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 지방교육세"},{"y":2021,"e":"지방직 9급","qn":14,"i":"L92021-14-3","t":"지방교육세를 신고하고 납부하여야 하는 자가 신고의무를 다하지 않은 경우에도 지방세기본법에 따른 무신고가산세와 과소신고가산세·초과환급신고가산세를 부과하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 지방교육세"},{"y":2021,"e":"지방직 9급","qn":14,"i":"L92021-14-4","t":"지방교육세는 지방세법 및 지방세감면법령에 따라 납부 하여야 할 담배소비세액의 100분의 40을 그 세액으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 지방교육세"},{"y":2021,"e":"지방직 9급","qn":16,"i":"L92021-16-1","t":"지하자원에 대한 특정자원분 지역자원시설세의 납세지는 광업권이 등록된 토지의 소재지이며, 광업권이 등록된 토지가 둘 이상의 지방자치단체에 걸쳐 있는 경우에는 광업권이 등록된 토지의 면적에 따라 안분한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2021,"e":"지방직 9급","qn":16,"i":"L92021-16-2","t":"흐르는 물을 이용하여 직접 수력발전(양수발전을 포함한다)을 하는 자는 특정자원분 지역자원시설세의 납세의무자에 해당한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2021,"e":"지방직 9급","qn":16,"i":"L92021-16-3","t":"지하수에 대한 지역자원시설세와 소방분 지역자원시설세는 신고납부의 방법으로 징수한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2021,"e":"지방직 9급","qn":16,"i":"L92021-16-4","t":"행정기관으로부터 철거명령을 받은 건축물에 대해 지방세법 제109조에 따라 재산세가 비과세되더라도 소방분 지역자원 시설세를 부과한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2022,"e":"지방직 9급","qn":7,"i":"L92022-07","t":"지방세법령상 지역자원시설세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법령상 지역자원시설세에 대한 설명으로 옳은 것은?","d":"(단, 비과세 및 지방세 특례는 고려하지 않는다)","o":["먹는 물로 판매하기 위하여 퍼 올린 지하수에 대한 특정자원분 지역자원시설세의 납세지는 해당 지하수를 판매하는 사업장의 소재지이다.","원자력발전은 특정시설분 지역자원시설세의 과세대상이다.","소방시설로 인하여 이익을 받는 자의 주택의 건축물 부분은 소방분 지역자원시설세의 과세대상에 포함하지 아니한다.","지역자원시설세로 징수할 세액이 고지서 1장당 2천원 미만인 경우에도 그 지역자원시설세를 징수한다."],"a":2}},{"y":2022,"e":"지방직 9급","qn":18,"i":"L92022-18-1","t":"지방자치단체의 장은 지방교육투자재원의 조달을 위하여 필요한 경우에는 해당 지방자치단체의 조례로 정하는 바에 따라 지방교육세의 세율을 표준세율(지방세법 및 지방세감면 법령에 따라 납부하여야 할 레저세의 경우 포함)의 100분의 50의 범위에서 가감할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 지방교육세"},{"y":2022,"e":"지방직 9급","qn":18,"i":"L92022-18-2","t":"지방교육세의 지방세환급금은 해당 지방자치단체의 장 또는 그 위임을 받은 공무원이 지방자치단체의 조례에 따라 환급한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지방교육세"},{"y":2022,"e":"지방직 9급","qn":18,"i":"L92022-18-3","t":"지방교육세를 신고하고 납부하여야 하는 자가 납부의무를 다하지 아니한 경우에도 지방세기본법에 따른 납부지연가산세를 징수하지 아니한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 지방교육세"},{"y":2022,"e":"지방직 9급","qn":18,"i":"L92022-18-4","t":"지방자치단체의 장이 지방세법에 따라 납세의무자에게 주민세 개인분을 부과·징수하는 때에는 그에 대한 지방교육세를 함께 부과·징수한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방교육세"},{"y":2023,"e":"지방직 9급","qn":5,"i":"L92023-05","t":"지방세법 상 지역자원시설세에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법 상 지역자원시설세에 대한 설명으로 옳지 않은 것은?","d":"(단, 비과세 및 지방세 특례는 고려하지 않는다)","o":["지하수에 대한 특정자원분 지역자원시설세의 납세지는 채수공 (採水孔)의 소재지이고, 컨테이너에 대한 특정시설분 지역자원 시설세의 납세지는 컨테이너를 취급하는 부두의 소재지이다.","지방자치단체의 장은 조례로 정하는 바에 따라 발전용수에 대한 특정자원분 지역자원시설세의 세율을 지방세법 제146조제1항 제1호에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다.","특정시설분 지역자원시설세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 징수한다.","소방분 지역자원시설세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다."],"a":3}},{"y":2023,"e":"지방직 9급","qn":11,"i":"L92023-11","t":"지방세법령상 지방교육세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법령상 지방교육세에 대한 설명으로 옳은 것은?","d":"(단, 비과세 및 지방세 특례는 고려하지 않는다)","o":["건설기계관리법 에 따라 등록된 덤프트럭과 콘크리트믹서트럭의 취득에 대한 취득세의 납세의무자는 지방교육세의 납세의무가 있다.","지방자치단체의 장은 지방교육투자재원의 조달을 위하여 필요한 경우에는 해당 지방자치단체의 조례로 정하는 바에 따라 지방세법 및 지방세감면법령에 따라 납부하여야 할 레저세액의 지방교육 세율을 그 표준세율의 100분의 50의 범위에서 가감할 수 있다.","주민세 개인분에 대한 지방교육세는 주민세 개인분 세액의 100분의 10으로 하되, 인구 50만 이상 시의 경우에는 100분의 20으로 한다.","지방교육세 납세의무자가 담배소비세와 함께 지방교육세를 신고하고 납부하는 경우, 담배소비세 납세의무자인 제조자의 주사무소 소재지를 관할하는 지방자치단체의 장이 지방세법 제64조 (납세담보)제1항에 따라 담보 제공을 요구하는 경우에는 담배 소비세분 지방교육세에 대한 담보 제공도 함께 요구할 수 있다."],"a":4}},{"y":2024,"e":"지방직 9급","qn":5,"i":"L92024-05-1","t":"지방자치단체가 직접 개발하여 이용하는 경우에는 특정자원분 지역자원시설세 및 특정시설분 지역자원시설세를 부과하지 아니한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2024,"e":"지방직 9급","qn":5,"i":"L92024-05-2","t":"행정기관으로부터 철거명령을 받은 건축물에 대해 지방세법에 따라 재산세가 비과세되더라도 해당 건축물에 대한 소방분 지역 자원시설세는 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2024,"e":"지방직 9급","qn":5,"i":"L92024-05-3","t":"소방분 지역자원시설세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2024,"e":"지방직 9급","qn":5,"i":"L92024-05-4","t":"소방분 지역자원시설세의 과세기준일은 매년 6월 1일로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지역자원시설세"},{"y":2024,"e":"지방직 9급","qn":15,"i":"L92024-15-1","t":"부동산 취득에 대한 취득세의 납세의무자, 레저세의 납세의무자, 담배소비세의 납세의무자는 지방교육세 납세의무자에 해당한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방교육세"},{"y":2024,"e":"지방직 9급","qn":15,"i":"L92024-15-2","t":"지방교육세를 신고하고 납부하여야 하는 자가 신고의무를 다하지 아니한 경우에도 지방세기본법에 따른 무신고가산세 또는 과소신고가산세ㆍ초과환급신고가산세를 부과하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방교육세"},{"y":2024,"e":"지방직 9급","qn":15,"i":"L92024-15-3","t":"지방교육세의 지방세환급금은 해당 지방자치단체의 장 또는 그 위임을 받은 공무원이 지방교육세의 과세표준이 되는 세목별 세액의 환급의 예에 따라 환급한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방교육세"},{"y":2024,"e":"지방직 9급","qn":15,"i":"L92024-15-4","t":"지방교육세로 징수할 세액이 고지서 1장당 2천원 미만인 경우에는 그 지방교육세를 징수하지 아니한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 지방교육세"},{"y":2025,"e":"지방직 9급","qn":9,"i":"L92025-09","t":"지방세법 상 지방교육세의 납세의무자가 아닌 자는?","c":"A","mc":{"s":"지방세법 상 지방교육세의 납세의무자가 아닌 자는?","d":"","o":["레저세의 납세의무자","담배소비세의 납세의무자","주민세 종업원분의 납세의무자","항공기 및 선박의 취득에 대한 취득세의 납세의무자"],"a":3}}],"8":[{"y":2015,"e":"지방직 9급","qn":13,"i":"L92015-13-1","t":"담배소비세의 세율은 표준세율체계를 따르며, 지방자치단체의 장은 당해 세율을 동 표준세율의 100분의 30의 범위에서 가감 하여 정할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2015,"e":"지방직 9급","qn":13,"i":"L92015-13-2","t":"담배소비세는 종량세이며 세율은 정액세율의 체계를 따른다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2015,"e":"지방직 9급","qn":13,"i":"L92015-13-3","t":"제조자 또는 수입판매업자가 담배를 수출하는 경우 담배소비세가 면제된다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2015,"e":"지방직 9급","qn":13,"i":"L92015-13-4","t":"수입담배의 경우 담배소비세를 징수하기 위한 특별징수의무자는 수입판매업자의 주사무소 소재지를 관할하는 지방자치단체의 장이다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 담배소비세"},{"y":2016,"e":"지방직 9급","qn":5,"i":"L92016-05-1","t":"수입판매업자가 보세구역에서의 판매를 위하여 담배를 제공 하는 경우에는 담배소비세를 면제한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2016,"e":"지방직 9급","qn":5,"i":"L92016-05-2","t":"제조장에 있는 담배가 파산절차에 따라 환가되는 경우에는 제조자가 담배를 제조장에서 반출한 것으로 본다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2016,"e":"지방직 9급","qn":5,"i":"L92016-05-3","t":"제조장에서 반출된 담배가 품질의 불량으로 제조장으로 반입된 경우에는 세액을 공제하거나 환급한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2016,"e":"지방직 9급","qn":5,"i":"L92016-05-4","t":"제조자는 제조장으로부터 반출한 담배에 대하여 담배소비세 납세의무를 지며, 이 경우 담배소비세의 납세지는 담배가 반출된 제조장의 소재지로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 담배소비세"},{"y":2017,"e":"지방직 9급","qn":2,"i":"L92017-02","t":"지방세법 상 제조자 또는 수입판매업자가 제공하는 담배로서 담배소비세가 면제되는 경우가 아닌 것은?","c":"A","mc":{"s":"지방세법 상 제조자 또는 수입판매업자가 제공하는 담배로서 담배소비세가 면제되는 경우가 아닌 것은?","d":"","o":["수출 상담을 위한 견본용으로 제공하는 경우","국제항로에 취항하는 항공기 또는 여객선의 승객에게 판매하는 경우","담배를 다른 담배의 원료로 사용하기 위하여 반출하는 경우","주한외국군의 관할 구역에서 외국 국적을 가진 민간인으로서 주한외국군대에서 근무하는 사람의 가족에게 판매하는 경우"],"a":3}},{"y":2017,"e":"지방직 9급","qn":5,"i":"L92017-05-1","t":"레저세의 과세표준은 승자투표권, 승마투표권 등의 발매금총액으로 하며, 세율은 100분의 10으로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 레저세"},{"y":2017,"e":"지방직 9급","qn":5,"i":"L92017-05-2","t":"납세의무자는 승자투표권, 승마투표권 등의 발매일이 속하는 달의 다음 달 10일까지 산출세액을 대통령령으로 정하는 바에 따라 경륜장등의 소재지 및 장외발매소의 소재지별로 안분계산 하여 해당 지방자치단체의 장에게 각각 신고하고 납부하여야 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 레저세"},{"y":2017,"e":"지방직 9급","qn":5,"i":"L92017-05-3","t":"레저세의 과세대상은 한국마사회법에 따른 경마, 경륜ㆍ 경정법에 따른 경륜 및 경정, 관광진흥법에 따른 카지노, 전통 소싸움경기에 관한 법률에 따른 소싸움이다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 레저세"},{"y":2017,"e":"지방직 9급","qn":5,"i":"L92017-05-4","t":"납세의무자는 조례로 정하는 바에 따라 경륜등의 시행에 관한 사항을 장부에 기재하고 필요한 사항을 지방자치단체의 장에게 신고하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 레저세"},{"y":2018,"e":"지방직 9급","qn":2,"i":"L92018-02-1","t":"장외발매소에서 발매한 승자투표권, 승마투표권 등에 대한 세액은 그 경륜장 등 소재지를 관할하는 시장·군수·구청장에게 100분의 70을 신고납부하고 그 장외발매소 소재지를 관할하는 시장·군수·구청장에게 100분의 30을 신고납부한다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 레저세"},{"y":2018,"e":"지방직 9급","qn":2,"i":"L92018-02-2","t":"레저세의 과세표준은 승자투표권, 승마투표권 등의 발매금 총액으로 하며, 세율은 100분의 10으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법령상 레저세"},{"y":2018,"e":"지방직 9급","qn":2,"i":"L92018-02-3","t":"시장·군수·구청장은 납세의무자가 레저세를 납부하면 납세 의무자에게 그 징수납부에 든 경비를 교부금으로 지급할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 레저세"},{"y":2018,"e":"지방직 9급","qn":2,"i":"L92018-02-4","t":"레저세의 납세의무자는 조례로 정하는 바에 따라 경륜 등의 시행에 관한 사항을 장부에 기재하고 필요한 사항을 지방 자치단체의 장에게 신고하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세법령상 레저세"},{"y":2018,"e":"지방직 9급","qn":14,"i":"L92018-14-1","t":"입국자 또는 수입판매업자가 아닌 사람이 외국으로부터 우편으로 반입하는 담배에 대해서는 그 수취인이 담배소비세를 납부할 의무가 있다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2018,"e":"지방직 9급","qn":14,"i":"L92018-14-2","t":"제조자 또는 수입판매업자가 남북교류협력에 관한 법률에 따라 반출 승인을 받은 담배로서 북한지역에서 취업 중인 근로자 및 북한지역 관광객에게 판매하는 담배에 대해서는 담배소비세를 면제한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2018,"e":"지방직 9급","qn":14,"i":"L92018-14-3","t":"납세담보의 제공을 요구받은 수입판매업자는 보세구역으로부터 담배를 반출하기 전에 미리 담배소비세를 신고납부하여 담보를 제공하지 아니할 수 있다. 이 경우 담배소비세의 납세의무는 담배를 보세구역으로부터 반출하는 때에 성립한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2018,"e":"지방직 9급","qn":14,"i":"L92018-14-4","t":"피우는 담배로서 제1종 궐련의 담배소비세 세율은 20개비당 1,007원이며 해당 세율은 그 세율의 100분의 30의 범위에서 대통령령으로 가감할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 담배소비세"},{"y":2019,"e":"지방직 9급","qn":3,"i":"L92019-03-1","t":"냄새 맡는 담배는 담배소비세의 과세대상인 담배이다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2019,"e":"지방직 9급","qn":3,"i":"L92019-03-2","t":"수입판매업자는 보세구역으로부터 반출한 담배에 대하여 담배소비세를 납부할 의무가 있다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2019,"e":"지방직 9급","qn":3,"i":"L92019-03-3","t":"담배소비세의 과세표준은 담배의 개비수, 중량 또는 니코틴 용액의 용량으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2019,"e":"지방직 9급","qn":3,"i":"L92019-03-4","t":"담배가 보세구역에서 소비되는 경우에는 수입판매업자가 담배를 보세구역에서 반출한 것으로 보지 않는다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 담배소비세"},{"y":2020,"e":"지방직 9급","qn":14,"i":"L92020-14-1","t":"제조자는 제조장으로부터 반출한 담배에 대하여 담배소비세를 납부할 의무가 있고 이 경우 납세지는 담배가 매도된 소매인의 영업장 소재지로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2020,"e":"지방직 9급","qn":14,"i":"L92020-14-2","t":"수입판매업자는 보세구역으로부터 반출한 담배에 대하여 담배소비세를 납부할 의무가 있고 이 경우 납세지는 세관 소재지로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2020,"e":"지방직 9급","qn":14,"i":"L92020-14-3","t":"제조자는 매월 1일부터 말일까지 제조장에서 반출한 담배에 대한 법정 과세표준과 세율에 따라 산출한 세액을 대통령령으로 정하는 안분기준에 따라 다음 달 20일까지 각 지방자치단체의 장에게 신고·납부하여야 한다. (단, 반출은 2020년 1월 1일 이후에 있었음)","ox":"O","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2020,"e":"지방직 9급","qn":14,"i":"L92020-14-4","t":"제조자 또는 수입판매업자의 주사무소 소재지를 관할하는 지방자치단체의 장은 담배소비세의 납세보전을 위하여 대통령령으로 정하는 바에 따라 제조자 또는 수입판매업자에게 담보의 제공을 요구할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 담배소비세"},{"y":2021,"e":"지방직 9급","qn":17,"i":"L92021-17","t":"그 사항으로 옳은 것은?","c":"A","mc":{"s":"그 사항으로 옳은 것은?","d":"지방세법령상 담배 수입판매업자가 직전 연도의 월평균 담배소비세 납부액이 5억원 이하인 경우 장부에 적지 아니할 수 있는 사항이 있다.  (단, 수입판매업자는 지방세법령상의 요건을 충족함)","o":["보세구역으로부터 반출되는 담배의 품종별 수량","도매업자와 소매인에게 판매한 담배의 해당 시․군별, 품종별 수량","보세구역 내에서 소비된 담배의 품종별 수량","훼손․멸실된 담배의 품종별 수량"],"a":2}},{"y":2021,"e":"지방직 9급","qn":19,"i":"L92021-19","t":"지방세법 상 레저세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법 상 레저세에 대한 설명으로 옳은 것은?","d":"(단, 지방세 특례는 고려하지 않음)","o":["납세의무자가 지방세법 제44조에 따른 장부 비치의 의무를 이행하지 아니한 경우에는 산출세액의 100분의 10에 해당하는 금액을 징수하여야 할 세액에 가산하여 보통징수의 방법으로 징수한다.","장외발매소에서 발매한 승자투표권․승마투표권 등에 대한 세액은 그 경륜장등(경륜장등이 신설된 경우는 제외) 소재지를 관할하는 시장․군수․구청장에게 100분의 80을 신고납부하고, 그 장외발매소 소재지를 관할하는 시장․군수․구청장에게 100분의 20을 신고납부한다.","과세표준은 승자투표권, 승마투표권 등의 당첨금총액으로 하며, 세율은 100분의 10으로 한다.","지방자치단체의 장은 조례로 정하는 바에 따라 레저세의 세율을 표준세율의 100분의 50의 범위에서 가감할 수 있다."],"a":1}},{"y":2022,"e":"지방직 9급","qn":13,"i":"L92022-13-1","t":"입국자 또는 수입판매업자가 아닌 사람이 외국으로부터 우편으로 반입하는 담배에 대해서는 그 수취인이 담배소비세를 납부할 의무가 있다.","ox":"O","m":"①","c":"A","tp":"지방세법령상 담배소비세"},{"y":2022,"e":"지방직 9급","qn":13,"i":"L92022-13-2","t":"여행자의 휴대품·별송품·탁송품으로 반입되는 담배로서 엽궐련은 200개비를 한도로 담배소비세를 면제한다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 담배소비세"},{"y":2022,"e":"지방직 9급","qn":13,"i":"L92022-13-3","t":"담배가 그 제조장 또는 보세구역에서 소비되는 경우에는 제조자 또는 수입판매업자가 담배를 제조장 또는 보세구역에서 반출한 것으로 본다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 담배소비세"},{"y":2022,"e":"지방직 9급","qn":13,"i":"L92022-13-4","t":"납세담보의 제공을 요구받은 수입판매업자가 보세구역으로부터 담배를 반출하기 전에 미리 담배소비세를 신고납부하여 담보를 제공하지 아니한 경우, 담배소비세를 신고하는 때 납세의무가 성립한다.","ox":"O","m":"④","c":"A","tp":"지방세법령상 담배소비세"},{"y":2022,"e":"지방직 9급","qn":17,"i":"L92022-17-1","t":"경륜·경정법에 따른 경륜 및 경정에 해당하는 사업을 하는 자는 레저세를 납부할 의무가 있다.","ox":"O","m":"①","c":"A","tp":"지방세법령상 레저세"},{"y":2022,"e":"지방직 9급","qn":17,"i":"L92022-17-2","t":"징수사무 보조의 명에 따라 납세의무자가 레저세를 납부하면 시장·군수·구청장은 납세의무자에게 그 징수납부에 든 경비를 교부금으로 지급할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세법령상 레저세"},{"y":2022,"e":"지방직 9급","qn":17,"i":"L92022-17-3","t":"지방자치단체의 장은 조례로 정하는 바에 따라 레저세의 세율을 표준세율의 100분의 50의 범위에서 가감할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세법령상 레저세"},{"y":2022,"e":"지방직 9급","qn":17,"i":"L92022-17-4","t":"레저세의 과세표준은 승자투표권, 승마투표권 등의 발매금 총액으로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법령상 레저세"},{"y":2023,"e":"지방직 9급","qn":12,"i":"L92023-12-1","t":"제조자는 담배를 제조장에서 지방세법 제53조에 따른 미납세 반출을 하였을 때에는 지방자치단체의 장에게 반출신고를 하여야 할 의무가 없다.","ox":"X","m":"①","c":"A","tp":"지방세법령상의 담배소비세"},{"y":2023,"e":"지방직 9급","qn":12,"i":"L92023-12-2","t":"피우는 담배 중 제3종 엽궐련의 세율은 제2종 파이프담배와 제4종 각련의 세율보다 낮다.","ox":"X","m":"②","c":"A","tp":"지방세법령상의 담배소비세"},{"y":2023,"e":"지방직 9급","qn":12,"i":"L92023-12-3","t":"제조자가 지방세법 제59조에 따른 기장의무를 이행하지 아니 하거나 거짓으로 기장한 경우에는 그 산출세액 또는 부족세액의 100분의 10에 해당하는 가산세를 징수하여야 할 세액에 가산하여 징수한다.","ox":"O","m":"③","c":"A","tp":"지방세법령상의 담배소비세"},{"y":2023,"e":"지방직 9급","qn":12,"i":"L92023-12-4","t":"제조장에 있는 담배가 공매, 경매 또는 파산절차 등에 따라 환가되는 경우에는 제조자가 담배를 제조장에서 반출한 것으로 보지 아니한다.","ox":"X","m":"④","c":"A","tp":"지방세법령상의 담배소비세"},{"y":2024,"e":"지방직 9급","qn":1,"i":"L92024-01-1","t":"우리나라에서 수출된 담배가 품질의 불량으로 다시 수입되어 제조장 또는 수입판매업자의 담배보관장소로 반입할 목적으로 보세구역으로부터 반출된 경우에는 담배소비세를 면제하지 아니한다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2024,"e":"지방직 9급","qn":1,"i":"L92024-01-2","t":"입국자 또는 수입판매업자가 아닌 사람이 외국으로부터 우편으로 반입하는 담배에 대해서는 그 수취인이 담배소비세를 납부할 의무가 있다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2024,"e":"지방직 9급","qn":1,"i":"L92024-01-3","t":"제조자가 담배를 담배의 제품개발ㆍ품질개선이나 이에 준하는 시험분석 또는 연구활동에 제공하는 경우에는 담배소비세를 면제한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2024,"e":"지방직 9급","qn":1,"i":"L92024-01-4","t":"담배소비세의 과세표준은 담배의 개비수, 중량 또는 니코틴 용액의 용량으로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 담배소비세"},{"y":2024,"e":"지방직 9급","qn":7,"i":"L92024-07-1","t":"경륜ㆍ경정법에 따른 경륜 및 경정과 한국마사회법에 따른 경마는 레저세의 과세대상에 해당한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 레저세"},{"y":2024,"e":"지방직 9급","qn":7,"i":"L92024-07-2","t":"레저세의 과세표준은 승자투표권, 승마투표권의 발매금총액 중 투표적중자에게 지급하는 환급금 총액으로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 레저세"},{"y":2024,"e":"지방직 9급","qn":7,"i":"L92024-07-3","t":"레저세의 세율은 100분의 10으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 레저세"},{"y":2024,"e":"지방직 9급","qn":7,"i":"L92024-07-4","t":"레저세의 납세의무자는 조례로 정하는 바에 따라 경륜등의 시행에 관한 사항을 장부에 기재하고 필요한 사항을 지방자치단체의 장에게 신고하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 레저세"},{"y":2025,"e":"지방직 9급","qn":6,"i":"L92025-06-1","t":"제조자는 제조장으로부터 반출한 담배에 대하여 담배소비세를 납부할 의무가 있다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 담배소비세"},{"y":2025,"e":"지방직 9급","qn":6,"i":"L92025-06-2","t":"담배소비세의 세율은 그 세율의 100분의 50의 범위에서 조례로 가감할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 담배소비세"},{"y":2025,"e":"지방직 9급","qn":6,"i":"L92025-06-3","t":"담배를 다른 담배의 원료로 사용하기 위하여 반출하는 것에 대하여는 담배소비세를 징수하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 담배소비세"},{"y":2025,"e":"지방직 9급","qn":6,"i":"L92025-06-4","t":"수입판매업자가 담배를 외항선의 선원에 대한 판매에 제공하는 경우에는 담배소비세를 면제한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 담배소비세"}],"6":[{"y":2015,"e":"지방직 9급","qn":14,"i":"L92015-14-1","t":"지방소득세는 부가세(附加稅)의 성격을 지니고 있다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 지방소득세"},{"y":2015,"e":"지방직 9급","qn":14,"i":"L92015-14-2","t":"소득세법, 법인세법 및 조세특례제한법에 따라 소득세 또는 법인세가 비과세되는 소득에 대하여는 지방소득세를 과세하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소득세"},{"y":2015,"e":"지방직 9급","qn":14,"i":"L92015-14-3","t":"종합소득 또는 퇴직소득에 대한 개인지방소득세의 공제세액 또는 감면세액이 산출세액을 초과하는 경우에는 그 초과금액은 없는 것으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소득세"},{"y":2015,"e":"지방직 9급","qn":14,"i":"L92015-14-4","t":"지방소득세(특별징수하는 지방소득세는 제외한다)의 세액이 2천원 미만일 때에는 이를 징수하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소득세"},{"y":2016,"e":"지방직 9급","qn":7,"i":"L92016-07-1","t":"납세지 관할 지방자치단체의 장이 내국법인에 대해 법인지방 소득세를 수시부과결정하는 경우 그 법인은 해당 사업연도 소득에 대한 법인지방소득세의 과세표준확정신고를 하지 아니한다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 지방소득세"},{"y":2016,"e":"지방직 9급","qn":7,"i":"L92016-07-2","t":"소득세법, 법인세법 및 조세특례제한법에 따라 소득세 또는 법인세가 비과세되는 소득에 대하여는 지방소득세를 과세하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소득세"},{"y":2016,"e":"지방직 9급","qn":7,"i":"L92016-07-3","t":"법인 또는 연결법인이 둘 이상의 지방자치단체에 사업장이 있는 경우에는 각각의 사업장 소재지를 법인지방소득세(특별 징수하는 지방소득세는 제외)의 납세지로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소득세"},{"y":2016,"e":"지방직 9급","qn":7,"i":"L92016-07-4","t":"과세표준확정신고를 한 거주자가 신고납부한 개인지방소득세의 납세지에 오류가 있음을 발견하여 경정 등의 청구로 환급받는 세액에 대하여는 지방세환급가산금을 지급하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소득세"},{"y":2017,"e":"지방직 9급","qn":18,"i":"L92017-18-1","t":"법인지방소득세(지방세법 제103조의29, 제103조의52에 따라 특별징수하는 경우 제외)의 납세지는 법인세법 제9조에 따른 납세지로 하되, 법인 또는 연결법인이 둘 이상의 지방자치 단체에 사업장이 있는 경우에는 각각의 사업장 소재지를 납세지로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 지방소득세"},{"y":2017,"e":"지방직 9급","qn":18,"i":"L92017-18-2","t":"지방세법 제103조의13에 따라 특별징수하는 근로소득에 대한 지방소득세는 납세의무자의 주소지를 관할하는 지방자치단체의 장이 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 지방소득세"},{"y":2017,"e":"지방직 9급","qn":18,"i":"L92017-18-3","t":"지방자치단체의 장은 조례로 정하는 바에 따라 종합소득에 대한 개인지방소득세의 세율을 지방세법 제92조제1항에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소득세"},{"y":2017,"e":"지방직 9급","qn":18,"i":"L92017-18-4","t":"납세지 관할 지방자치단체의 장은 개인지방소득세의 과세표준과 세액을 결정 또는 경정한 후 그 결정 또는 경정에 오류나 누락이 있는 것을 발견한 경우에는 즉시 이를 다시 경정한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소득세"},{"y":2019,"e":"지방직 9급","qn":10,"i":"L92019-10-1","t":"거주자의 양도소득에 대한 개인지방소득세 과세표준은 종합소득 및 퇴직소득에 대한 개인지방소득세 과세표준과 구분하여 계산한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 거주자의 양도소득"},{"y":2019,"e":"지방직 9급","qn":10,"i":"L92019-10-2","t":"양도소득에 대한 개인지방소득세의 공제세액 또는 감면세액이 산출세액을 초과하는 경우에는 그 초과금액은 없는 것으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 거주자의 양도소득"},{"y":2019,"e":"지방직 9급","qn":10,"i":"L92019-10-3","t":"거주자가 소득세법에 따라 양도소득과세표준 확정신고를 하는 경우에는 해당 신고기한까지 양도소득에 대한 개인지방 소득세 과세표준과 세액을 대통령령으로 정하는 바에 따라 납세지 관할 지방자치단체의 장에게 확정신고·납부하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 거주자의 양도소득"},{"y":2019,"e":"지방직 9급","qn":10,"i":"L92019-10-4","t":"양도차익이 없거나 양도차손이 발생한 경우에 거주자는 소득세법에 따른 양도소득과세표준 예정신고만으로 충분하고 양도소득에 대한 개인지방소득세 과세표준과 세액을 납세지 관할 지방자치단체의 장에게 신고할 필요는 없다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 거주자의 양도소득"},{"y":2020,"e":"지방직 9급","qn":3,"i":"L92020-03-1","t":"거주자의 개인지방소득은 종합소득, 퇴직소득 및 양도소득으로 분류하여 과세한다.","ox":"O","m":"①","c":"A","tp":"지방세법 및 지방세기본법 상 개인지방소득세"},{"y":2020,"e":"지방직 9급","qn":3,"i":"L92020-03-2","t":"거주자의 개인지방소득세는 과세표준이 되는 소득에 대하여 국세인 소득세의 납세의무가 성립하는 때에 성립한다.","ox":"O","m":"②","c":"A","tp":"지방세법 및 지방세기본법 상 개인지방소득세"},{"y":2020,"e":"지방직 9급","qn":3,"i":"L92020-03-3","t":"거주자가 출국하여 비거주자가 되는 경우 해당 거주자의 개인지방소득세의 과세기간은 1월 1일부터 출국한 날까지로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 및 지방세기본법 상 개인지방소득세"},{"y":2020,"e":"지방직 9급","qn":3,"i":"L92020-03-4","t":"거주자의 종합소득에 대한 개인지방소득세의 표준세율은 국세인 종합소득세의 세율이 변경되면 그에 연동하여 변경된다.","ox":"X","m":"④","c":"A","tp":"지방세법 및 지방세기본법 상 개인지방소득세"},{"y":2021,"e":"지방직 9급","qn":12,"i":"L92021-12-1","t":"거주자의 종합소득에 대한 개인지방소득세의 세율은 지방세법에서 따로 규정하고 있으며, 지방자치단체의 장이 조례로 정하는 바에 따라 가감할 수 없다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 지방소득세"},{"y":2021,"e":"지방직 9급","qn":12,"i":"L92021-12-2","t":"소득세법, 법인세법 및 조세특례제한법에 따라 소득세 또는 법인세가 비과세되는 소득에 대하여는 지방소득세를 과세하지 아니한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 지방소득세"},{"y":2021,"e":"지방직 9급","qn":12,"i":"L92021-12-3","t":"지방세법 제103조의22제1항에 따른 각 사업연도의 소득에 대한 법인지방소득세의 공제세액 또는 감면세액이 법인지방 소득세 산출세액을 초과하는 경우에는 그 초과금액은 없는 것으로 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 지방소득세"},{"y":2021,"e":"지방직 9급","qn":12,"i":"L92021-12-4","t":"지방세법 제103조의13, 제103조의29, 제103조의52에 따라 특별징수하는 지방소득세 중 국민건강보험법에 따른 국민 건강보험공단이 지급하는 사업소득에 대한 지방소득세는 그 소득을 지급받는 사람의 사업장 소재지를 관할하는 지방 자치단체의 장이 부과한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 지방소득세"},{"y":2022,"e":"지방직 9급","qn":12,"i":"L92022-12","t":"지방세법령상 법인지방소득세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법령상 법인지방소득세에 대한 설명으로 옳은 것은?","d":"(단, 조세특례 및 국외원천소득은 고려하지 않는다)","o":["내국법인의 각 사업연도의 소득에 대한 법인지방소득세의 과세표준은 법인세법 제13조(과세표준)에 따라 계산한 법인세의 과세표준과 동일한 금액으로 한다.","본점을 외국에 둔 단체는 사업의 실질적 관리장소가 국내에 소재하더라도 법인지방소득세를 부과할 경우에는 외국법인으로 본다.","연결납세방식이란 둘 이상의 법인을 하나의 계산 단위로 하여 법인지방소득세를 신고․납부하는 방식으로 내국법인과 외국법인 모두 연결법인에 포함된다.","사업장이 둘 이상의 지방자치단체에 있는 법인은 각 사업장의 종업원 수 기준이나 건축물 연면적 기준 중 어느 하나를 선택한 방법으로 안분한 법인지방소득세를 관할 지방자치단체의 장에게 각각 신고납부하여야 한다."],"a":1}},{"y":2023,"e":"지방직 9급","qn":9,"i":"L92023-09","t":"지방세법 상 지방소득세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법 상 지방소득세에 대한 설명으로 옳은 것은?","d":"(단, 비과세, 소액징수면제, 특별징수 및 법인과세 신탁재산은 고려하지 않는다)","o":["내국법인의 각 사업연도의 소득에 대한 법인지방소득세의 지방세 특례제한법 에 따른 공제세액 또는 감면세액이 법인지방소득세 산출세액을 초과하는 경우에는 그 초과금액은 이월공제된다.","거주자가 주소 또는 거소를 국외로 이전하여 비거주자가 되는 경우의 개인지방소득세 과세기간은 1월 1일부터 출국한 날의 전날까지로 한다.","법인지방소득세의 납세지는 사업연도 종료일 현재의 법인세법 제9조에 따른 납세지로 하되, 법인 또는 연결법인이 둘 이상의 지방자치단체에 사업장이 있는 경우에는 각각의 사업장 소재지를 납세지로 한다.","비영리내국법인의 법인지방소득은 법인세법 제4조제3항에 따른 수익사업에서 생기는 각 사업연도의 소득, 청산소득 및 법인세법 제55조의2에 따른 토지 등의 양도소득이 포함된다."],"a":3}},{"y":2025,"e":"지방직 9급","qn":2,"i":"L92025-02-1","t":"종합소득에 대한 개인지방소득세의 세율은 지방세법에서 따로 규정하고 있으며, 지방자치단체의 장은 조례로 가감할 수 없다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 거주자의 지방소득세"},{"y":2025,"e":"지방직 9급","qn":2,"i":"L92025-02-2","t":"종합소득에 대한 개인지방소득세의 공제세액 또는 감면세액이 산출세액을 초과하는 경우에는 그 초과금액은 이월공제된다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 거주자의 지방소득세"},{"y":2025,"e":"지방직 9급","qn":2,"i":"L92025-02-3","t":"개인지방소득세 확정신고를 한 거주자가 납세지를 관할하는 지방자치단체의 장 외의 지방자치단체의 장에게 수정신고를 한 경우에는 그 신고의 효력이 없다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 거주자의 지방소득세"},{"y":2025,"e":"지방직 9급","qn":2,"i":"L92025-02-4","t":"납세지 관할 지방자치단체의 장은 개인지방소득세의 과세표준과 세액을 결정 또는 경정한 후 그 결정 또는 경정에 오류나 누락이 있는 것을 발견한 경우에는 즉시 이를 다시 경정한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 거주자의 지방소득세"},{"y":2025,"e":"지방직 9급","qn":5,"i":"L92025-05","t":"지방세법 상 지방소득세에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법 상 지방소득세에 대한 설명으로 옳지 않은 것은?","d":"(단, 특별징수, 법인과세 신탁재산은 고려하지 않는다)","o":["거주자의 개인지방소득은 종합소득, 퇴직소득, 양도소득으로 구분한다.","법인지방소득세의 납세지는 사업연도 종료일 현재의 법인세법 에 따른 납세지로 한다. 다만, 법인 또는 연결법인이 둘 이상의 지방자치단체에 사업장이 있는 경우에는 각각의 사업장 소재지를 납세지로 한다.","소득세법 , 법인세법 및 조세특례제한법 에 따라 소득세 또는 법인세가 비과세되는 소득에 대하여는 지방소득세를 과세하지 아니한다.","비거주자에 대하여 과세하는 개인지방소득세는 해당 국내원천소득을 종합하여 과세하는 경우와 분류하여 과세하는 경우를 구분하지 않고 계산한다."],"a":4}},{"y":2025,"e":"지방직 9급","qn":20,"i":"L92025-20","t":"지방세법 상 지방소비세와 지방소득세에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세법 상 지방소비세와 지방소득세에 대한 설명으로 옳지 않은 것은?","d":"(단, 특별징수하는 지방소득세, 소규모사업자 등 대통령령으로 정하는 거주자, 분할납부는 고려하지 않는다)","o":["지방소비세의 과세표준은 부가가치세의 과세표준과 동일하고, 거주자의 종합소득에 대한 개인지방소득세 과세표준은 소득세법 에 따라 계산한 소득세의 과세표준과 동일한 금액으로 한다.","개인지방소득세의 납세지는 지방세기본법 제34조에 따른 납세의무 성립 당시의 소득세법 제6조 및 제7조에 따른 납세지로 한다.","지방소비세와 부가가치세를 신고할 경우에는 지방세법 제69조 (과세표준 및 세액)제2항에 따른 지방소비세와 부가가치세법 제72조(부가가치세의 세액 등에 관한 특례)에 따른 부가가치세가 합쳐진 금액으로 신고하여야 한다.","거주자가 소득세법 에 따라 종합소득에 대한 과세표준확정신고를 하는 경우에는 해당 신고기한까지 종합소득에 대한 개인지방소득세 과세표준과 세액을 대통령령으로 정하는 바에 따라 납세지 관할 지방자치단체의 장에게 확정신고ㆍ납부하여야 한다."],"a":1}}],"10":[{"y":2015,"e":"지방직 9급","qn":16,"i":"L92015-16-1","t":"배기량이 2천시시로서 법정규모 이하인 승용차를 비영업용 승용자동차로 취득하는 경우에는 2015년 12월 31일까지 취득세를 면제한다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법 상 과세면제 및 경감"},{"y":2015,"e":"지방직 9급","qn":16,"i":"L92015-16-2","t":"지방세의 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 지방세 감면 신청을 하여야 한다. 다만, 지방자치단체의 장이 감면대상을 알 수 있을 때에는 직권으로도 감면할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법 상 과세면제 및 경감"},{"y":2015,"e":"지방직 9급","qn":16,"i":"L92015-16-4","t":"자동차관리법 제53조에 따라 자동차매매업을 등록한 자가 매매용으로 취득하는 중고 자동차에 대하여는 2027년 12월 31일까지 취득세와 자동차세를 면제한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법 상 과세면제 및 경감","t0":"자동차관리법 제53조에 따라 자동차매매업을 등록한 자가 매매용으로 취득하는 중고 자동차에 대하여는 2015년 12월 31일까지 취득세와 자동차세를 면제한다.","ox0":"O","rv":"개정 반영"},{"y":2015,"e":"지방직 9급","qn":17,"i":"L92015-17-1","t":"천재지변, 소실, 도괴, 그 밖의 불가항력으로 멸실 또는 파손된 건축물을 복구하기 위하여 멸실일 또는 파손일부터 2년 이내에 종전 건물의 연면적과 동일하게 건축 또는 개수하여 대체 취득하는 경우에는 취득세를 면제한다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법 상 천재지변 등으로 인한 대체취득과 관련한 지방세의 감면"},{"y":2015,"e":"지방직 9급","qn":17,"i":"L92015-17-2","t":"천재지변, 소실, 도괴, 그 밖의 불가항력으로 파손된 선박을 복구하기 위하여 그 파손일부터 2년 이내에 종전 선박과 동일한 톤수로 새로 건조하여도 새로 건조한 선박의 가액이 종전 선박의 가액을 초과하는 경우에는 그 초과부분에 대하여 취득세를 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법 상 천재지변 등으로 인한 대체취득과 관련한 지방세의 감면"},{"y":2015,"e":"지방직 9급","qn":17,"i":"L92015-17-3","t":"천재지변, 소실, 도괴, 그 밖의 불가항력으로 파손된 건축물의 말소등기와 멸실 또는 파손된 건축물을 복구하기 위하여 그 멸실일 또는 파손일부터 2년 이내에 신축 또는 개축을 위한 건축허가 면허에 대하여는 등록면허세를 면제한다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법 상 천재지변 등으로 인한 대체취득과 관련한 지방세의 감면"},{"y":2015,"e":"지방직 9급","qn":17,"i":"L92015-17-4","t":"천재지변ㆍ화재ㆍ교통사고 등으로 소멸ㆍ멸실 또는 파손되어 해당 자동차를 회수하거나 사용할 수 없는 것으로 시장ㆍ군수가 인정하는 자동차에 대하여는 자동차세를 면제한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법 상 천재지변 등으로 인한 대체취득과 관련한 지방세의 감면"},{"y":2016,"e":"지방직 9급","qn":16,"i":"L92016-16-1","t":"지방세특례제한법, 지방세기본법, 지방세법, 조세특례 제한법 및 조약에 따르지 아니하고는 지방세법에서 정한 일반과세에 대한 지방세 특례를 정할 수 없다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2016,"e":"지방직 9급","qn":16,"i":"L92016-16-2","t":"행정안전부장관 및 지방자치단체는 지방세 특례를 정하려는 경우에는 공익성, 국가의 경제·사회 정책, 조세의 형평성, 지방세 특례 적용 대상자의 조세부담능력 및 지방자치단체의 재정여건 등을 종합적으로 고려하여야 한다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법 상 지방세 특례","t0":"행정자치부장관 및 지방자치단체는 지방세 특례를 정하려는 경우에는 공익성, 국가의 경제·사회 정책, 조세의 형평성, 지방세 특례 적용 대상자의 조세부담능력 및 지방자치단체의 재정여건 등을 종합적으로 고려하여야 한다.","ox0":"O","rv":"행정자치부장관→행정안전부장관"},{"y":2016,"e":"지방직 9급","qn":16,"i":"L92016-16-3","t":"지방자치단체의 장은 지방세 감면 등 지방세 특례에 따른 재정 지원의 직전 회계연도의 실적과 해당 회계연도의 추정 금액에 대한 보고서를 작성하여 지방의회에 제출하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2016,"e":"지방직 9급","qn":16,"i":"L92016-16-4","t":"지방자치단체는 지방세법에 따른 토지에 대한 재산세 과세 대상의 구분(종합합산, 별도합산, 분리과세) 전환을 통해서도 지방세 감면이 가능하다.","ox":"X","m":"④","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2017,"e":"지방직 9급","qn":6,"i":"L92017-06-1","t":"이월공제가 인정되는 개인지방소득세의 세액공제를 하는 경우 해당 과세기간 중에 발생한 세액공제액과 이전 과세기간에서 이월된 미공제액이 함께 있을 때에는 그 중 하나를 선택하여 먼저 공제할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법 상 지방세의 세액감면과 세액공제 등"},{"y":2017,"e":"지방직 9급","qn":6,"i":"L92017-06-2","t":"동일한 과세대상에 대하여 지방세를 감면할 때 지방세특례 제한법 제73조의 토지수용 등으로 인한 대체취득에 대한 감면 규정과 동법 제74조의 도시개발사업 등에 대한 감면 규정이 중복되는 경우에는 두 개의 감면 규정을 모두 적용할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법 상 지방세의 세액감면과 세액공제 등"},{"y":2017,"e":"지방직 9급","qn":6,"i":"L92017-06-3","t":"지방자치단체는 사회적 취약계층 보호, 공익 목적, 그 밖에 전국적으로 동일한 지방세 감면이 필요한 경우 등으로서 대통령령으로 정하는 사항에 대해서는 지방세 감면율을 인하 하여 조정할 수 없다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법 상 지방세의 세액감면과 세액공제 등"},{"y":2017,"e":"지방직 9급","qn":6,"i":"L92017-06-4","t":"지방세의 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 지방세 감면 신청을 하여야 하고, 지방자치단체의 장이 감면대상을 알 수 있을 때에도 직권으로 감면할 수 없다.","ox":"X","m":"④","c":"A","tp":"지방세특례제한법 상 지방세의 세액감면과 세액공제 등"},{"y":2018,"e":"지방직 9급","qn":10,"i":"L92018-10-1","t":"동일한 과세대상에 대하여 지방세를 감면할 때 지방세특례 제한법 제20조(노인복지시설에 대한 감면)와 제22조(사회복지 법인 등에 대한 감면)의 감면 규정이 동시에 적용되는 경우 지방세특례제한법 제20조 및 제22조의 감면 규정을 모두 적용할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2018,"e":"지방직 9급","qn":10,"i":"L92018-10-2","t":"지방자치단체는 사회적 취약계층 보호, 공익 목적, 그 밖에 전국적으로 동일한 지방세 감면이 필요한 경우 등으로서 대통령령으로 정하는 사항에 대해서는 지방세 감면율을 인하하여 조정할 수 없다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2018,"e":"지방직 9급","qn":10,"i":"L92018-10-3","t":"개인지방소득세의 감면에 관한 규정과 세액공제에 관한 규정이 동시에 적용되는 경우 그 적용순위는 해당 과세기간의 소득에 대한 개인지방소득세의 감면, 이월공제가 인정되지 아니하는 세액공제, 이월공제가 인정되는 세액공제(이 경우 해당 과세기간 중에 발생한 세액공제액과 이전 과세기간에서 이월된 미공제액이 함께 있을 때에는 이월된 미공제액을 먼저 공제한다)의 순서로 한다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2018,"e":"지방직 9급","qn":10,"i":"L92018-10-4","t":"지방세의 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 지방세 감면 신청을 하여야 한다. 다만, 지방자치단체의 장이 감면대상을 알 수 있을 때에는 직권으로 감면할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2018,"e":"지방직 9급","qn":19,"i":"L92018-19-1","t":"‘지방세 특례’란 세율의 경감, 세액감면, 세액공제, 과세표준 공제(중과세 배제, 재산세 과세대상 구분전환은 제외) 등을 말한다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2018,"e":"지방직 9급","qn":19,"i":"L92018-19-2","t":"지방자치단체의 장은 천재지변이나 그 밖에 대통령령으로 정하는 특수한 사유로 지방세 감면이 필요하다고 인정되는 자에 대해서는 해당 지방의회의 의결을 얻어 지방세 감면을 할 수 있다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2018,"e":"지방직 9급","qn":19,"i":"L92018-19-3","t":"지방자치단체의 장은 지방세 감면 등 지방세 특례에 따른 재정 지원의 직전 회계연도의 실적과 해당 회계연도의 추정 금액에 대한 보고서를 작성하여 행정안전부장관에게 제출 하여야 한다.","ox":"X","m":"③","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2018,"e":"지방직 9급","qn":19,"i":"L92018-19-4","t":"지방자치단체의 장은 지방세 감면에 관한 사항을 정비하여야 하며, 그 정비 결과를 지방의회에게 제출하여야 한다.","ox":"X","m":"④","c":"A","tp":"지방세특례제한법 상 지방세 특례"},{"y":2019,"e":"지방직 9급","qn":8,"i":"L92019-08-1","t":"지방세를 감면받은 자는 대통령령으로 정하는 바에 따라 관할 지방자치단체의 장에게 감면에 관한 자료를 제출하여야 한다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법령상 감면신청 등"},{"y":2019,"e":"지방직 9급","qn":8,"i":"L92019-08-2","t":"자동차에 대한 취득세 감면의 경우 해당 자동차의 사용본거지를 관할하지 아니하는 시장·군수·구청장은 감면신청서의 제출에 따른 업무를 처리할 수 없다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법령상 감면신청 등"},{"y":2019,"e":"지방직 9급","qn":8,"i":"L92019-08-3","t":"부동산에 대한 취득세의 감면을 신청하려는 자는 감면대상을 취득한 날부터 60일 이내에 행정안전부령으로 정하는 감면 신청서를 관할 시장·군수·구청장에게 제출하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법령상 감면신청 등"},{"y":2019,"e":"지방직 9급","qn":8,"i":"L92019-08-4","t":"지방자치단체의 장이 지방세의 감면대상을 알 수 있을 때에는 직권으로 감면할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법령상 감면신청 등"},{"y":2019,"e":"지방직 9급","qn":17,"i":"L92019-17-1","t":"종교단체가 과세기준일 현재 제3자의 부동산을 무상으로 종교행위를 목적으로 하는 사업에 직접 사용하더라도 그 부동산에 대한 재산세를 면제하는 경우는 없다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법 상 종교단체가 취득하거나 사용하는 부동산"},{"y":2019,"e":"지방직 9급","qn":17,"i":"L92019-17-2","t":"종교단체가 종교행위를 목적으로 하는 사업에 직접 사용하기 위하여 취득한 부동산을 취득한 날부터 5년 이내에 수익사업에 사용하는 경우 면제된 취득세를 추징한다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법 상 종교단체가 취득하거나 사용하는 부동산"},{"y":2019,"e":"지방직 9급","qn":17,"i":"L92019-17-3","t":"법인의 사업장 중 종교의식을 행하는 교회·성당·사찰·불당 등에 대해서는 주민세 균등분을 면제한다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법 상 종교단체가 취득하거나 사용하는 부동산"},{"y":2019,"e":"지방직 9급","qn":17,"i":"L92019-17-4","t":"종교단체가 종교행위를 목적으로 하는 사업에 직접 사용하기 위하여 취득한 부동산을 해당 용도로 직접 사용한 기간이 2년 미만인 상태에서 증여하는 경우 면제된 취득세를 추징한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법 상 종교단체가 취득하거나 사용하는 부동산"},{"y":2020,"e":"지방직 9급","qn":6,"i":"L92020-06","t":"다음 중 지방세특례제한법 상 지방세법 에서 정한 일반과세에 대한 지방세 특례를 둘 수 있는 근거법원(法源)의 총 개수는?","c":"A","mc":{"s":"다음 중 지방세특례제한법 상 지방세법 에서 정한 일반과세에 대한 지방세 특례를 둘 수 있는 근거법원(法源)의 총 개수는?","d":"○ 지방세기본법\n○ 지방세징수법\n○ 지방세법\n○ 조세특례제한법\n○ 조약","o":["2개","3개","4개","5개"],"a":4}},{"y":2020,"e":"지방직 9급","qn":16,"i":"L92020-16","t":"지방세특례제한법 상 ‘자경농민의 농지 등에 대한 감면’에 관한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"지방세특례제한법 상 ‘자경농민의 농지 등에 대한 감면’에 관한 설명으로 옳지 않은 것은?","d":"(단, ‘자경농민’은 지방세특례제한법 상 자경농민을 말함)","o":["자경농민이 창고[저온창고, 상온창고(常溫倉庫)만 해당하며 농기계보관용 창고는 제외함] 및 농산물 선별처리시설로서 대통령령으로 정하는 기준에 적합한 시설을 농업용으로 직접 사용하기 위하여 취득하는 경우 해당 농업용 시설에 대해서는 취득세의 100분의 50을 법정기한까지 경감한다.","대통령령으로 정하는 바에 따라 농업을 주업으로 하는 사람으로서 2년 이상 영농에 종사한 사람은 자경농민에 해당한다.","자경농민이 대통령령으로 정하는 기준에 따라 직접 경작할 목적으로 취득하는 농지(논, 밭, 과수원 및 목장용지를 말함)에 대해서는 취득세의 100분의 50을 법정기한까지 경감한다.","자경농민이 경작할 목적으로 받는 도로점용, 하천점용 및 공유수면점용의 면허에 대해서는 등록면허세를 법정기한까지 면제한다."],"a":1}},{"y":2021,"e":"지방직 9급","qn":18,"i":"L92021-18-1","t":"지방자치단체의 장은 천재지변이나 그 밖에 대통령령으로 정하는 특수한 사유로 지방세 감면이 필요하다고 인정되는 자에 대해서는 해당 지방의회의 의결을 얻어 지방세 감면을 할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법령상 조례에 따른 지방세감면"},{"y":2021,"e":"지방직 9급","qn":18,"i":"L92021-18-2","t":"지방자치단체는 지방세특례제한법의 위임에 따라 지방세 감면을 하려면 지방세기본법 제147조에 따른 지방세심의 위원회의 심의를 거쳐 조례로 정하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법령상 조례에 따른 지방세감면"},{"y":2021,"e":"지방직 9급","qn":18,"i":"L92021-18-3","t":"지방자치단체는 지방세법 제13조(과밀억제권역 안 취득 등 중과) 및 제28조제2항에 따른 중과세의 배제를 통한 지방세 감면에 해당하는 지방세 감면을 할 수 없다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법령상 조례에 따른 지방세감면"},{"y":2021,"e":"지방직 9급","qn":18,"i":"L92021-18-4","t":"지방자치단체는 지방세 감면에 관한 사항을 정비하여야 하며, 지방자치단체의 장은 정비 결과를 행정안전부장관에게 제출 하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법령상 조례에 따른 지방세감면"},{"y":2021,"e":"지방직 9급","qn":20,"i":"L92021-20","t":"그 면제된 취득세의 추징에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"그 면제된 취득세의 추징에 대한 설명으로 옳지 않은 것은?","d":"지방세특례제한법 상 사회복지사업법 에 따른 사회복지법인이 해당 사회복지사업에 직접 사용하기 위하여 취득한 부동산은 취득세가 면제된다.","o":["해당 부동산을 해당 용도로 직접 사용한 기간이 2년 미만인 상태에서 매각․증여하는 경우 그 해당 부분에 대해서는 면제된 취득세를 추징한다.","해당 부동산을 취득한 날부터 3년이 경과한 날에 수익사업에 사용한 경우 면제된 취득세를 추징하지 아니한다.","정당한 사유 없이 해당 부동산의 취득일부터 3년이 경과할 때까지 해당 용도로 직접 사용하지 아니하는 경우 그 해당 부분에 대해서는 면제된 취득세를 추징한다.","해당 부동산을 2년 이상 해당 용도로 직접 사용한 후에 다른 용도로 사용하는 경우(수익사업에 사용하는 경우는 제외) 면제된 취득세를 추징하지 아니한다."],"a":2}},{"y":2022,"e":"지방직 9급","qn":16,"i":"L92022-16-1","t":"광업권의 설정·변경·이전, 그 밖의 등록에 해당하는 면허로서 면허를 새로 받거나 변경받는 경우에는 면허에 대한 등록면허세를 2027년 12월 31일까지 면제한다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법 상 감면","t0":"광업권의 설정·변경·이전, 그 밖의 등록에 해당하는 면허로서 면허를 새로 받거나 변경받는 경우에는 면허에 대한 등록면허세를 2024년 12월 31일까지 면제한다.","ox0":"O","rv":"개정 반영"},{"y":2022,"e":"지방직 9급","qn":16,"i":"L92022-16-2","t":"천재지변으로 멸실된 건축물을 그 멸실일부터 2년 이내에 새로 취득하는 경우, 그 새로 취득한 건축물의 연면적이 종전의 건축물의 연면적을 초과하면 그 초과부분에 대해서도 취득세를 면제한다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법 상 감면"},{"y":2022,"e":"지방직 9급","qn":16,"i":"L92022-16-3","t":"여객자동차 운수사업법 제4조에 따라 여객자동차운송사업 면허를 받거나 등록을 한 자가 같은 법제3조에 따른 여객자동차 운송사업 중 시내버스운송사업·농어촌버스운송사업·마을버스 운송사업 또는 시외버스운송사업에 직접 사용하기 위하여 취득하는 자동차에 대해서는 자동차세를 2024년 12월 31일까지 면제한다.","ox":"X","m":"③","c":"A","tp":"지방세특례제한법 상 감면"},{"y":2022,"e":"지방직 9급","qn":16,"i":"L92022-16-4","t":"장애인이 대통령령으로 정하는 바에 따라 대체취득을 하는 경우 해당 자동차에 대해서는 자동차 주행에 대한 자동차세를 면제한다.","ox":"X","m":"④","c":"A","tp":"지방세특례제한법 상 감면"},{"y":2023,"e":"지방직 9급","qn":13,"i":"L92023-13-1","t":"풍수해를 사유로 지방세 감면을 받으려는 자는 그 사유가 발생한 날부터 2개월 이내에 관할 지방자치단체의 장에게 지방세 감면을 신청하여야 하고, 그 지방자치단체의 장은 지방의회의 의결을 거쳐 해당 지방세를 감면하여야 한다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법령상 지방세 감면"},{"y":2023,"e":"지방직 9급","qn":13,"i":"L92023-13-2","t":"지방자치단체의 재정여건은 행정안전부장관 및 지방자치단체가 지방세 특례를 정하려는 경우에 종합적으로 고려하여야 할 사항 중의 하나에 해당한다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법령상 지방세 감면"},{"y":2023,"e":"지방직 9급","qn":13,"i":"L92023-13-3","t":"지방자치단체는 지방세 감면에 관한 사항을 정비하여야 하며, 지방자치단체의 장은 정비 결과를 행정안전부장관에게 제출하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방세특례제한법령상 지방세 감면"},{"y":2023,"e":"지방직 9급","qn":13,"i":"L92023-13-4","t":"지방자치단체의 장은 지방세 감면 등 지방세 특례에 따른 재정 지원의 직전 회계연도의 실적과 해당 회계연도의 추정 금액에 대한 보고서를 작성하여 지방의회에 제출하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법령상 지방세 감면"},{"y":2023,"e":"지방직 9급","qn":19,"i":"L92023-19-1","t":"2년 이상 영농에 종사한 사람이 직접 경작할 목적으로 국토의 계획 및 이용에 관한 법률에 따른 도시지역(개발제한구역과 녹지지역은 제외함) 내에 있는 농지를 취득한 경우에 그 농지에 대해서는 취득세의 100분의 50을 경감한다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법령상 ‘자경농민의 농지 등"},{"y":2023,"e":"지방직 9급","qn":19,"i":"L92023-19-2","t":"농지를 취득한 본인과 배우자(주민등록법에 따른 세대별 주민 등록표에 함께 기재되어 있는 경우로 한정함) 모두 2년 이상 농업에 종사하거나 농지 취득일 현재 그 소재지로부터 30킬로미터 이내의 지역에 거주하여야 자경농민이 된다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법령상 ‘자경농민의 농지 등"},{"y":2023,"e":"지방직 9급","qn":19,"i":"L92023-19-3","t":"농지를 취득한 사람이 그 취득일부터 90일 이내에 귀농인이 되면 그 농지에 대한 취득세를 경감하고, 귀농인이 된 때부터 2년 이내에 그 농지를 직접 경작하지 아니하면 경감된 취득세를 추징한다.","ox":"X","m":"③","c":"A","tp":"지방세특례제한법령상 ‘자경농민의 농지 등"},{"y":2023,"e":"지방직 9급","qn":19,"i":"L92023-19-4","t":"농지의 취득세를 경감받은 자경농민이 해당 농지를 직접 경작한 기간이 2년 미만인 상태에서 다른 용도로 사용하였을 때에는 그 해당 부분에 대해서는 경감된 취득세를 추징한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법령상 ‘자경농민의 농지 등"},{"y":2024,"e":"지방직 9급","qn":16,"i":"L92024-16-1","t":"부동산에 대한 감면을 적용할 때 지방세특례제한법에서 특별히 규정한 경우를 제외하고는 정당한 사유 없이 그 취득일부터 1년이 경과할 때까지 해당 용도로 직접 사용하지 아니하는 경우 그 해당 부분에 대해서는 감면된 취득세를 추징한다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2024,"e":"지방직 9급","qn":16,"i":"L92024-16-2","t":"중앙행정기관의 장은 조례에 따른 지방세 감면제도의 신설, 연장 또는 폐지 등을 요청하려는 경우에는 지방세감면건의서 또는 지방세감면평가서를 해당 지방자치단체의 장에게 제출하여야 한다.","ox":"O","m":"②","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2024,"e":"지방직 9급","qn":16,"i":"L92024-16-3","t":"지방자치단체는 지방세특례제한법에 따른 지방세 감면 중 지방세 감면 기한이 연장되는 경우에는 지방자치단체의 재정여건, 감면 대상자의 조세부담능력 등을 고려하여 해당 조에 따른 지방세 감면율을 100분의 80의 범위에서 조례로 인하하여 조정할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2024,"e":"지방직 9급","qn":16,"i":"L92024-16-4","t":"지방세의 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 지방세 감면 신청을 하여야 하지만, 지방자치단체의 장이 감면대상을 알 수 있을 때에는 직권으로 감면할 수 있다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법 상 지방세 감면"},{"y":2024,"e":"지방직 9급","qn":20,"i":"L92024-20-1","t":"지방자치단체는 주민의 복리 증진 등 효율적인 정책 추진을 위하여 필요하다고 인정될 경우 5년의 기간 이내에서 지방세 감면을 할 수 있다.","ox":"X","m":"①","c":"A","tp":"지방세특례제한법 상 총칙"},{"y":2024,"e":"지방직 9급","qn":20,"i":"L92024-20-2","t":"지방자치단체의 장은 천재지변이나 그 밖에 대통령령으로 정하는 특수한 사유로 지방세 감면이 필요하다고 인정되는 자에 대해서는 해당 지방자치단체장의 직권으로 지방세 감면을 할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법 상 총칙"},{"y":2024,"e":"지방직 9급","qn":20,"i":"L92024-20-3","t":"지방자치단체는 지방세특례제한법의 위임에 따른 지방세 감면을 하려면 지방세기본법에 따른 지방세심의위원회의 심의를 거쳐 조례로 정하여야 한다.","ox":"X","m":"③","c":"A","tp":"지방세특례제한법 상 총칙"},{"y":2024,"e":"지방직 9급","qn":20,"i":"L92024-20-4","t":"지방자치단체의 장은 지방세 감면 등 지방세 특례에 따른 재정 지원의 직전 회계연도의 실적과 해당 회계연도의 추정 금액에 대한 보고서를 작성하여 지방의회에 제출하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세특례제한법 상 총칙"},{"y":2025,"e":"지방직 9급","qn":18,"i":"L92025-18-1","t":"지방세지출보고서의 작성방법 등에 관하여는 행정안전부장관이 정한다.","ox":"O","m":"①","c":"A","tp":"지방세특례제한법령상 지방세지출보고서와 지방세 감면"},{"y":2025,"e":"지방직 9급","qn":18,"i":"L92025-18-2","t":"지방자치단체의 장이 주요 역점사업 추진을 위해 필요하다고 인정한 경우 지방자치단체는 5년의 기간 이내에서 지방세 감면을 확대하는 지방세 감면을 할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세특례제한법령상 지방세지출보고서와 지방세 감면"},{"y":2025,"e":"지방직 9급","qn":18,"i":"L92025-18-3","t":"지방자치단체의 장은 천재지변으로 지방세 감면이 필요하다고 인정되는 자에 대해서는 행정안전부장관의 허가를 얻어 세율경감을 할 수 있다.","ox":"X","m":"③","c":"A","tp":"지방세특례제한법령상 지방세지출보고서와 지방세 감면"},{"y":2025,"e":"지방직 9급","qn":18,"i":"L92025-18-4","t":"지방자치단체는 조세특례제한법의 위임에 따른 지방세 감면을 하려면 지방세심의위원회의 심의를 거쳐 조례로 정하여야 한다.","ox":"X","m":"④","c":"A","tp":"지방세특례제한법령상 지방세지출보고서와 지방세 감면"}],"5":[{"y":2015,"e":"지방직 9급","qn":20,"i":"L92015-20-1","t":"자동차 주행에 대한 자동차세의 세율은 과세물품에 대한 교통·에너지·환경세액의 1천분의 360으로 하며, 교통·에너지·환경세율의 변동 등으로 조정이 필요하면 그 세율의 100분의 30의 범위에서 대통령령으로 정하는 바에 따라 가감 하여 조정할 수 있다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 자동차세"},{"y":2015,"e":"지방직 9급","qn":20,"i":"L92015-20-2","t":"지방자치단체의 장은 자동차 소유에 대한 자동차세의 세율을 조례로 정하는 바에 따라 자동차 배기량 등을 고려하여 표준 세율의 100분의 50의 범위에서 가감하여 정할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 자동차세"},{"y":2015,"e":"지방직 9급","qn":20,"i":"L92015-20-3","t":"자동차 소유에 대한 자동차세는 지방자치단체 관할구역에 등록 되어 있거나 신고되어 있는 자동차를 소유하는 자에게 부과 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 자동차세"},{"y":2015,"e":"지방직 9급","qn":20,"i":"L92015-20-4","t":"과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매수인이 자동차세 납부의무를 진다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 자동차세"},{"y":2016,"e":"지방직 9급","qn":18,"i":"L92016-18-1","t":"연세액(年稅額)이 10만원 이하인 자동차세는 제1기분을 부과할 때 전액을 부과·징수할 수 있으며, 이 경우 제1기분과 제2기분 세액의 100분의 10을 공제한 금액을 연세액으로 한다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2016,"e":"지방직 9급","qn":18,"i":"L92016-18-2","t":"과세기준일 현재 상속이 개시된 자동차로서 사실상의 소유자 명의로 이전등록을 하지 아니한 경우에는 상속지분의 규모에 관계없이 상속인 중 연장자가 우선적으로 자동차세를 납부할 의무를 진다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2016,"e":"지방직 9급","qn":18,"i":"L92016-18-3","t":"지방자치단체의 장은 영업용 자동차가 비영업용이 되는 경우 자동차세를 수시로 부과할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2016,"e":"지방직 9급","qn":18,"i":"L92016-18-4","t":"승합자동차의 자동차세는 배기량에 시시당 세액을 곱하여 산정한 세액을 자동차 1대당 연세액으로 한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2017,"e":"지방직 9급","qn":14,"i":"L92017-14","t":"지방세법 상 자동차 소유에 대한 자동차세를 수시로 부과할 수 있는 경우는 모두 몇 개인가?","c":"A","mc":{"s":"지방세법 상 자동차 소유에 대한 자동차세를 수시로 부과할 수 있는 경우는 모두 몇 개인가?","d":"(단, 신고납부하거나 연세액을 한꺼번에 부과․징수하는 경우는 없다고 가정한다)\n○ 자동차를 신규등록하는 경우\n○ 비과세 또는 감면대상 자동차가 과세대상이 되는 경우\n○ 과세대상 자동차가 비과세 또는 감면대상이 되는 경우\n○ 비영업용 자동차가 영업용이 되는 경우\n○ 자동차를 승계취득함으로써 일할계산하여 부과․징수 하는 경우\n○ 자동차를 말소등록하는 경우","o":["3개","4개","5개","6"],"a":4}},{"y":2021,"e":"지방직 9급","qn":11,"i":"L92021-11-1","t":"자동차 소유에 대한 자동차세의 경우 과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매도인이 자동차세를 납부할 의무를 진다.","ox":"X","m":"①","c":"A","tp":"지방세법령상 자동차세"},{"y":2021,"e":"지방직 9급","qn":11,"i":"L92021-11-2","t":"자동차 주행에 대한 자동차세의 세율은 교통·에너지·환경세율의 변동 등으로 조정이 필요하면 그 세율의 100분의 50의 범위에서 조례로 정하는 바에 따라 가감하여 조정할 수 있다.","ox":"X","m":"②","c":"A","tp":"지방세법령상 자동차세"},{"y":2021,"e":"지방직 9급","qn":11,"i":"L92021-11-3","t":"자동차 소유에 대한 자동차세의 부과대상이 되는 “자동차”란 자동차관리법에 따라 등록되거나 신고된 차량과 건설기계 관리법에 따라 등록된 덤프트럭과 콘크리트믹서트럭을 말한다.","ox":"O","m":"③","c":"A","tp":"지방세법령상 자동차세"},{"y":2021,"e":"지방직 9급","qn":11,"i":"L92021-11-4","t":"자동차 소유에 대한 자동차세의 경우 과세기준일 현재 상속이 개시된 자동차로서 사실상의 소유자 명의로 이전등록을 하지 아니한 경우에는 사실상의 사용자, 연장자의 순서로 자동차세를 납부할 의무를 진다.","ox":"X","m":"④","c":"A","tp":"지방세법령상 자동차세"},{"y":2022,"e":"지방직 9급","qn":20,"i":"L92022-20","t":"지방세법령상 자동차 소유에 대한 자동차세 중 자동차 1대당 연세액이 큰 것부터 바르게 나열한 것은?","c":"A","mc":{"s":"지방세법령상 자동차 소유에 대한 자동차세 중 자동차 1대당 연세액이 큰 것부터 바르게 나열한 것은?","d":"(단, 비과세와 지방세 특례는 고려하지 않는다) (가) 고속버스 (나) 대형전세버스 (다) 비영업용 대형일반버스 (라) 비영업용 소형일반버스","o":["(가), (나), (다), (라)","(가), (다), (라), (나)","(다), (가), (나), (라)","(다), (나), (가), (라)"],"a":3}},{"y":2023,"e":"지방직 9급","qn":20,"i":"L92023-20","t":"지방세법 상 ‘자동차 소유에 대한 자동차세’에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"지방세법 상 ‘자동차 소유에 대한 자동차세’에 대한 설명으로 옳은 것만을 모두 고르면?","d":"(단, 지방세법 제130조(수시부과 시의 세액 계산), 비과세, 면세 등 지방세 특례는 고려하지 않는다)\nㄱ. 과세기간 중에 매매로 인하여 자동차를 승계취득한 자가 자동차 소유권 이전 등록을 하는 경우에는 그 소유기간에 따라 자동차세를 일할계산하여 양도인과 양수인에게 각각 부과ㆍ징수한다.\nㄴ. 자동차에 관한 지방자치단체의 징수금을 납부하지 아니하거나 납부한 금액이 부족할 때에는 반드시 독촉절차를 거쳐 체납처분을 하여야 한다.\nㄷ. 과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매도인이 자동차세를 납부할 의무를 진다.\nㄹ. 지방자치단체의 장은 조례로 정하는 바에 따라 자동차세의 세율을 배기량 등을 고려하여 표준세율의 100분의 50까지 초과하여 정할 수 있다.","o":["ㄱ, ㄹ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2024,"e":"지방직 9급","qn":9,"i":"L92024-09-1","t":"국가가 국방ㆍ경호ㆍ경비ㆍ교통순찰 또는 소방을 위하여 제공하는 자동차를 소유하는 자에 대하여는 자동차세를 부과하지 않는다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2024,"e":"지방직 9급","qn":9,"i":"L92024-09-2","t":"지방자치단체가 환자수송ㆍ청소ㆍ오물제거 또는 도로공사를 위하여 제공하는 자동차를 소유하는 자에 대하여는 자동차세를 부과하지 않는다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2024,"e":"지방직 9급","qn":9,"i":"L92024-09-3","t":"과세기준일 현재 상속이 개시된 자동차로서 사실상의 소유자 명의로 이전등록을 하지 아니한 경우에는 연장자, 민법상 상속지분이 가장 높은 자의 순서에 따라 자동차세를 납부할 의무를 진다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 자동차 소유"},{"y":2024,"e":"지방직 9급","qn":9,"i":"L92024-09-4","t":"과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매수인이 자동차세를 납부할 의무를 진다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 자동차 소유"}],"3":[{"y":2016,"e":"지방직 9급","qn":6,"i":"L92016-06","t":"지방세법 상 등록면허세를 과세하는 경우로 옳은 것은?","c":"A","mc":{"s":"지방세법 상 등록면허세를 과세하는 경우로 옳은 것은?","d":"","o":["사업주체의 변경에 따라 면허를 받은 자가 변경되는 경우","주한국제기구가 자기를 위하여 받는 등록 또는 면허","등기 담당 공무원의 착오로 인한 지번의 오기에 대한 경정등기","지목이 묘지인 토지 등 대통령령으로 정하는 등록"],"a":1}},{"y":2017,"e":"지방직 9급","qn":8,"i":"L92017-08-1","t":"같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 등록면허세"},{"y":2017,"e":"지방직 9급","qn":8,"i":"L92017-08-2","t":"한국은행법 및 한국수출입은행법에 따른 은행업을 영위 하는 법인이 대도시에서 지점이나 분사무소를 설치함에 따른 등기를 할 때에는 그 세율을 해당 표준세율의 100분의 300으로 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 등록면허세"},{"y":2017,"e":"지방직 9급","qn":8,"i":"L92017-08-3","t":"같은 채권을 위한 저당권의 목적물이 종류가 달라 둘 이상의 등기 또는 등록을 하게 되는 경우에 등기ㆍ등록관서가 이에 관한 등기 또는 등록 신청을 받았을 때에는 채권금액 전액에서 이미 납부한 등록면허세의 산출기준이 된 금액을 뺀 잔액을 그 채권금액으로 보고 등록면허세를 부과한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 등록면허세"},{"y":2017,"e":"지방직 9급","qn":8,"i":"L92017-08-4","t":"피상속인이 납부한 면허에 대한 등록면허세는 상속인이 납부한 것으로 보고, 합병으로 인하여 소멸한 법인이 납부한 면허에 대한 등록면허세는 합병 후 존속하는 법인 또는 합병으로 인하여 설립된 법인이 납부한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 등록면허세"},{"y":2018,"e":"지방직 9급","qn":16,"i":"L92018-16-1","t":"광업권 및 어업권의 취득에 따른 등록과 외국인 소유의 취득세 과세대상 물건(차량, 기계장비, 항공기 및 선박만 해당)을 임차하여 수입하는 경우의 연부 취득에 따른 등기 또는 등록은 등록면허세의 과세대상인 등기·등록에 포함된다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 등록면허세"},{"y":2018,"e":"지방직 9급","qn":16,"i":"L92018-16-2","t":"특별징수의무자(지식재산처장 또는 해당 등록기관의 장)가 특별 징수한 등록면허세를 납부하기 전에 해당 권리가 등록되지 아니하였거나 잘못 징수하거나 더 많이 징수한 사실을 발견 하였을 경우에는 특별징수한 등록면허세를 직접 환급할 수 있으며, 이 경우 지방세환급가산금을 환급금에 가산하여 환급하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 등록면허세","t0":"특별징수의무자(특허청장 또는 해당 등록기관의 장)가 특별 징수한 등록면허세를 납부하기 전에 해당 권리가 등록되지 아니하였거나 잘못 징수하거나 더 많이 징수한 사실을 발견 하였을 경우에는 특별징수한 등록면허세를 직접 환급할 수 있으며, 이 경우 지방세환급가산금을 환급금에 가산하여 환급하여야 한다.","ox0":"X","rv":"특허청→지식재산처"},{"y":2018,"e":"지방직 9급","qn":16,"i":"L92018-16-3","t":"제조·가공 또는 수입의 면허로서 각각 그 품목별로 받는 면허에 대하여는 면허를 할 때 한 번만 등록면허세를 부과한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 등록면허세"},{"y":2018,"e":"지방직 9급","qn":16,"i":"L92018-16-4","t":"자동차 등록과 관련한 등록면허세의 납세지는 자동차관리법에 따른 등록지이다. 다만, 등록지가 사용본거지와 다른 경우에는 사용본거지를 납세지로 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 등록면허세"},{"y":2019,"e":"지방직 9급","qn":5,"i":"L92019-05-1","t":"부동산 등기에 대한 등록면허세의 납세지는 부동산 소유자의 주소지이다.","ox":"X","m":"①","c":"A","tp":"지방세법 상 등록면허세"},{"y":2019,"e":"지방직 9급","qn":5,"i":"L92019-05-2","t":"등록을 하려는 자가 법정신고기한까지 산출세액의 신고의무를 다하지 않은 경우 산출세액을 등록을 하기 전까지 납부하였더라도 지방세기본법에 따른 무신고가산세를 부과한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 등록면허세"},{"y":2019,"e":"지방직 9급","qn":5,"i":"L92019-05-3","t":"상속으로 인한 부동산 소유권 이전 등기에 대한 세율은 부동산 가액의 1천분의 15로 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 등록면허세"},{"y":2019,"e":"지방직 9급","qn":5,"i":"L92019-05-4","t":"채권금액으로 과세액을 정하는 경우에 일정한 채권금액이 없을 때에는 채권의 목적이 된 것의 가액 또는 처분의 제한의 목적이 된 금액을 그 채권금액으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 등록면허세"},{"y":2021,"e":"지방직 9급","qn":15,"i":"L92021-15-1","t":"회사의 정리 또는 특별청산에 관하여 법원의 촉탁으로 인한 등기 또는 등록에 대하여는 등록면허세를 부과하지 아니하나, 법인의 자본금 또는 출자금의 납입, 증자 및 출자전환에 따른 등기 또는 등록은 제외한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 등록면허세"},{"y":2021,"e":"지방직 9급","qn":15,"i":"L92021-15-2","t":"부동산 등록에 대한 등록면허세의 과세표준은 조례로 정하는 바에 따라 등록자의 신고에 따르나, 신고가 없거나 신고가액이 지방세법 제4조에 따른 시가표준액보다 적은 경우에는 시가표준액을 과세표준으로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 등록면허세"},{"y":2021,"e":"지방직 9급","qn":15,"i":"L92021-15-3","t":"면허를 받은 후에 면허유효기간의 종료, 면허의 취소, 그밖에 이와 유사한 사유로 면허의 효력이 소멸한 경우에는 이미 납부한 등록면허세를 환급하지 아니한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 등록면허세"},{"y":2021,"e":"지방직 9급","qn":15,"i":"L92021-15-4","t":"등록면허세의 과세대상인 등록에는 지방세기본법 제38조에 따른 취득세 부과제척기간이 경과한 물건의 등기 또는 등록은 포함하지 아니한다.","ox":"X","m":"④","c":"A","tp":"지방세법 상 등록면허세"},{"y":2022,"e":"지방직 9급","qn":11,"i":"L92022-11","t":"지방세법 상 등록면허세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법 상 등록면허세에 대한 설명으로 옳은 것은?","d":"(단, 상호면세, 비과세 및 지방세 특례는 고려하지 않는다)","o":["외국인 소유의 취득세 과세대상 물건인 항공기의 연부 취득에 따른 등록은 등록면허세에서 사용하는 등록에 포함된다.","양식업권의 취득에 따른 등록은 등록면허세의 부과대상인 등록에 포함되지 않는다.","법인의 증자 및 출자전환에 따른 등기 또는 등록은 등록면허세의 부과대상인 등록에 포함되지 않는다.","변경면허를 받는 자는 등록면허세를 납부할 의무가 없다."],"a":1}},{"y":2023,"e":"지방직 9급","qn":1,"i":"L92023-01","t":"지방세법 상 등록면허세에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"지방세법 상 등록면허세에 대한 설명으로 옳은 것은?","d":"(단, 지방세 특례는 고려하지 않는다)","o":["법인의 자본금 또는 출자금의 납입, 증자 및 출자전환에 따른 등기 또는 등록에 대하여는 등록면허세를 부과한다.","자동차 등록의 경우 자동차관리법 에 따른 등록지가 사용본거지와 다른 경우에는 등록지를 납세지로 한다.","선박의 등록에 대한 등록면허세의 과세표준은 지방세법 제4조에 따른 시가표준액으로 하여야 하며, 등록자의 신고가액으로는 할 수 없다.","지방자치단체의 장은 조례로 정하는 바에 따라 부동산 등기에 대한 등록면허세의 세율을 표준세율의 100분의 80의 범위에서 가감할 수 있다."],"a":1}},{"y":2024,"e":"지방직 9급","qn":14,"i":"L92024-14-1","t":"면허를 받은 후에 면허유효기간의 종료, 면허의 취소, 그 밖에 이와 유사한 사유로 면허의 효력이 소멸한 경우에는 이미 납부한 등록면허세를 환급하지 아니한다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 등록면허세"},{"y":2024,"e":"지방직 9급","qn":14,"i":"L92024-14-2","t":"지방자치단체의 장은 면허증서를 발급받거나 송달받기 전에 등록면허세를 신고납부한 자가 면허신청을 철회하거나 그 밖의 사유로 해당 면허를 받지 못하게 된 경우에는 지방세기본법에 따른 지방세환급금의 처리절차에 따라 신고납부한 등록면허세에 지방세환급가산금을 가산하여 환급하여야 한다.","ox":"X","m":"②","c":"A","tp":"지방세법 상 등록면허세"},{"y":2024,"e":"지방직 9급","qn":14,"i":"L92024-14-3","t":"세무공무원이 등록면허세의 부과ㆍ징수를 위하여 면허의 부여ㆍ 변경ㆍ취소 또는 정지에 대한 관계 서류를 열람하거나 복사할 것을 청구하는 경우에는 관계 기관은 이에 따라야 한다.","ox":"O","m":"③","c":"A","tp":"지방세법 상 등록면허세"},{"y":2024,"e":"지방직 9급","qn":14,"i":"L92024-14-4","t":"면허의 부여기관이 면허를 부여하거나 변경하는 경우에는 등록 면허세의 납부 여부를 확인한 후 그 면허증서를 발급하거나 송달하여야 한다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 등록면허세"},{"y":2025,"e":"지방직 9급","qn":16,"i":"L92025-16-1","t":"지방세법 제15조제2항제4호에 따른 외국인 소유의 취득세 과세대상 물건(차량, 기계장비, 항공기 및 선박만 해당한다)의 연부 취득에 따른 등기 또는 등록은 등록면허세에서 사용하는 등록에 포함된다.","ox":"O","m":"①","c":"A","tp":"지방세법 상 등록면허세"},{"y":2025,"e":"지방직 9급","qn":16,"i":"L92025-16-2","t":"등록에 대한 등록면허세에 있어 같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다.","ox":"O","m":"②","c":"A","tp":"지방세법 상 등록면허세"},{"y":2025,"e":"지방직 9급","qn":16,"i":"L92025-16-3","t":"부동산, 선박, 항공기, 자동차 및 건설기계의 등록에 대한 등록 면허세의 과세표준은 취득 당시의 가액으로 한다.","ox":"X","m":"③","c":"A","tp":"지방세법 상 등록면허세"},{"y":2025,"e":"지방직 9급","qn":16,"i":"L92025-16-4","t":"등록에 대한 등록면허세에 있어 채권금액으로 과세액을 정하는 경우에 일정한 채권금액이 없을 때에는 채권의 목적이 된 것의 가액 또는 처분의 제한의 목적이 된 금액을 그 채권금액으로 본다.","ox":"O","m":"④","c":"A","tp":"지방세법 상 등록면허세"}]};
window.PAIRS=[{"n":1,"s":0.768,"o":{"i":"L92021-07-2","t":"지방세환급금의 소멸시효는 지방자치단체의 장이 납세자의 지방세 환급청구를 촉구하기 위하여 납세자에게 하는 지방세 환급청구의 안내·통지 등으로 인하여 중단되지 아니한다.","y":2021,"e":"지방직 9급"},"x":{"i":"L92025-15-4","t":"지방세환급금의 소멸시효는 지방자치단체의 장이 납세자의 지방세 환급청구를 촉구하기 위하여 납세자에게 하는 지방세 환급청구의 안내ㆍ통지 등으로 인하여 중단된다.","y":2025,"e":"지방직 9급"}},{"n":1,"s":0.701,"o":{"i":"L92017-10-4","t":"지방세기본법 또는 지방세관계법 중 과세표준 또는 세액의 계산에 관한 규정은 소득·수익·재산·행위 또는 거래의 명칭이나 형식에 관계없이 그 실질내용에 따라 적용한다.","y":2017,"e":"지방직 9급"},"x":{"i":"L92022-06-3","t":"지방세관계법 중 과세표준 또는 세액의 계산에 관한 규정은 소득·수익·재산·행위 또는 거래의 실질내용과 관계없이 그 명칭이나 형식에 따라 적용한다.","y":2022,"e":"지방직 9급"}},{"n":1,"s":0.7,"o":{"i":"L92016-13-4","t":"납세자가 세무조사를 신청하는 경우에는 지방자치단체의 장은 정기선정에 의한 조사 외에도 세무조사를 할 수 있다.","y":2016,"e":"지방직 9급"},"x":{"i":"L92024-06-4","t":"지방자치단체의 장은 정기선정에 의한 조사 외에 납세자가 세무 조사를 신청하는 경우에는 세무조사를 할 수 없다.","y":2024,"e":"지방직 9급"}},{"n":1,"s":0.661,"o":{"i":"L92020-05-2","t":"납세보증보험증권을 납세담보로 제공하려는 자는 그 보험증권을 지방자치단체의 장에게 제출하여야 한다.","y":2020,"e":"지방직 9급"},"x":{"i":"L92025-12-2","t":"납세보증보험증권을 납세담보로 제공하려는 자는 그 보험증권에 담보제공의 뜻을 등록하고 등록확인증을 지방자치단체의 장에게 제출하여야 한다.","y":2025,"e":"지방직 9급"}},{"n":7,"s":0.723,"o":{"i":"L92017-09-1","t":"특별징수의무자는 징수한 지방소비세를 다음 달 20일까지 관할 구역의 인구 등을 고려하여 대통령령으로 정하는 납입관리자에게 행정안전부령으로 정하는 징수명세서와 함께 납입하여야 한다.","y":2017,"e":"지방직 9급"},"x":{"i":"L92018-12-3","t":"특별징수의무자는 징수한 지방소비세를 다음 달 10일까지 관할구역의 인구 등을 고려하여 납입관리자에게 행정안전부령으로 정하는 징수명세서와 함께 납입하여야 한다.","y":2018,"e":"지방직 9급"}},{"n":7,"s":0.607,"o":{"i":"L92022-14-4","t":"지방소비세와 관련하여 지방세법 제6장(지방소비세)에 규정 되어 있지 아니한 사항에 관하여는 부가가치세법을 준용한다.","y":2022,"e":"지방직 9급"},"x":{"i":"L92023-04-4","t":"지방소비세와 관련하여 지방세법 제6장(지방소비세)에 규정되어 있지 아니한 사항에 관하여는 지방자치단체의 조례로 정한다.","y":2023,"e":"지방직 9급"}},{"n":7,"s":0.594,"o":{"i":"L92021-06-4","t":"지방소비세의 부과·징수 및 불복절차 등에 관하여는 국세의 예를 따르며, 이 경우 지방소비세 특별징수의무자를 그 처분청으로 본다.","y":2021,"e":"지방직 9급"},"x":{"i":"L92022-14-3","t":"지방소비세의 부과·징수 및 불복절차 등에 관하여는 지방세의 예를 따르며, 이 경우 지방자치단체의 장을 그 처분청으로 본다.","y":2022,"e":"지방직 9급"}},{"n":7,"s":0.491,"o":{"i":"L92019-07-2","t":"지방소비세의 세액은 부가가치세법에 따른 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 세액에 1천분의 253을 적용하여 계산한 금액으로 한다.","y":2019,"e":"지방직 9급"},"x":{"i":"L92015-03-2","t":"지방소비세는 부가가치세의 납부세액에서 부가가치세법 및 다른 법률에 따라 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더하여 계산한 금액의 1천분의 253으로 하며, 부가 가치세를 신고하지 않은 경우에도 지방소비세는 신고하여야 한다.","y":2015,"e":"지방직 9급"}},{"n":2,"s":0.613,"o":{"i":"L92019-20-3","t":"법인 설립 후 60 %의 주식을 가진 주주가 추가로 10 %의 주식을 취득하여 총 70 %의 주식을 소유하게 되었다면, 취득으로 간주되는 비율은 10 %이다.","y":2019,"e":"지방직 9급"},"x":{"i":"L92019-20-4","t":"법인 설립 후 60 %의 주식을 가진 주주가 15 %의 주식을 양도하여 총 45 %의 주식을 소유하던 중 추가로 10 %의 주식을 취득하여 총 55 %의 주식을 소유하게 되었다면, 취득으로 간주되는 비율은 5 %이다.","y":2019,"e":"지방직 9급"}},{"n":2,"s":0.383,"o":{"i":"L92016-04-2","t":"토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다.","y":2016,"e":"지방직 9급"},"x":{"i":"L92019-02-1","t":"토지의 지목을 사실상 변경한 경우에는 그 가액의 증가 여부에 관계없이 취득으로 본다.","y":2019,"e":"지방직 9급"}},{"n":2,"s":0.327,"o":{"i":"L92020-10-3","t":"건축물을 건축(신축과 재축은 제외)하거나 개수한 경우와 대통령령으로 정하는 선박, 차량 및 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경한 경우에는 그로 인하여 증가한 가액을 각각 과세표준으로 한다. 이 경우 신고 또는 신고가액의 표시가 없거나 신고가액이 대통령령으로 정하는 시가표준액보다 적을 때에는 그 시가표준액으로 한다.","y":2020,"e":"지방직 9급"},"x":{"i":"L92020-10-4","t":"국가, 지방자치단체 또는 지방자치단체조합으로부터 취득한 경우 신고 또는 신고가액의 표시가 없거나 신고가액이 대통령령으로 정하는 시가표준액보다 적을 때에는 그 시가 표준액으로 한다.","y":2020,"e":"지방직 9급"}},{"n":9,"s":0.702,"o":{"i":"L92015-15-4","t":"지역자원시설세로 징수할 세액이 고지서 1장당 2천원 미만인 경우에는 그 지역자원시설세를 징수하지 아니한다.","y":2015,"e":"지방직 9급"},"x":{"i":"L92024-15-4","t":"지방교육세로 징수할 세액이 고지서 1장당 2천원 미만인 경우에는 그 지방교육세를 징수하지 아니한다.","y":2024,"e":"지방직 9급"}},{"n":9,"s":0.682,"o":{"i":"L92019-16-1","t":"소방시설로 인하여 이익을 받는 자의 건축물은 지역자원시설세의 과세대상이다.","y":2019,"e":"지방직 9급"},"x":{"i":"L92018-18-1","t":"소방시설, 그 밖의 공공시설로 인하여 이익을 받는 자의 건축물은 지역자원시설세의 과세대상이 아니다.","y":2018,"e":"지방직 9급"}},{"n":9,"s":0.664,"o":{"i":"L92018-05-1","t":"지방자치단체의 장은 지방교육투자재원의 조달을 위하여 필요한 경우에는 해당 지방자치단체의 조례로 정하는 바에 따라 지방교육세의 세율을 지방세법 제151조제1항[같은 항제3호(지방세법 및 지방세감면법령에 따라 납부하여야 할 레저세액의 100분의 40)는 제외]의 표준세율의 100분의 50의 범위에서 가감할 수 있다.","y":2018,"e":"지방직 9급"},"x":{"i":"L92022-18-1","t":"지방자치단체의 장은 지방교육투자재원의 조달을 위하여 필요한 경우에는 해당 지방자치단체의 조례로 정하는 바에 따라 지방교육세의 세율을 표준세율(지방세법 및 지방세감면 법령에 따라 납부하여야 할 레저세의 경우 포함)의 100분의 50의 범위에서 가감할 수 있다.","y":2022,"e":"지방직 9급"}},{"n":9,"s":0.641,"o":{"i":"L92024-15-3","t":"지방교육세의 지방세환급금은 해당 지방자치단체의 장 또는 그 위임을 받은 공무원이 지방교육세의 과세표준이 되는 세목별 세액의 환급의 예에 따라 환급한다.","y":2024,"e":"지방직 9급"},"x":{"i":"L92022-18-2","t":"지방교육세의 지방세환급금은 해당 지방자치단체의 장 또는 그 위임을 받은 공무원이 지방자치단체의 조례에 따라 환급한다.","y":2022,"e":"지방직 9급"}},{"n":8,"s":0.648,"o":{"i":"L92019-03-2","t":"수입판매업자는 보세구역으로부터 반출한 담배에 대하여 담배소비세를 납부할 의무가 있다.","y":2019,"e":"지방직 9급"},"x":{"i":"L92020-14-2","t":"수입판매업자는 보세구역으로부터 반출한 담배에 대하여 담배소비세를 납부할 의무가 있고 이 경우 납세지는 세관 소재지로 한다.","y":2020,"e":"지방직 9급"}},{"n":8,"s":0.583,"o":{"i":"L92022-13-4","t":"납세담보의 제공을 요구받은 수입판매업자가 보세구역으로부터 담배를 반출하기 전에 미리 담배소비세를 신고납부하여 담보를 제공하지 아니한 경우, 담배소비세를 신고하는 때 납세의무가 성립한다.","y":2022,"e":"지방직 9급"},"x":{"i":"L92018-14-3","t":"납세담보의 제공을 요구받은 수입판매업자는 보세구역으로부터 담배를 반출하기 전에 미리 담배소비세를 신고납부하여 담보를 제공하지 아니할 수 있다. 이 경우 담배소비세의 납세의무는 담배를 보세구역으로부터 반출하는 때에 성립한다.","y":2018,"e":"지방직 9급"}},{"n":8,"s":0.567,"o":{"i":"L92016-05-2","t":"제조장에 있는 담배가 파산절차에 따라 환가되는 경우에는 제조자가 담배를 제조장에서 반출한 것으로 본다.","y":2016,"e":"지방직 9급"},"x":{"i":"L92023-12-4","t":"제조장에 있는 담배가 공매, 경매 또는 파산절차 등에 따라 환가되는 경우에는 제조자가 담배를 제조장에서 반출한 것으로 보지 아니한다.","y":2023,"e":"지방직 9급"}},{"n":8,"s":0.553,"o":{"i":"L92022-17-4","t":"레저세의 과세표준은 승자투표권, 승마투표권 등의 발매금 총액으로 한다.","y":2022,"e":"지방직 9급"},"x":{"i":"L92024-07-2","t":"레저세의 과세표준은 승자투표권, 승마투표권의 발매금총액 중 투표적중자에게 지급하는 환급금 총액으로 한다.","y":2024,"e":"지방직 9급"}},{"n":6,"s":0.683,"o":{"i":"L92019-10-2","t":"양도소득에 대한 개인지방소득세의 공제세액 또는 감면세액이 산출세액을 초과하는 경우에는 그 초과금액은 없는 것으로 한다.","y":2019,"e":"지방직 9급"},"x":{"i":"L92025-02-2","t":"종합소득에 대한 개인지방소득세의 공제세액 또는 감면세액이 산출세액을 초과하는 경우에는 그 초과금액은 이월공제된다.","y":2025,"e":"지방직 9급"}},{"n":6,"s":0.389,"o":{"i":"L92021-12-4","t":"지방세법 제103조의13, 제103조의29, 제103조의52에 따라 특별징수하는 지방소득세 중 국민건강보험법에 따른 국민 건강보험공단이 지급하는 사업소득에 대한 지방소득세는 그 소득을 지급받는 사람의 사업장 소재지를 관할하는 지방 자치단체의 장이 부과한다.","y":2021,"e":"지방직 9급"},"x":{"i":"L92017-18-2","t":"지방세법 제103조의13에 따라 특별징수하는 근로소득에 대한 지방소득세는 납세의무자의 주소지를 관할하는 지방자치단체의 장이 부과한다.","y":2017,"e":"지방직 9급"}},{"n":6,"s":0.324,"o":{"i":"L92017-18-3","t":"지방자치단체의 장은 조례로 정하는 바에 따라 종합소득에 대한 개인지방소득세의 세율을 지방세법 제92조제1항에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다.","y":2017,"e":"지방직 9급"},"x":{"i":"L92021-12-1","t":"거주자의 종합소득에 대한 개인지방소득세의 세율은 지방세법에서 따로 규정하고 있으며, 지방자치단체의 장이 조례로 정하는 바에 따라 가감할 수 없다.","y":2021,"e":"지방직 9급"}},{"n":10,"s":0.785,"o":{"i":"L92018-19-2","t":"지방자치단체의 장은 천재지변이나 그 밖에 대통령령으로 정하는 특수한 사유로 지방세 감면이 필요하다고 인정되는 자에 대해서는 해당 지방의회의 의결을 얻어 지방세 감면을 할 수 있다.","y":2018,"e":"지방직 9급"},"x":{"i":"L92024-20-2","t":"지방자치단체의 장은 천재지변이나 그 밖에 대통령령으로 정하는 특수한 사유로 지방세 감면이 필요하다고 인정되는 자에 대해서는 해당 지방자치단체장의 직권으로 지방세 감면을 할 수 있다.","y":2024,"e":"지방직 9급"}},{"n":10,"s":0.769,"o":{"i":"L92016-16-3","t":"지방자치단체의 장은 지방세 감면 등 지방세 특례에 따른 재정 지원의 직전 회계연도의 실적과 해당 회계연도의 추정 금액에 대한 보고서를 작성하여 지방의회에 제출하여야 한다.","y":2016,"e":"지방직 9급"},"x":{"i":"L92018-19-3","t":"지방자치단체의 장은 지방세 감면 등 지방세 특례에 따른 재정 지원의 직전 회계연도의 실적과 해당 회계연도의 추정 금액에 대한 보고서를 작성하여 행정안전부장관에게 제출 하여야 한다.","y":2018,"e":"지방직 9급"}},{"n":10,"s":0.759,"o":{"i":"L92024-16-4","t":"지방세의 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 지방세 감면 신청을 하여야 하지만, 지방자치단체의 장이 감면대상을 알 수 있을 때에는 직권으로 감면할 수 있다.","y":2024,"e":"지방직 9급"},"x":{"i":"L92017-06-4","t":"지방세의 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 지방세 감면 신청을 하여야 하고, 지방자치단체의 장이 감면대상을 알 수 있을 때에도 직권으로 감면할 수 없다.","y":2017,"e":"지방직 9급"}},{"n":10,"s":0.557,"o":{"i":"L92021-18-4","t":"지방자치단체는 지방세 감면에 관한 사항을 정비하여야 하며, 지방자치단체의 장은 정비 결과를 행정안전부장관에게 제출 하여야 한다.","y":2021,"e":"지방직 9급"},"x":{"i":"L92018-19-4","t":"지방자치단체의 장은 지방세 감면에 관한 사항을 정비하여야 하며, 그 정비 결과를 지방의회에게 제출하여야 한다.","y":2018,"e":"지방직 9급"}},{"n":5,"s":0.792,"o":{"i":"L92024-09-4","t":"과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매수인이 자동차세를 납부할 의무를 진다.","y":2024,"e":"지방직 9급"},"x":{"i":"L92021-11-1","t":"자동차 소유에 대한 자동차세의 경우 과세기준일 현재 공매되어 매수대금이 납부되었으나 매수인 명의로 소유권 이전등록을 하지 아니한 자동차에 대하여는 매도인이 자동차세를 납부할 의무를 진다.","y":2021,"e":"지방직 9급"}},{"n":5,"s":0.604,"o":{"i":"L92015-20-1","t":"자동차 주행에 대한 자동차세의 세율은 과세물품에 대한 교통·에너지·환경세액의 1천분의 360으로 하며, 교통·에너지·환경세율의 변동 등으로 조정이 필요하면 그 세율의 100분의 30의 범위에서 대통령령으로 정하는 바에 따라 가감 하여 조정할 수 있다.","y":2015,"e":"지방직 9급"},"x":{"i":"L92021-11-2","t":"자동차 주행에 대한 자동차세의 세율은 교통·에너지·환경세율의 변동 등으로 조정이 필요하면 그 세율의 100분의 50의 범위에서 조례로 정하는 바에 따라 가감하여 조정할 수 있다.","y":2021,"e":"지방직 9급"}}];
